function getBootstrapDataDir() {
  const baseDir = app.isPackaged ? path.dirname(app.getPath('exe')) : __dirname;
  const dir = path.join(baseDir, 'data');
  try {
    if (!fs.existsSync(dir)) {
      fs.mkdirSync(dir, { recursive: true });
    }
  } catch (_) {}
  return dir;
}

function readJsonFileSafe(filePath, fallback = null) {
  try {
    if (!fs.existsSync(filePath)) return fallback;
    const raw = fs.readFileSync(filePath, 'utf8');
    return JSON.parse(raw || 'null');
  } catch (_) {
    return fallback;
  }
}

function writeJsonFileSafe(filePath, value) {
  fs.mkdirSync(path.dirname(filePath), { recursive: true });
  fs.writeFileSync(filePath, JSON.stringify(value, null, 2), 'utf8');
}

function getOrCreateStableDeviceId() {
  const deviceIdPath = path.join(getBootstrapDataDir(), 'device-id.json');
  const saved = readJsonFileSafe(deviceIdPath, null);
  if (saved && typeof saved.deviceId === 'string' && saved.deviceId.trim()) {
    return saved.deviceId.trim();
  }
  const deviceId = `device_${Date.now()}_${Math.random().toString(36).slice(2, 12)}`;
  writeJsonFileSafe(deviceIdPath, { deviceId, savedAt: new Date().toISOString() });
  return deviceId;
}

// Helper function to get local datetime in YYYY-MM-DD HH:MM:SS format
function getLocalDateTime() {
  const now = new Date();
  const year = now.getFullYear();
  const month = String(now.getMonth() + 1).padStart(2, '0');
  const day = String(now.getDate()).padStart(2, '0');
  const hours = String(now.getHours()).padStart(2, '0');
  const minutes = String(now.getMinutes()).padStart(2, '0');
  const seconds = String(now.getSeconds()).padStart(2, '0');
  return `${year}-${month}-${day} ${hours}:${minutes}:${seconds}`;
}

function formatLocalDateTimeFromMs(ms) {
  const t = Number(ms);
  if (!Number.isFinite(t)) return getLocalDateTime();
  const now = new Date(t);
  const year = now.getFullYear();
  const month = String(now.getMonth() + 1).padStart(2, '0');
  const day = String(now.getDate()).padStart(2, '0');
  const hours = String(now.getHours()).padStart(2, '0');
  const minutes = String(now.getMinutes()).padStart(2, '0');
  const seconds = String(now.getSeconds()).padStart(2, '0');
  return `${year}-${month}-${day} ${hours}:${minutes}:${seconds}`;
}

// Helper function to handle foreign key constraint errors
function handleForeignKeyError(error, entityType = 'السجل') {
  if (error.message && error.message.includes('FOREIGN KEY constraint failed')) {
    const messages = {
      'حساب': {
        error: 'لا يمكن حذف هذا الحساب',
        reason: 'يوجد سجلات مرتبطة بهذا الحساب',
        details: 'الحساب مرتبط بسجلات في (سندات القبض، سندات الصرف، القيود اليومية، الأرصدة الافتتاحية، أو الفواتير). يجب حذف السجلات المرتبطة أولاً قبل حذف الحساب.'
      },
      'فرع': {
        error: 'لا يمكن حذف هذا الفرع',
        reason: 'يوجد سجلات مرتبطة بهذا الفرع',
        details: 'الفرع مرتبط بسجلات في (صلاحيات المستخدمين على الفروع، العملاء، الموردين، الحسابات، الصناديق الافتراضية، سندات القبض، سندات الصرف، الأرصدة الافتتاحية، القيود اليومية، فواتير البيع، فواتير الشراء، الأوردرات، أو الإقرارات الضريبية). يجب حذف السجلات المرتبطة أولاً قبل حذف الفرع.'
      },
      'عميل': {
        error: 'لا يمكن حذف هذا العميل',
        reason: 'يوجد سجلات مرتبطة بهذا العميل',
        details: 'العميل مرتبط بسجلات في (سندات القبض، سندات الصرف، القيود اليومية، الأرصدة الافتتاحية، فواتير البيع، أو الأوردرات). يجب حذف السجلات المرتبطة أولاً قبل حذف العميل.'
      },
      'مورد': {
        error: 'لا يمكن حذف هذا المورد',
        reason: 'يوجد سجلات مرتبطة بهذا المورد',
        details: 'المورد مرتبط بسجلات في (سندات القبض، سندات الصرف، القيود اليومية، الأرصدة الافتتاحية، فواتير الشراء، أو الأوردرات). يجب حذف السجلات المرتبطة أولاً قبل حذف المورد.'
      },
      'مستخدم': {
        error: 'لا يمكن حذف هذا المستخدم',
        reason: 'يوجد سجلات مرتبطة بهذا المستخدم',
        details: 'المستخدم مرتبط بسجلات قام بإنشائها أو تعديلها في النظام. يجب تعديل هذه السجلات أولاً قبل حذف المستخدم.'
      }
    };
    
    const msg = messages[entityType] || {
      error: `لا يمكن حذف ${entityType}`,
      reason: `يوجد سجلات مرتبطة بهذا ${entityType}`,
      details: `${entityType} مرتبط بسجلات أخرى في النظام. يجب حذف أو تعديل السجلات المرتبطة أولاً.`
    };
    
    return { 
      success: false, 
      error: msg.error,
      reason: msg.reason,
      details: msg.details
    };
  }
  return { success: false, error: error.message };
}

// متغير لتخزين معرف الجهاز الحالي (ثابت لكل جهاز)
const currentDeviceId = getOrCreateStableDeviceId();

const CLOUD_PRESENCE_ACTIVE_WINDOW_MS = 45000;

function normalizeCloudPresenceIdentity(payload = {}) {
  const userId = Number(payload?.userId || payload?.id || 0);
  const username = String(payload?.username || '').trim();
  const fullName = String(payload?.fullName || payload?.full_name || '').trim();
  const branchId = Number(payload?.branchId || payload?.branch_id || 0);
  return {
    userId: Number.isFinite(userId) && userId > 0 ? userId : null,
    username: username || null,
    fullName: fullName || null,
    branchId: Number.isFinite(branchId) && branchId > 0 ? branchId : null,
  };
}

async function ensureCloudPresenceTableReady() {
  if (!tursoSync.isSyncEnabled()) {
    return false;
  }
  const result = await tursoSync.executeOnTurso(`
    CREATE TABLE IF NOT EXISTS cloud_active_sessions (
      device_id TEXT PRIMARY KEY,
      user_id INTEGER,
      username TEXT,
      full_name TEXT,
      branch_id INTEGER,
      last_seen_at TEXT NOT NULL,
      connected_at TEXT NOT NULL,
      updated_at TEXT NOT NULL
    )
  `);
  if (!result?.success) {
    return false;
  }

  try {
    const columnsResult = await tursoSync.executeOnTurso('PRAGMA table_info(cloud_active_sessions)');
    const columnNames = Array.isArray(columnsResult?.result?.rows)
      ? columnsResult.result.rows.map((row) => String(row?.name || '').trim().toLowerCase()).filter(Boolean)
      : [];
    if (!columnNames.includes('branch_id')) {
      const addColumnResult = await tursoSync.executeOnTurso('ALTER TABLE cloud_active_sessions ADD COLUMN branch_id INTEGER');
      if (!addColumnResult?.success) {
        console.warn('[CloudPresence] branch_id migration warning:', addColumnResult?.error || 'unknown error');
      }
    }
    await tursoSync.executeOnTurso('CREATE INDEX IF NOT EXISTS idx_cloud_active_sessions_last_seen_at ON cloud_active_sessions(last_seen_at)');
  } catch (migrationError) {
    console.warn('[CloudPresence] ensureCloudPresenceTableReady migration warning:', migrationError.message);
  }

  return true;
}

async function cleanupStaleCloudPresenceRows() {
  if (!tursoSync.isSyncEnabled()) {
    return false;
  }
  await ensureCloudPresenceTableReady();
  const threshold = new Date(Date.now() - CLOUD_PRESENCE_ACTIVE_WINDOW_MS).toISOString();
  await tursoSync.executeOnTurso('DELETE FROM cloud_active_sessions WHERE last_seen_at < ?', [threshold]);
  return true;
}

async function clearCurrentCloudPresence() {
  if (!tursoSync.isSyncEnabled()) {
    return false;
  }
  await ensureCloudPresenceTableReady();
  await tursoSync.executeOnTurso('DELETE FROM cloud_active_sessions WHERE device_id = ?', [currentDeviceId]);
  return true;
}

function sanitizeUserMessageText(value = '') {
  return String(value ?? '')
    .replace(/\r\n/g, '\n')
    .replace(/\r/g, '\n')
    .trim();
}

function buildUserMessagePreview(value = '', maxLength = 96) {
  const normalized = sanitizeUserMessageText(value).replace(/\s+/g, ' ').trim();
  if (!normalized) {
    return '';
  }
  const safeMaxLength = Number.isFinite(Number(maxLength)) && Number(maxLength) > 12 ? Number(maxLength) : 96;
  if (normalized.length <= safeMaxLength) {
    return normalized;
  }
  return `${normalized.slice(0, safeMaxLength - 1).trim()}…`;
}

