function buildMessagingPresencePayload(authenticatedUser = {}) {
  return {
    userId: normalizePositiveId(authenticatedUser?.id, null),
    username: String(authenticatedUser?.username || '').trim(),
    fullName: String(authenticatedUser?.full_name || authenticatedUser?.username || '').trim(),
    branchId: normalizePositiveId(authenticatedUser?.branch_id || authenticatedUser?.login_branch_id || authenticatedUser?.default_branch_id, null),
  };
}

function getCloudPresenceSortTime(session = {}) {
  return Date.parse(session?.last_seen_at || session?.updated_at || session?.connected_at || '') || 0;
}

function isPresenceSessionActive(session = {}) {
  if (!session) return false;
  const lastSeen = Date.parse(session?.last_seen_at || '') || 0;
  return lastSeen > 0 && (Date.now() - lastSeen) <= CLOUD_PRESENCE_ACTIVE_WINDOW_MS;
}

async function getMessagingPresenceByUserId(event, payload = {}) {
  const authenticatedUser = getAuthenticatedUserFromEvent(event) || {};
  const presencePayload = {
    ...buildMessagingPresencePayload(authenticatedUser),
    ...(payload && typeof payload === 'object' && !Array.isArray(payload) ? payload : {}),
    summaryOnly: false,
  };
  let result = null;
  try {
    result = await getCloudPresenceStatus(event, presencePayload);
  } catch (_) {
    result = null;
  }
  const sessions = Array.isArray(result?.sessions) ? result.sessions : [];
  const presenceByUserId = new Map();
  for (const session of sessions) {
    const userId = normalizePositiveId(session?.user_id, null);
    if (!userId) {
      continue;
    }
    const existing = presenceByUserId.get(userId);
    if (!existing || getCloudPresenceSortTime(session) > getCloudPresenceSortTime(existing)) {
      presenceByUserId.set(userId, session);
    }
  }
  return presenceByUserId;
}

async function getCloudPresenceStatus(event, payload = {}) {
  const connected = tursoSync.isSyncEnabled();
  const activeMode = tursoSync.isCloudMode();
  if (!connected || !activeMode) {
    return { success: true, connected, activeMode, activeUsers: 0, sessions: [] };
  }

  await ensureCloudPresenceTableReady();
  await cleanupStaleCloudPresenceRows();

  const authenticatedUser = getAuthenticatedUserFromEvent(event);
  const identity = normalizeCloudPresenceIdentity(payload);
  const summaryOnly = payload?.summaryOnly === true;
  const now = new Date().toISOString();
  const resolvedBranchId = normalizePositiveId(
    identity.branchId
    || payload?.currentBranch?.id
    || payload?.branch_id
    || payload?.branchId
    || authenticatedUser?.branch_id
    || authenticatedUser?.login_branch_id,
    null
  );
  const upsertResult = await tursoSync.executeOnTurso(`
    INSERT OR REPLACE INTO cloud_active_sessions (
      device_id, user_id, username, full_name, branch_id, last_seen_at, connected_at, updated_at
    ) VALUES (
      ?, ?, ?, ?, ?, ?, COALESCE((SELECT connected_at FROM cloud_active_sessions WHERE device_id = ?), ?), ?
    )
  `, [
    currentDeviceId,
    identity.userId,
    identity.username,
    identity.fullName,
    resolvedBranchId,
    now,
    currentDeviceId,
    now,
    now,
  ]);
  if (!upsertResult?.success) {
    throw new Error(upsertResult?.error || 'Cloud presence update failed');
  }

  const activeThreshold = new Date(Date.now() - CLOUD_PRESENCE_ACTIVE_WINDOW_MS).toISOString();
  const countResult = await tursoSync.executeOnTurso(`
    SELECT COUNT(DISTINCT CASE
      WHEN user_id IS NOT NULL THEN 'u:' || CAST(user_id AS TEXT)
      ELSE 'd:' || device_id
    END) AS activeCount
    FROM cloud_active_sessions
    WHERE last_seen_at >= ?
  `, [activeThreshold]);
  if (!countResult?.success) {
    throw new Error(countResult?.error || 'Cloud presence count failed');
  }

  const activeUsers = Number(countResult?.result?.rows?.[0]?.activeCount || 0) || 0;

  if (summaryOnly) {
    return {
      success: true,
      connected,
      activeMode,
      activeUsers: Math.max(activeUsers, 1),
      deviceId: currentDeviceId,
      sessions: [],
      snapshotAt: now,
    };
  }

  const sessionsResult = await tursoSync.executeOnTurso(`
    WITH active_sessions AS (
      SELECT
        s.device_id,
        s.user_id,
        s.username,
        s.full_name,
        COALESCE(s.branch_id, (
          SELECT ub.branch_id
          FROM user_branches ub
          WHERE ub.user_id = s.user_id
            AND COALESCE(ub.can_login, 1) = 1
          ORDER BY COALESCE(ub.is_default, 0) DESC, ub.branch_id ASC
          LIMIT 1
        )) AS branch_id,
        s.last_seen_at,
        s.connected_at,
        s.updated_at
      FROM cloud_active_sessions s
      WHERE s.last_seen_at >= ?
    )
    SELECT
      a.device_id,
      a.user_id,
      a.username,
      a.full_name,
      a.branch_id,
      b.code AS branch_code,
      b.name AS branch_name,
      b.name_en AS branch_name_en,
      a.last_seen_at,
      a.connected_at,
      a.updated_at
    FROM active_sessions a
    LEFT JOIN branches b ON b.id = a.branch_id
    ORDER BY a.last_seen_at DESC, a.connected_at DESC, a.updated_at DESC, a.device_id ASC
  `, [activeThreshold]);

  const sessions = Array.isArray(sessionsResult?.result?.rows)
    ? sessionsResult.result.rows.map((row) => {
        const userId = Number(row?.user_id || 0);
        const deviceId = String(row?.device_id || '').trim();
        return {
          device_id: deviceId || null,
          user_id: userId > 0 ? userId : null,
          username: String(row?.username || '').trim() || null,
          full_name: String(row?.full_name || '').trim() || null,
          branch_id: Number(row?.branch_id || 0) > 0 ? Number(row.branch_id) : null,
          branch_code: String(row?.branch_code || '').trim() || null,
          branch_name: String(row?.branch_name || '').trim() || null,
          branch_name_en: String(row?.branch_name_en || '').trim() || null,
          last_seen_at: row?.last_seen_at || null,
          connected_at: row?.connected_at || null,
          updated_at: row?.updated_at || null,
        };
      }).filter((session) => String(session?.device_id || '').trim())
    : [];

  return {
    success: true,
    connected,
    activeMode,
    activeUsers: Math.max(activeUsers, 1),
    deviceId: currentDeviceId,
    sessions,
    snapshotAt: now,
  };
}

const CLOUD_REALTIME_EVENT_POLL_MS = 2000;
let cloudRealtimePollIntervalId = null;
let cloudRealtimePollInFlight = false;
let lastCloudRealtimeEventId = 0;

function normalizeCloudRealtimePayload(payload = {}) {
  const source = String(payload?.source || '').trim().toLowerCase();
  const action = String(payload?.action || 'sync').trim().toLowerCase() || 'sync';
  const tables = Array.isArray(payload?.tables)
    ? payload.tables.map((tableName) => String(tableName || '').trim()).filter(Boolean)
    : [];
  const entityType = String(payload?.entityType || '').trim();
  const documentId = Number(payload?.documentId || payload?.id || 0);
  const displayDocumentId = Number(
    payload?.displayDocumentId
    || payload?.displayNumber
    || payload?.branch_local_number
    || payload?.branchLocalNumber
    || payload?.manual_number
    || payload?.manualNumber
    || 0
  );
  const actorUserId = Number(payload?.actorUserId || 0);
  const changes = Number(payload?.changes || 0);
  const latestRows = payload?.latestRows && typeof payload.latestRows === 'object' ? payload.latestRows : {};
  return {
    source,
    action,
    tables,
    entityType,
    documentId: Number.isFinite(documentId) && documentId > 0 ? documentId : 0,
    displayDocumentId: Number.isFinite(displayDocumentId) && displayDocumentId > 0 ? displayDocumentId : 0,
    actorUserId: Number.isFinite(actorUserId) && actorUserId > 0 ? actorUserId : null,
    actorName: String(payload?.actorName || payload?.userName || '').trim(),
    originDeviceId: payload?.originDeviceId ? String(payload.originDeviceId).trim() : null,
    changes: Number.isFinite(changes) ? changes : 0,
    status: payload?.status == null ? null : String(payload.status),
    latestRows,
  };
}

async function ensureCloudRealtimeEventsTableReady() {
  await tursoSync.run(`
    CREATE TABLE IF NOT EXISTS cloud_realtime_events (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      source TEXT,
      action TEXT NOT NULL,
      tables_json TEXT,
      entity_type TEXT,
      document_id INTEGER,
      actor_user_id INTEGER,
      actor_name TEXT,
      origin_device_id TEXT,
      changes INTEGER DEFAULT 0,
      status TEXT,
      payload_json TEXT,
      created_at TEXT NOT NULL
    )
  `);
}

async function primeCloudRealtimeEventCursor() {
  if (!tursoSync.isCloudMode() || !tursoSync.isSyncEnabled()) {
    lastCloudRealtimeEventId = 0;
    return 0;
  }
  await ensureCloudRealtimeEventsTableReady();
  const row = await tursoSync.queryOne('SELECT COALESCE(MAX(id), 0) AS maxId FROM cloud_realtime_events');
  lastCloudRealtimeEventId = Number(row?.maxId || 0);
  return lastCloudRealtimeEventId;
}

async function enqueueCloudRealtimeEvent(payload = {}) {
  if (!tursoSync.isCloudMode() || !tursoSync.isSyncEnabled()) {
    return false;
  }
  const normalized = normalizeCloudRealtimePayload(payload);
  if (!normalized.tables.length && !normalized.entityType) {
    return false;
  }
  if (['cloud-event', 'cloud-pull', 'cloud-periodic'].includes(normalized.source)) {
    return false;
  }
  await ensureCloudRealtimeEventsTableReady();
  await tursoSync.run(
    `INSERT INTO cloud_realtime_events (
      source, action, tables_json, entity_type, document_id, actor_user_id,
      actor_name, origin_device_id, changes, status, payload_json, created_at
    ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
    [
      normalized.source || 'local',
      normalized.action,
      JSON.stringify(normalized.tables),
      normalized.entityType || null,
      normalized.documentId || null,
      normalized.actorUserId,
      normalized.actorName || null,
      normalized.originDeviceId || null,
      normalized.changes || 0,
      normalized.status || null,
      JSON.stringify(normalized),
      new Date().toISOString(),
    ]
  );
  return true;
}

async function pollCloudRealtimeEvents() {
  if (cloudRealtimePollInFlight) {
    return;
  }
  if (!tursoSync.isCloudMode() || !tursoSync.isSyncEnabled()) {
    return;
  }
  cloudRealtimePollInFlight = true;
  try {
    await ensureCloudRealtimeEventsTableReady();
    const rows = await tursoSync.queryAll(
      `SELECT id, payload_json, tables_json, entity_type, action, document_id,
              actor_user_id, actor_name, origin_device_id, changes, status, created_at
         FROM cloud_realtime_events
        WHERE id > ?
        ORDER BY id ASC
        LIMIT 100`,
      [lastCloudRealtimeEventId || 0]
    );
    for (const row of rows) {
      const eventId = Number(row?.id || 0);
      if (Number.isFinite(eventId) && eventId > lastCloudRealtimeEventId) {
        lastCloudRealtimeEventId = eventId;
      }
      if (row?.origin_device_id && String(row.origin_device_id) === currentDeviceId) {
        continue;
      }
      let parsedPayload = {};
      try {
        parsedPayload = row?.payload_json ? JSON.parse(row.payload_json) : {};
      } catch (_) {
        parsedPayload = {};
      }
      let parsedTables = [];
      try {
        parsedTables = row?.tables_json ? JSON.parse(row.tables_json) : [];
      } catch (_) {
        parsedTables = [];
      }
      const normalized = normalizeCloudRealtimePayload({
        ...parsedPayload,
        source: 'cloud-event',
        action: row?.action || parsedPayload?.action || 'sync',
        tables: Array.isArray(parsedTables) && parsedTables.length ? parsedTables : parsedPayload?.tables,
        entityType: row?.entity_type || parsedPayload?.entityType,
        documentId: Number(row?.document_id || parsedPayload?.documentId || parsedPayload?.id || 0),
        actorUserId: Number(row?.actor_user_id || parsedPayload?.actorUserId || 0),
        actorName: row?.actor_name || parsedPayload?.actorName || parsedPayload?.userName || '',
        originDeviceId: row?.origin_device_id || parsedPayload?.originDeviceId || null,
        changes: Number(row?.changes || parsedPayload?.changes || 0),
        status: row?.status || parsedPayload?.status || null,
      });
      broadcastCloudDataUpdated({
        ...normalized,
        eventId,
        timestamp: row?.created_at ? new Date(row.created_at).getTime() : Date.now(),
      });
    }
  } catch (error) {
    console.error('[Main] Cloud realtime poll error:', error.message);
  } finally {
    cloudRealtimePollInFlight = false;
  }
}

async function startCloudRealtimeEventPolling(options = {}) {
  stopCloudRealtimeEventPolling();
  if (!tursoSync.isCloudMode() || !tursoSync.isSyncEnabled()) {
    return false;
  }
  const intervalMs = Number(options?.intervalMs || CLOUD_REALTIME_EVENT_POLL_MS);
  if (options?.resetCursor !== false) {
    try {
      await primeCloudRealtimeEventCursor();
    } catch (error) {
      console.error('[Main] Cloud realtime cursor init error:', error.message);
    }
  }
  cloudRealtimePollIntervalId = setInterval(() => {
    pollCloudRealtimeEvents();
  }, Number.isFinite(intervalMs) && intervalMs > 0 ? intervalMs : CLOUD_REALTIME_EVENT_POLL_MS);
  return true;
}

function stopCloudRealtimeEventPolling() {
  if (cloudRealtimePollIntervalId) {
    clearInterval(cloudRealtimePollIntervalId);
    cloudRealtimePollIntervalId = null;
  }
  cloudRealtimePollInFlight = false;
}

async function broadcastCloudDataUpdated(payload = {}) {
  try {
    // لا ترسل إشعارات إذا كنا في الوضع المحلي
    if (!tursoSync.isCloudMode()) {
      console.log('[Main] Skipping broadcast - LOCAL mode active');
      return;
    }
    
    const source = String(payload?.source || '').toLowerCase();
    const resolvedDisplayDocumentId = await resolveBroadcastDisplayDocumentId(payload);
    const defaultOriginDeviceId = (source === 'cloud-periodic' || source === 'cloud-pull') ? null : currentDeviceId;
    // إضافة معرف الجهاز/المستخدم المنفذ للعملية
    const enrichedPayload = {
      ...payload,
      displayDocumentId: normalizePositiveId(payload?.displayDocumentId, null) || resolvedDisplayDocumentId || null,
      originDeviceId: payload.originDeviceId === undefined ? defaultOriginDeviceId : payload.originDeviceId,
      timestamp: Date.now()
    };
    
    console.log('[Main] Broadcasting cloud-data-updated:', JSON.stringify(enrichedPayload));
    const windows = BrowserWindow.getAllWindows();
    console.log(`[Main] Found ${windows.length} windows to broadcast to`);
    windows.forEach((win) => {
      try {
        if (!win || win.isDestroyed() || !win.webContents) return;
        win.webContents.send('cloud-data-updated', enrichedPayload);
        console.log('[Main] Sent cloud-data-updated to window');
      } catch (sendErr) { console.error('[Main] Send error:', sendErr.message); }
    });
    if (!['cloud-event', 'cloud-pull', 'cloud-periodic'].includes(source)) {
      enqueueCloudRealtimeEvent(enrichedPayload).catch((eventErr) => {
        console.error('[Main] Cloud realtime enqueue error:', eventErr.message);
      });
    }
  } catch (err) { console.error('[Main] Broadcast error:', err.message); }
}

// دالة للحصول على معرف الجهاز الحالي
function getCurrentDeviceId() {
  return currentDeviceId;
}

async function resolveUserDisplayNameById(userId) {
  const id = Number(userId);
  if (!Number.isFinite(id) || id <= 0) return '';
  try {
    const row = await tursoSync.queryOne('SELECT full_name, username FROM users WHERE id = ?', [id]);
    return String(row?.full_name || row?.username || '').trim();
  } catch (_) {
    return '';
  }
}

const NOTIFICATION_DISPLAY_DOCUMENT_SOURCES = {
  journal: { table: 'journal_entries', column: 'manual_number' },
  salesInvoice: { table: 'sales_invoices', column: 'branch_local_number' },
  purchaseInvoice: { table: 'purchase_invoices', column: 'branch_local_number' },
  receipt: { table: 'receipts', column: 'branch_local_number' },
  voucher: { table: 'vouchers', column: 'branch_local_number' },
  opening: { table: 'openings', column: 'branch_local_number' },
};

async function resolveBroadcastDisplayDocumentId(payload = {}) {
  const directDisplayId = normalizePositiveId(
    payload?.displayDocumentId
      ?? payload?.displayNumber
      ?? payload?.branch_local_number
      ?? payload?.branchLocalNumber
      ?? payload?.manual_number
      ?? payload?.manualNumber,
    null
  );
  if (directDisplayId) {
    return directDisplayId;
  }

  const entityType = String(payload?.entityType || '').trim();
  const sourceInfo = NOTIFICATION_DISPLAY_DOCUMENT_SOURCES[entityType];
  const documentId = normalizePositiveId(payload?.documentId ?? payload?.id, null);
  if (!sourceInfo || !documentId) {
    return 0;
  }

  try {
    const row = await tursoSync.queryOne(
      `SELECT ${sourceInfo.column} AS displayDocumentId FROM ${sourceInfo.table} WHERE id = ? LIMIT 1`,
      [documentId]
    );
    return normalizePositiveId(row?.displayDocumentId, null) || 0;
  } catch (_) {
    return 0;
  }
}

function parseDocumentRequestPayload(value) {
  const payload = value && typeof value === 'object' ? value : {};
  const primitiveId = normalizePositiveId(typeof value === 'object' ? 0 : value, null);
  const rawPayloadId = normalizePositiveId(payload?.id ?? payload?.documentId, null);
  const lookupByBranchLocalNumber = Number(payload?.lookupByBranchLocalNumber ?? payload?.useBranchLocalNumber ?? 0) === 1
    || payload?.idType === 'branch_local_number'
    || payload?.idKind === 'branch_local_number';
  const explicitInternalId = normalizePositiveId(
    payload?.internalId ?? payload?.documentInternalId ?? payload?.recordId ?? payload?.rowId ?? payload?.dbId ?? payload?.entityId,
    null
  );
  const branchLocalNumber = normalizePositiveId(
    payload?.branch_local_number
      ?? payload?.branchLocalNumber
      ?? payload?.document_number
      ?? payload?.documentNumber
      ?? payload?.manual_number
      ?? (lookupByBranchLocalNumber ? rawPayloadId : null),
    null
  );
  const id = explicitInternalId || (!lookupByBranchLocalNumber ? (rawPayloadId || primitiveId || 0) : (primitiveId || 0));
  return {
    id: Number.isFinite(id) && id > 0 ? id : 0,
    internalId: Number.isFinite(id) && id > 0 ? id : 0,
    branchLocalNumber,
    payload,
  };
}

async function resolveBroadcastActor(event, payload = {}, fallbackUserId = null, fallbackActorName = '') {
  const actorPayload = payload && typeof payload === 'object' ? payload : {};
  const authenticatedUser = getAuthenticatedUserFromEvent(event);
  const explicitActorUserId = Number(
    actorPayload?.actorUserId ||
    actorPayload?.userId ||
    actorPayload?.deleted_by ||
    actorPayload?.updated_by ||
    actorPayload?.modified_by ||
    actorPayload?.created_by ||
    0
  );
  const fallbackId = Number(fallbackUserId || 0);
  const actorUserId = Number(authenticatedUser?.id)
    || (Number.isFinite(explicitActorUserId) && explicitActorUserId > 0 ? explicitActorUserId : 0)
    || (Number.isFinite(fallbackId) && fallbackId > 0 ? fallbackId : 0)
    || null;

  let actorName = String(actorPayload?.actorName || actorPayload?.userName || fallbackActorName || '').trim();
  if (!actorName && actorUserId) {
    actorName = await resolveUserDisplayNameById(actorUserId);
  }

  return { actorUserId, actorName };
}

function normalizePositiveId(value, fallback = null) {
  const id = Number(value || 0);
  if (Number.isFinite(id) && id > 0) {
    return id;
  }
  return fallback;
}

function getDefaultMainBranchIdSync() {
  try {
    const mainBranch = db?.prepare?.('SELECT id FROM branches WHERE is_main = 1 ORDER BY id ASC LIMIT 1')?.get?.();
    if (Number(mainBranch?.id) > 0) {
      return Number(mainBranch.id);
    }
    const firstBranch = db?.prepare?.('SELECT id FROM branches ORDER BY id ASC LIMIT 1')?.get?.();
    if (Number(firstBranch?.id) > 0) {
      return Number(firstBranch.id);
    }
  } catch (_) {}
  return 1;
}

function ensureBranchLocalNumberingSync(tableName, options = {}) {
  try {
    const numberColumn = options.numberColumn || 'branch_local_number';
    const branchColumn = options.branchColumn || 'branch_id';
    const idColumn = options.idColumn || 'id';
    const orderBy = options.orderBy || `${idColumn} ASC`;
    const mainBranchId = getDefaultMainBranchIdSync();
    const columns = db.prepare(`PRAGMA table_info(${tableName})`).all();
    if (!columns.some((column) => column.name === numberColumn)) {
      db.prepare(`ALTER TABLE ${tableName} ADD COLUMN ${numberColumn} INTEGER`).run();
    }
    db.prepare(`
      UPDATE ${tableName}
      SET ${branchColumn} = ?
      WHERE ${branchColumn} IS NULL OR ${branchColumn} = 0
    `).run(mainBranchId);
    const rows = db.prepare(`
      SELECT ${idColumn} AS row_id, COALESCE(${branchColumn}, ?) AS branch_id
      FROM ${tableName}
      ORDER BY COALESCE(${branchColumn}, ?), ${orderBy}
    `).all(mainBranchId, mainBranchId);
    const updateNumberStatement = db.prepare(`UPDATE ${tableName} SET ${numberColumn} = ? WHERE ${idColumn} = ?`);
    const counters = new Map();
    rows.forEach((row) => {
      const branchId = normalizePositiveId(row?.branch_id, mainBranchId) || mainBranchId;
      const nextNumber = (counters.get(branchId) || 0) + 1;
      updateNumberStatement.run(nextNumber, row?.row_id);
      counters.set(branchId, nextNumber);
    });
    db.prepare(`CREATE UNIQUE INDEX IF NOT EXISTS uq_${tableName}_${branchColumn}_${numberColumn} ON ${tableName}(${branchColumn}, ${numberColumn})`).run();
    db.prepare(`CREATE INDEX IF NOT EXISTS idx_${tableName}_${numberColumn} ON ${tableName}(${numberColumn})`).run();
  } catch (error) {
    console.warn(`Branch local numbering migration for ${tableName}:`, error.message);
  }
}

function ensureJournalManualNumberingSync() {
  try {
    const mainBranchId = getDefaultMainBranchIdSync();
    const columns = db.prepare('PRAGMA table_info(journal_entries)').all();

    if (!columns.some((column) => column.name === 'manual_number')) {
      db.prepare('ALTER TABLE journal_entries ADD COLUMN manual_number INTEGER').run();
    }
    if (!columns.some((column) => column.name === 'branch_id')) {
      db.prepare('ALTER TABLE journal_entries ADD COLUMN branch_id INTEGER DEFAULT 1').run();
    }

    db.prepare(`
      UPDATE journal_entries
      SET branch_id = ?
      WHERE branch_id IS NULL OR branch_id = 0
    `).run(mainBranchId);

    const rows = db.prepare(`
      SELECT id AS row_id, COALESCE(branch_id, ?) AS branch_id
      FROM journal_entries
      WHERE (is_auto = 0 OR is_auto IS NULL)
      ORDER BY COALESCE(branch_id, ?), id ASC
    `).all(mainBranchId, mainBranchId);

    const updateNumberStatement = db.prepare('UPDATE journal_entries SET manual_number = ? WHERE id = ?');
    const counters = new Map();
    rows.forEach((row) => {
      const branchId = normalizePositiveId(row?.branch_id, mainBranchId) || mainBranchId;
      const nextNumber = (counters.get(branchId) || 0) + 1;
      updateNumberStatement.run(nextNumber, row?.row_id);
      counters.set(branchId, nextNumber);
    });

    db.prepare(`CREATE UNIQUE INDEX IF NOT EXISTS uq_journal_entries_branch_id_manual_number ON journal_entries(branch_id, manual_number) WHERE manual_number IS NOT NULL`).run();
    db.prepare('CREATE INDEX IF NOT EXISTS idx_journal_entries_branch_id_manual_number ON journal_entries(branch_id, manual_number)').run();
  } catch (error) {
    console.warn('Journal manual numbering migration:', error.message);
  }
}

async function getNextBranchLocalNumber(tableName, branchId, options = {}) {
  const mainBranchId = options.mainBranchId || getDefaultMainBranchIdSync();
  const numberColumn = options.numberColumn || 'branch_local_number';
  const branchColumn = options.branchColumn || 'branch_id';
  const rows = await tursoSync.queryAll(`
    SELECT ${numberColumn} AS seq
    FROM ${tableName}
    WHERE COALESCE(${branchColumn}, ?) = ?
      AND ${numberColumn} IS NOT NULL
    ORDER BY ${numberColumn} ASC
  `, [mainBranchId, branchId]);
  let nextNumber = 1;
  for (const row of rows) {
    const current = Number(row?.seq || 0);
    if (!Number.isFinite(current) || current <= 0) {
      continue;
    }
    if (current === nextNumber) {
      nextNumber += 1;
      continue;
    }
    if (current > nextNumber) {
      break;
    }
  }
  return nextNumber;
}

async function resolveBranchLocalNumberForInsert(tableName, branchId, requestedNumber, options = {}) {
  const mainBranchId = options.mainBranchId || getDefaultMainBranchIdSync();
  const numberColumn = options.numberColumn || 'branch_local_number';
  const branchColumn = options.branchColumn || 'branch_id';
  const explicitNumber = normalizePositiveId(requestedNumber, null);
  if (!explicitNumber) {
    return getNextBranchLocalNumber(tableName, branchId, { mainBranchId, numberColumn, branchColumn });
  }
  const existing = await tursoSync.queryOne(`
    SELECT id
    FROM ${tableName}
    WHERE COALESCE(${branchColumn}, ?) = ?
      AND ${numberColumn} = ?
    LIMIT 1
  `, [mainBranchId, branchId, explicitNumber]);
  if (existing) {
    throw new Error('الرقم التسلسلي مستخدم بالفعل في هذا الفرع');
  }
  return explicitNumber;
}

async function resolveBranchScopedDocumentId(tableName, requestInfo, branchId, options = {}) {
  const mainBranchId = options.mainBranchId || getDefaultMainBranchIdSync();
  const idColumn = options.idColumn || 'id';
  const numberColumn = options.numberColumn || 'branch_local_number';
  const branchColumn = options.branchColumn || 'branch_id';
  const internalId = normalizePositiveId(requestInfo?.internalId ?? requestInfo?.id, 0);
  if (internalId) {
    return internalId;
  }
  const branchLocalNumber = normalizePositiveId(requestInfo?.branchLocalNumber, 0);
  if (!branchLocalNumber) {
    return 0;
  }
  const scopedBranchIds = normalizeBranchIdList(Array.isArray(branchId) ? branchId : [branchId]);
  const effectiveBranchIds = scopedBranchIds.length
    ? scopedBranchIds
    : [normalizePositiveId(mainBranchId, getDefaultMainBranchIdSync()) || getDefaultMainBranchIdSync()];
  const placeholders = effectiveBranchIds.map(() => '?').join(', ');
  const row = await tursoSync.queryOne(`
    SELECT ${idColumn} AS id
    FROM ${tableName}
    WHERE COALESCE(${branchColumn}, ?) IN (${placeholders})
      AND ${numberColumn} = ?
    ORDER BY ${idColumn} DESC
    LIMIT 1
  `, [mainBranchId, ...effectiveBranchIds, branchLocalNumber]);
  return normalizePositiveId(row?.id, 0);
}

const READ_ONLY_BRANCH_MESSAGE = 'صلاحيتك في الفرع الحالي للقراءة فقط، يمكنك العرض فقط دون إضافة أو تعديل أو حذف أي حركة';

async function listUserAccessibleBranches(userId, options = {}) {
  const normalizedUserId = normalizePositiveId(userId, 0);
  if (!normalizedUserId) {
    return [];
  }

  const activeOnly = options?.activeOnly !== false;
  const canLoginOnly = options?.canLoginOnly !== false;
  const conditions = ['ub.user_id = ?'];
  const params = [normalizedUserId];

  if (activeOnly) {
    conditions.push('COALESCE(b.active, 1) = 1');
  }
  if (canLoginOnly) {
    conditions.push('COALESCE(ub.can_login, 1) = 1');
  }

  const rows = await tursoSync.queryAll(`
    SELECT b.id, b.code, b.name, b.name_en, b.address, b.phone,
           COALESCE(b.active, 1) AS active,
           COALESCE(b.is_main, 0) AS is_main,
           COALESCE(ub.is_default, 0) AS is_default,
           COALESCE(ub.can_login, 1) AS can_login,
           COALESCE(ub.read_only, 0) AS read_only
    FROM user_branches ub
    JOIN branches b ON b.id = ub.branch_id
    WHERE ${conditions.join(' AND ')}
    ORDER BY COALESCE(ub.is_default, 0) DESC, COALESCE(b.is_main, 0) DESC, b.name COLLATE NOCASE ASC, b.id ASC
  `, params);

  return rows.map((row) => ({
    ...row,
    id: Number(row?.id || 0) || 0,
    active: Number(row?.active || 0) || 0,
    is_main: Number(row?.is_main || 0) || 0,
    is_default: Number(row?.is_default || 0) || 0,
    can_login: Number(row?.can_login || 0) || 0,
    read_only: Number(row?.read_only || 0) || 0,
  }));
}

async function getUserDefaultBranch(userId, options = {}) {
  const branches = await listUserAccessibleBranches(userId, options);
  return branches.find((branch) => Number(branch?.is_default || 0) === 1)
    || branches.find((branch) => Number(branch?.is_main || 0) === 1)
    || branches[0]
    || null;
}

function normalizeSessionBranchAssignments(branches = []) {
  if (!Array.isArray(branches)) {
    return [];
  }
  return branches
    .map((branch) => {
      const branchId = normalizePositiveId(branch?.id || branch?.branch_id, null);
      if (!branchId) {
        return null;
      }
      return {
        ...branch,
        id: branchId,
        branch_id: branchId,
        code: String(branch?.code || '').trim(),
        name: String(branch?.name || '').trim(),
        name_en: String(branch?.name_en || '').trim(),
        active: Number(branch?.active || 0) === 1 ? 1 : 0,
        is_main: Number(branch?.is_main || 0) === 1 ? 1 : 0,
        is_default: Number(branch?.is_default || 0) === 1 ? 1 : 0,
        can_login: Number(branch?.can_login ?? 1) === 1 ? 1 : 0,
        read_only: Number(branch?.read_only || 0) === 1 ? 1 : 0,
      };
    })
    .filter(Boolean);
}

function buildAuthenticatedSessionRecord(user = {}, options = {}) {
  const branch = options?.branch || null;
  const branchId = normalizePositiveId(options?.branchId ?? branch?.id ?? user?.branch_id, null);
  const allowedBranchIds = Array.isArray(options?.allowedBranchIds)
    ? options.allowedBranchIds.map((value) => normalizePositiveId(value, null)).filter((value) => Number.isFinite(value) && value > 0)
    : [];
  const allowedBranches = normalizeSessionBranchAssignments(options?.allowedBranches ?? user?.allowed_branches);
  const branchReadOnly = Number(
    options?.branchReadOnly
    ?? branch?.read_only
    ?? user?.branch_read_only
    ?? allowedBranches.find((item) => Number(item?.id || 0) === Number(branchId || 0))?.read_only
    ?? 0
  ) === 1 ? 1 : 0;

  return {
    id: normalizePositiveId(user?.id, null),
    role: String(user?.role || '').trim().toLowerCase(),
    username: String(user?.username || '').trim(),
    full_name: String(user?.full_name || '').trim(),
    branch_id: branchId,
    login_branch_id: normalizePositiveId(user?.login_branch_id ?? branchId, branchId),
    default_branch_id: normalizePositiveId(options?.defaultBranchId ?? user?.default_branch_id ?? branchId, branchId),
    allowed_branch_ids: allowedBranchIds,
    allowed_branches: allowedBranches,
    branch_read_only: branchReadOnly,
    read_only_branch_ids: allowedBranches.filter((item) => Number(item?.read_only || 0) === 1).map((item) => Number(item.id)),
  };
}
function getAllowedBranchIdsForAuthenticatedUser(user = {}, fallbackBranchId = null) {
  const allowedBranchIds = normalizeBranchIdList(user?.allowed_branch_ids);
  if (allowedBranchIds.length) {
    return allowedBranchIds;
  }
  const fallback = normalizePositiveId(user?.branch_id || user?.default_branch_id || fallbackBranchId, null);
  return fallback ? [fallback] : [];
}

async function getUserBranchAccessRecord(userId, branchId) {
  const normalizedUserId = normalizePositiveId(userId, null);
  const normalizedBranchId = normalizePositiveId(branchId, null);
  if (!normalizedUserId || !normalizedBranchId) {
    return null;
  }
  const row = await tursoSync.queryOne(`
    SELECT ub.user_id, ub.branch_id,
           COALESCE(ub.is_default, 0) AS is_default,
           COALESCE(ub.can_login, 1) AS can_login,
           COALESCE(ub.read_only, 0) AS read_only,
           b.code AS branch_code,
           b.name AS branch_name,
           b.name_en AS branch_name_en,
           COALESCE(b.active, 1) AS branch_active
    FROM user_branches ub
    LEFT JOIN branches b ON b.id = ub.branch_id
    WHERE ub.user_id = ? AND ub.branch_id = ?
    LIMIT 1
  `, [normalizedUserId, normalizedBranchId]);
  if (!row) {
    return null;
  }
  return {
    ...row,
    user_id: normalizePositiveId(row?.user_id, null),
    branch_id: normalizePositiveId(row?.branch_id, null),
    is_default: Number(row?.is_default || 0) === 1 ? 1 : 0,
    can_login: Number(row?.can_login ?? 1) === 1 ? 1 : 0,
    read_only: Number(row?.read_only || 0) === 1 ? 1 : 0,
    branch_code: String(row?.branch_code || '').trim(),
    branch_name: String(row?.branch_name || '').trim(),
    branch_name_en: String(row?.branch_name_en || '').trim(),
    branch_active: Number(row?.branch_active || 0) === 1 ? 1 : 0,
  };
}

function buildReadOnlyBranchDeniedResponse(branchAccess = null) {
  return {
    success: false,
    error: READ_ONLY_BRANCH_MESSAGE,
    branchReadOnly: true,
    details: {
      branchId: normalizePositiveId(branchAccess?.branch_id, null),
      branchCode: String(branchAccess?.branch_code || '').trim() || null,
      branchName: String(branchAccess?.branch_name || branchAccess?.branch_name_en || '').trim() || null,
      readOnly: true,
    },
  };
}

async function ensureAuthenticatedUserCanMutateBranch(event, branchId) {
  const normalizedBranchId = normalizePositiveId(branchId, null);
  const authenticatedUser = getAuthenticatedUserFromEvent(event);
  const userId = normalizePositiveId(authenticatedUser?.id, null);
  if (!normalizedBranchId || !userId) {
    return { allowed: true, branchId: normalizedBranchId, authenticatedUser, branchAccess: null };
  }
  const branchAccess = await getUserBranchAccessRecord(userId, normalizedBranchId);
  if (!branchAccess) {
    return { allowed: true, branchId: normalizedBranchId, authenticatedUser, branchAccess: null };
  }
  if (Number(branchAccess.read_only || 0) === 1) {
    return {
      allowed: false,
      branchId: normalizedBranchId,
      authenticatedUser,
      branchAccess,
      response: buildReadOnlyBranchDeniedResponse(branchAccess),
    };
  }
  return { allowed: true, branchId: normalizedBranchId, authenticatedUser, branchAccess };
}

function getAllowedBranchIdsFromRequestPayload(payload = {}, fallbackBranchId = null) {
  const requestPayload = payload && typeof payload === 'object' ? payload : {};
  const branchScopePayload = requestPayload?.branchScope && typeof requestPayload.branchScope === 'object' && !Array.isArray(requestPayload.branchScope)
    ? requestPayload.branchScope
    : {};
  const explicitValues = Array.isArray(requestPayload?.allowedBranchIds)
    ? requestPayload.allowedBranchIds
    : (Array.isArray(requestPayload?.allowed_branch_ids) ? requestPayload.allowed_branch_ids : []);
  const explicitBranchIds = normalizeBranchIdList(explicitValues);
  if (explicitBranchIds.length) {
    return explicitBranchIds;
  }
  const scopedBranchIds = normalizeBranchIdList(
    Array.isArray(branchScopePayload?.allowedBranchIds)
      ? branchScopePayload.allowedBranchIds
      : (Array.isArray(branchScopePayload?.allowed_branch_ids) ? branchScopePayload.allowed_branch_ids : [])
  );
  if (scopedBranchIds.length) {
    return scopedBranchIds;
  }
  const currentUserBranchIds = normalizeBranchIdList(Array.isArray(requestPayload?.currentUser?.allowed_branch_ids) ? requestPayload.currentUser.allowed_branch_ids : []);
  if (currentUserBranchIds.length) {
    return currentUserBranchIds;
  }
  const fallback = normalizePositiveId(
    requestPayload?.branch_id || requestPayload?.branchId || requestPayload?.selectedBranchId || branchScopePayload?.branchId || branchScopePayload?.branch_id || requestPayload?.currentBranch?.id || fallbackBranchId,
    null
  );
  return fallback ? [fallback] : [];
}

async function resolveBranchScopeForRequest(event, payload = {}, fallbackBranchId = null) {
  const requestPayload = payload && typeof payload === 'object' ? payload : {};
  const branchScopePayload = requestPayload?.branchScope && typeof requestPayload.branchScope === 'object' && !Array.isArray(requestPayload.branchScope)
    ? requestPayload.branchScope
    : {};
  const branchId = await resolveBranchIdForRequest(event, requestPayload, fallbackBranchId);
  const authenticatedUser = getAuthenticatedUserFromEvent(event);
  const authenticatedAllowedBranchIds = getAllowedBranchIdsForAuthenticatedUser(authenticatedUser, null);
  const payloadAllowedBranchIds = getAllowedBranchIdsFromRequestPayload(requestPayload, branchId || fallbackBranchId);
  const allowedBranchIds = authenticatedAllowedBranchIds.length ? authenticatedAllowedBranchIds : payloadAllowedBranchIds;
  const explicitScopeValue = typeof requestPayload?.branchScope === 'string' ? requestPayload.branchScope : requestPayload?.branch_scope;
  const requestedScope = String(branchScopePayload?.mode || branchScopePayload?.scope || explicitScopeValue || '').trim().toLowerCase();
  const isAllBranches = requestedScope === 'all' && allowedBranchIds.length > 1;
  return {
    branchId,
    allowedBranchIds: allowedBranchIds.length ? allowedBranchIds : normalizeBranchIdList([branchId]),
    isAllBranches,
  };
}

async function resolveBranchIdForRequest(event, payload = {}, fallbackBranchId = null) {
  const requestPayload = payload && typeof payload === 'object' ? payload : {};
  const branchScopePayload = requestPayload?.branchScope && typeof requestPayload.branchScope === 'object' && !Array.isArray(requestPayload.branchScope)
    ? requestPayload.branchScope
    : {};
  const authenticatedUser = getAuthenticatedUserFromEvent(event);
  const authenticatedAllowedBranchIds = getAllowedBranchIdsForAuthenticatedUser(authenticatedUser, null);
  const payloadAllowedBranchIds = getAllowedBranchIdsFromRequestPayload(requestPayload, fallbackBranchId);
  const allowedBranchIds = authenticatedAllowedBranchIds.length ? authenticatedAllowedBranchIds : payloadAllowedBranchIds;
  const payloadBranchId = normalizePositiveId(
    requestPayload?.branch_id || requestPayload?.branchId || requestPayload?.selectedBranchId || branchScopePayload?.branchId || branchScopePayload?.branch_id || requestPayload?.currentBranch?.id,
    null
  );
  if (payloadBranchId) {
    if (!allowedBranchIds.length || allowedBranchIds.includes(payloadBranchId)) {
      return payloadBranchId;
    }
    return allowedBranchIds[0];
  }

  const authenticatedBranchId = normalizePositiveId(authenticatedUser?.branch_id, null);
  if (authenticatedBranchId && (!allowedBranchIds.length || allowedBranchIds.includes(authenticatedBranchId))) {
    return authenticatedBranchId;
  }

  const fallbackResolved = normalizePositiveId(fallbackBranchId, getDefaultMainBranchIdSync()) || getDefaultMainBranchIdSync();
  if (allowedBranchIds.length) {
    return allowedBranchIds.includes(fallbackResolved) ? fallbackResolved : allowedBranchIds[0];
  }
  return fallbackResolved;
}

function normalizeBranchIdList(values = []) {
  if (!Array.isArray(values)) {
    return [];
  }
  const unique = new Set();
  values.forEach((value) => {
    const normalized = normalizePositiveId(value, null);
    if (normalized) {
      unique.add(normalized);
    }
  });
  return Array.from(unique);
}

function normalizeReportsBranchWindowContext(payload = {}) {
  const requestPayload = payload && typeof payload === 'object' ? payload : {};
  const branchScopePayload = requestPayload?.branchScope && typeof requestPayload.branchScope === 'object' && !Array.isArray(requestPayload.branchScope)
    ? requestPayload.branchScope
    : {};
  const currentBranch = requestPayload?.currentBranch && typeof requestPayload.currentBranch === 'object' && !Array.isArray(requestPayload.currentBranch)
    ? requestPayload.currentBranch
    : {};
  const currentUser = requestPayload?.currentUser && typeof requestPayload.currentUser === 'object' && !Array.isArray(requestPayload.currentUser)
    ? requestPayload.currentUser
    : {};
  const explicitScopeValue = typeof requestPayload?.branchScope === 'string' ? requestPayload.branchScope : requestPayload?.branch_scope;
  const requestedBranchId = normalizePositiveId(
    requestPayload?.branchId || requestPayload?.branch_id || requestPayload?.selectedBranchId || branchScopePayload?.branchId || branchScopePayload?.branch_id || currentBranch?.id || currentUser?.branch_id || currentUser?.default_branch_id,
    getDefaultMainBranchIdSync()
  ) || getDefaultMainBranchIdSync();
  let allowedBranchIds = getAllowedBranchIdsFromRequestPayload(requestPayload, requestedBranchId);
  if (!allowedBranchIds.length) {
    allowedBranchIds = normalizeBranchIdList(
      Array.isArray(branchScopePayload?.allowedBranchIds)
        ? branchScopePayload.allowedBranchIds
        : (Array.isArray(branchScopePayload?.allowed_branch_ids) ? branchScopePayload.allowed_branch_ids : [requestedBranchId])
    );
  }
  const effectiveAllowedBranchIds = allowedBranchIds.length ? allowedBranchIds : normalizeBranchIdList([requestedBranchId]);
  const branchId = effectiveAllowedBranchIds.includes(requestedBranchId)
    ? requestedBranchId
    : (effectiveAllowedBranchIds[0] || requestedBranchId);
  const branchInfo = requestPayload?.branch && typeof requestPayload.branch === 'object' && !Array.isArray(requestPayload.branch)
    ? requestPayload.branch
    : currentBranch;
  return {
    branchScopeMode: String(branchScopePayload?.mode || branchScopePayload?.scope || explicitScopeValue || '').trim().toLowerCase() === 'all' && effectiveAllowedBranchIds.length > 1
      ? 'all'
      : 'branch',
    branchId,
    allowedBranchIds: effectiveAllowedBranchIds,
    branchCode: String(requestPayload?.branchCode || requestPayload?.branch_code || branchInfo?.code || '').trim(),
    branchName: String(requestPayload?.branchName || requestPayload?.branch_name || branchInfo?.name || branchInfo?.name_en || '').trim(),
  };
}

function getEffectiveBranchIdsForScope(scopeInfo = {}, fallbackBranchId = null) {
  const fallback = normalizePositiveId(fallbackBranchId, getDefaultMainBranchIdSync()) || getDefaultMainBranchIdSync();
  const scopeBranchIds = scopeInfo?.isAllBranches
    ? normalizeBranchIdList(scopeInfo?.allowedBranchIds)
    : normalizeBranchIdList([scopeInfo?.branchId || fallback]);
  return scopeBranchIds.length ? scopeBranchIds : [fallback];
}

function buildCoalescedBranchWhereClause(columnExpression, branchIds = [], mainBranchId = null) {
  const fallbackBranchId = normalizePositiveId(mainBranchId, getDefaultMainBranchIdSync()) || getDefaultMainBranchIdSync();
  const normalizedBranchIds = normalizeBranchIdList(branchIds);
  const effectiveBranchIds = normalizedBranchIds.length ? normalizedBranchIds : [fallbackBranchId];
  const placeholders = effectiveBranchIds.map(() => '?').join(', ');
  const includesFallbackBranch = effectiveBranchIds.includes(fallbackBranchId);
  return {
    sql: includesFallbackBranch
      ? `(${columnExpression} IS NULL OR ${columnExpression} IN (${placeholders}))`
      : `${columnExpression} IN (${placeholders})`,
    params: effectiveBranchIds,
  };
}

function buildSystemOrBranchWhereClause(alias, branchIds = [], mainBranchId = null) {
  const fallbackBranchId = normalizePositiveId(mainBranchId, 1) || 1;
  const normalizedBranchIds = normalizeBranchIdList(branchIds);
  const effectiveBranchIds = normalizedBranchIds.length ? normalizedBranchIds : [fallbackBranchId];
  const placeholders = effectiveBranchIds.map(() => '?').join(', ');
  return {
    sql: `(COALESCE(${alias}.is_system, 0) = 1 OR COALESCE(${alias}.is_parent, 0) = 1 OR ${alias}.branch_id IS NULL OR ${alias}.branch_id IN (${placeholders}))`,
    params: effectiveBranchIds,
  };
}

const COMPANY_INFO_BRANCH_FIELD_MAP = [
  ['name', 'company_name'],
  ['name_en', 'company_name_en'],
  ['address', 'company_address'],
  ['address_en', 'company_address_en'],
  ['tax', 'company_tax'],
  ['phone', 'company_phone'],
  ['email', 'company_email'],
  ['website', 'company_website'],
  ['logo', 'company_logo'],
  ['logo_base64', 'company_logo_base64'],
];

function normalizeOptionalString(value) {
  const text = String(value ?? '').trim();
  if (text) {
    return text;
  }
  return null;
}

function firstNonEmptyString(...values) {
  for (const value of values) {
    const text = String(value ?? '').trim();
    if (text) {
      return text;
    }
  }
  return null;
}

async function readDefaultCompanyInfo() {
  return await tursoSync.queryOne(`
    SELECT id, name, name_en, address, address_en, tax, phone, email, website, logo, logo_base64
    FROM company
    WHERE id = 1
  `);
}

async function readBranchCompanyInfo(branchId) {
  const normalizedBranchId = normalizePositiveId(branchId, null);
  if (!normalizedBranchId) {
    return null;
  }
  return await tursoSync.queryOne(`
    SELECT id, code, name, name_en,
           company_name, company_name_en, company_address, company_address_en,
           company_tax, company_phone, company_email, company_website,
           company_logo, company_logo_base64
    FROM branches
    WHERE id = ?
    LIMIT 1
  `, [normalizedBranchId]);
}

function mergeCompanyInfoRecords(defaultCompany = {}, branchCompany = {}, branchId = null) {
  const resolvedBranchId = normalizePositiveId(branchId || branchCompany?.id, null);
  const merged = {
    id: 1,
    branch_id: resolvedBranchId,
    branch_code: normalizeOptionalString(branchCompany?.code),
    branch_name: normalizeOptionalString(branchCompany?.name),
    branch_name_en: normalizeOptionalString(branchCompany?.name_en),
    name: firstNonEmptyString(branchCompany?.company_name, defaultCompany?.name) || '',
    name_en: firstNonEmptyString(branchCompany?.company_name_en, defaultCompany?.name_en) || '',
    address: firstNonEmptyString(branchCompany?.company_address, defaultCompany?.address) || '',
    address_en: firstNonEmptyString(branchCompany?.company_address_en, defaultCompany?.address_en) || '',
    tax: firstNonEmptyString(branchCompany?.company_tax, defaultCompany?.tax) || '',
    phone: firstNonEmptyString(branchCompany?.company_phone, defaultCompany?.phone) || '',
    email: firstNonEmptyString(branchCompany?.company_email, defaultCompany?.email) || '',
    website: firstNonEmptyString(branchCompany?.company_website, defaultCompany?.website) || '',
    logo: firstNonEmptyString(branchCompany?.company_logo, defaultCompany?.logo),
    logo_base64: firstNonEmptyString(branchCompany?.company_logo_base64, defaultCompany?.logo_base64),
  };
  merged.logoData = merged.logo_base64 || null;
  merged.has_branch_override = COMPANY_INFO_BRANCH_FIELD_MAP.some(([, branchField]) => normalizeOptionalString(branchCompany?.[branchField]));
  return merged;
}

async function resolveCompanyInfoForRequest(event, payload = {}) {
  const mainBranchId = getDefaultMainBranchIdSync();
  const branchId = await resolveBranchIdForRequest(event, payload, mainBranchId);
  const [defaultCompany, branchCompany] = await Promise.all([
    readDefaultCompanyInfo(),
    readBranchCompanyInfo(branchId),
  ]);
  return mergeCompanyInfoRecords(defaultCompany || {}, branchCompany || {}, branchId || mainBranchId);
}

