function buildDefaultCurrencySettingsList() {
  return DEFAULT_BRANCH_CURRENCIES.map((currency, index) => ({
    id: index + 1,
    code: currency.code,
    name: currency.name,
    symbol: currency.symbol,
    flag: currency.flag,
    icon: currency.icon,
    type: currency.type,
    rate: currency.code === 'SAR' ? 1 : 1,
    isDefault: currency.code === 'SAR' ? 1 : 0,
    is_base: currency.code === 'SAR' ? 1 : 0,
  }));
}

function parseJsonObjectText(value) {
  try {
    const text = String(value ?? '').trim();
    if (!text) {
      return {};
    }
    const parsed = JSON.parse(text);
    return parsed && typeof parsed === 'object' && !Array.isArray(parsed) ? parsed : {};
  } catch (_) {
    return {};
  }
}

function normalizeBooleanFlag(value, fallback = 0) {
  if (value === undefined || value === null || value === '') {
    return Number(fallback ? 1 : 0);
  }
  if (typeof value === 'string') {
    const normalized = value.trim().toLowerCase();
    if (['1', 'true', 'yes', 'on'].includes(normalized)) {
      return 1;
    }
    if (['0', 'false', 'no', 'off'].includes(normalized)) {
      return 0;
    }
  }
  return Number(Boolean(value));
}

function normalizeFiniteNumber(value, fallback) {
  const normalized = Number(value);
  return Number.isFinite(normalized) ? normalized : fallback;
}

function normalizePositiveFiniteNumber(value, fallback) {
  const normalized = Number(value);
  return Number.isFinite(normalized) && normalized > 0 ? normalized : fallback;
}

function normalizeInvoiceType(value, fallback = DEFAULT_INVOICE_SETTINGS.defaultInvoiceType) {
  return String(value || fallback).trim().toLowerCase() === 'mashghul' ? 'mashghul' : 'taskir';
}

function normalizePaymentType(value, fallback = DEFAULT_INVOICE_SETTINGS.defaultPaymentType) {
  return String(value || fallback).trim().toLowerCase() === 'cash' ? 'cash' : 'credit';
}

function normalizeOunceCalculationType(value, fallback = DEFAULT_INVOICE_SETTINGS.ounceCalculationType) {
  const normalized = String(value || fallback).trim().toLowerCase();
  return ['default', 'gold', 'gold2', 'custom', 'manual'].includes(normalized) ? normalized : fallback;
}

function normalizeCurrencyCode(value, fallback = null) {
  const normalize = (input) => {
    const text = String(input ?? '').trim().toUpperCase().replace(/[^A-Z]/g, '');
    return text ? text.slice(0, 3) : null;
  };
  return normalize(value) || normalize(fallback);
}

function normalizeCurrencyText(value, fallback = '') {
  const text = String(value ?? '').trim();
  return text || String(fallback ?? '').trim();
}

function normalizeCurrencyType(value, fallback = 'world') {
  const normalized = String(value || fallback).trim().toLowerCase();
  return normalized === 'arab' ? 'arab' : 'world';
}

function normalizeCurrencyItem(source = {}, fallback = {}, defaultId = 1) {
  const code = normalizeCurrencyCode(source?.code, fallback?.code);
  if (!code) {
    return null;
  }
  return {
    id: Number(source?.id || fallback?.id || defaultId) || defaultId,
    code,
    name: normalizeCurrencyText(source?.name ?? source?.name_ar ?? source?.nameAr, fallback?.name || fallback?.name_ar || fallback?.nameAr || code),
    symbol: normalizeCurrencyText(source?.symbol, fallback?.symbol || code),
    flag: normalizeCurrencyText(source?.flag, fallback?.flag || '🏳️'),
    icon: normalizeCurrencyText(source?.icon, fallback?.icon || 'fa-dollar-sign'),
    type: normalizeCurrencyType(source?.type, fallback?.type || 'world'),
    rate: normalizePositiveFiniteNumber(source?.rate ?? source?.exchange_rate ?? source?.exchangeRate, Number(fallback?.rate ?? fallback?.exchange_rate ?? fallback?.exchangeRate ?? 1) || 1),
    isDefault: normalizeBooleanFlag(source?.isDefault ?? source?.is_default, fallback?.isDefault ?? fallback?.is_default),
    is_base: normalizeBooleanFlag(source?.is_base ?? source?.isBase, fallback?.is_base ?? fallback?.isBase ?? fallback?.isDefault ?? fallback?.is_default),
  };
}

function normalizeCurrencySettingsList(rawList = [], fallbackList = []) {
  const fallbackBase = Array.isArray(fallbackList) && fallbackList.length ? fallbackList : buildDefaultCurrencySettingsList();
  const fallbackMap = new Map();
  const normalizedFallback = [];
  fallbackBase.forEach((item, index) => {
    const normalized = normalizeCurrencyItem(item, item, index + 1);
    if (!normalized || fallbackMap.has(normalized.code)) {
      return;
    }
    fallbackMap.set(normalized.code, normalized);
    normalizedFallback.push(normalized);
  });

  const sourceMap = new Map();
  const sourceList = Array.isArray(rawList) ? rawList : [];
  sourceList.forEach((item, index) => {
    const sourceCode = normalizeCurrencyCode(item?.code, null);
    const fallbackItem = sourceCode ? fallbackMap.get(sourceCode) : null;
    const normalized = normalizeCurrencyItem(item, fallbackItem || {}, Number(fallbackItem?.id || index + 1) || index + 1);
    if (!normalized || sourceMap.has(normalized.code)) {
      return;
    }
    sourceMap.set(normalized.code, normalized);
  });

  const merged = normalizedFallback.map((fallbackItem, index) => {
    const override = sourceMap.get(fallbackItem.code);
    return normalizeCurrencyItem(override || fallbackItem, fallbackItem, index + 1);
  }).filter(Boolean);

  sourceMap.forEach((sourceItem, code) => {
    if (!fallbackMap.has(code)) {
      const normalized = normalizeCurrencyItem(sourceItem, {}, merged.length + 1);
      if (normalized) {
        merged.push(normalized);
      }
    }
  });

  let defaultCode = merged.find((item) => item.isDefault || item.is_base)?.code || 'SAR';
  if (!merged.some((item) => item.code === defaultCode)) {
    defaultCode = merged[0]?.code || 'SAR';
  }

  return merged.map((item, index) => ({
    ...item,
    id: Number(item?.id || index + 1) || index + 1,
    isDefault: item.code === defaultCode ? 1 : 0,
    is_base: item.code === defaultCode ? 1 : 0,
  }));
}

function normalizeCurrencySettingsPayload(raw = {}, fallbackList = []) {
  const source = Array.isArray(raw)
    ? { currencies: raw }
    : ((raw && typeof raw === 'object' && !Array.isArray(raw)) ? raw : {});
  const normalizedFallback = normalizeCurrencySettingsList(fallbackList, buildDefaultCurrencySettingsList());
  const normalizedCurrencies = normalizeCurrencySettingsList(source?.currencies, normalizedFallback);
  const requestedDefaultCode = normalizeCurrencyCode(
    source?.defaultCurrencyCode || source?.default_currency_code || source?.defaultCurrency?.code,
    null
  );
  const fallbackDefaultCode = normalizedCurrencies.find((item) => item.isDefault || item.is_base)?.code || normalizedFallback.find((item) => item.isDefault)?.code || normalizedCurrencies[0]?.code || 'SAR';
  const defaultCode = requestedDefaultCode && normalizedCurrencies.some((item) => item.code === requestedDefaultCode)
    ? requestedDefaultCode
    : fallbackDefaultCode;
  const currencies = normalizedCurrencies.map((item, index) => ({
    ...item,
    id: Number(item?.id || index + 1) || index + 1,
    isDefault: item.code === defaultCode ? 1 : 0,
    is_base: item.code === defaultCode ? 1 : 0,
  }));
  return {
    currencies,
    defaultCurrencyCode: defaultCode,
  };
}

function normalizeInvoiceSettingsRecord(raw = {}, fallback = {}) {
  const source = raw && typeof raw === 'object' && !Array.isArray(raw) ? raw : {};
  const base = {
    ...DEFAULT_INVOICE_SETTINGS,
    ...((fallback && typeof fallback === 'object' && !Array.isArray(fallback)) ? fallback : {}),
  };
  return {
    id: Number(source?.id || base?.id || 1) || 1,
    taxEnabled: normalizeBooleanFlag(source?.taxEnabled, base.taxEnabled),
    taxRate: normalizeFiniteNumber(source?.taxRate, Number(base.taxRate || DEFAULT_INVOICE_SETTINGS.taxRate) || DEFAULT_INVOICE_SETTINGS.taxRate),
    taxOnLabor: normalizeBooleanFlag(source?.taxOnLabor, base.taxOnLabor),
    defaultInvoiceType: normalizeInvoiceType(source?.defaultInvoiceType, base.defaultInvoiceType),
    lockTaxRate: normalizeBooleanFlag(source?.lockTaxRate, base.lockTaxRate),
    lockTaxOnLabor: normalizeBooleanFlag(source?.lockTaxOnLabor, base.lockTaxOnLabor),
    allowInvoiceTypeChange: normalizeBooleanFlag(source?.allowInvoiceTypeChange, base.allowInvoiceTypeChange),
    ounceCalculationType: normalizeOunceCalculationType(source?.ounceCalculationType, base.ounceCalculationType),
    conversionFactor: normalizePositiveFiniteNumber(source?.conversionFactor, Number(base.conversionFactor || DEFAULT_INVOICE_SETTINGS.conversionFactor) || DEFAULT_INVOICE_SETTINGS.conversionFactor),
    exchangeRate: normalizePositiveFiniteNumber(source?.exchangeRate, Number(base.exchangeRate || DEFAULT_INVOICE_SETTINGS.exchangeRate) || DEFAULT_INVOICE_SETTINGS.exchangeRate),
    goldMultiplier: normalizePositiveFiniteNumber(source?.goldMultiplier, Number(base.goldMultiplier || DEFAULT_INVOICE_SETTINGS.goldMultiplier) || DEFAULT_INVOICE_SETTINGS.goldMultiplier),
    gold2Multiplier: normalizePositiveFiniteNumber(source?.gold2Multiplier, Number(base.gold2Multiplier || DEFAULT_INVOICE_SETTINGS.gold2Multiplier) || DEFAULT_INVOICE_SETTINGS.gold2Multiplier),
    customMultiplier: normalizePositiveFiniteNumber(source?.customMultiplier, Number(base.customMultiplier || DEFAULT_INVOICE_SETTINGS.customMultiplier) || DEFAULT_INVOICE_SETTINGS.customMultiplier),
    defaultPaymentType: normalizePaymentType(source?.defaultPaymentType, base.defaultPaymentType),
    lockPaymentType: normalizeBooleanFlag(source?.lockPaymentType, base.lockPaymentType),
    warnDeleteLine: normalizeBooleanFlag(source?.warnDeleteLine, base.warnDeleteLine),
    warnDeleteInvoice: normalizeBooleanFlag(source?.warnDeleteInvoice, base.warnDeleteInvoice),
    requireOunceTaskir: normalizeBooleanFlag(source?.requireOunceTaskir, base.requireOunceTaskir),
    requireKarat: normalizeBooleanFlag(source?.requireKarat, base.requireKarat),
    warnDuplicateRef: normalizeBooleanFlag(source?.warnDuplicateRef, base.warnDuplicateRef),
    created_at: normalizeOptionalString(source?.created_at || base?.created_at),
    updated_at: normalizeOptionalString(source?.updated_at || base?.updated_at),
  };
}

async function readDefaultInvoiceSettings() {
  return await tursoSync.queryOne('SELECT * FROM invoice_settings ORDER BY id ASC LIMIT 1');
}

async function readBranchInvoiceSettings(branchId) {
  const normalizedBranchId = normalizePositiveId(branchId, null);
  if (!normalizedBranchId) {
    return {};
  }
  const row = await tursoSync.queryOne(`
    SELECT invoice_settings_json
    FROM branches
    WHERE id = ?
    LIMIT 1
  `, [normalizedBranchId]);
  return parseJsonObjectText(row?.invoice_settings_json);
}

async function resolveInvoiceSettingsForRequest(event, payload = {}) {
  const mainBranchId = getDefaultMainBranchIdSync();
  const branchId = await resolveBranchIdForRequest(event, payload, mainBranchId);
  const [defaultSettings, branchSettings] = await Promise.all([
    readDefaultInvoiceSettings(),
    readBranchInvoiceSettings(branchId),
  ]);
  const data = normalizeInvoiceSettingsRecord(branchSettings, defaultSettings || DEFAULT_INVOICE_SETTINGS);
  data.branch_id = branchId || mainBranchId;
  data.has_branch_override = Object.keys(branchSettings || {}).length > 0;
  return data;
}

function getInvoiceSettingsCacheKey(branchId) {
  const normalizedBranchId = normalizePositiveId(branchId, getDefaultMainBranchIdSync()) || getDefaultMainBranchIdSync();
  return `invoiceSettings:${normalizedBranchId}`;
}

async function readDefaultCurrencySettings() {
  const rows = await tursoSync.queryAll(`
    SELECT id, code, name_ar, name_en, symbol, flag, exchange_rate, is_default, type, active
    FROM currencies
    WHERE COALESCE(active, 1) = 1
    ORDER BY COALESCE(is_default, 0) DESC, id ASC
  `);
  if (!Array.isArray(rows) || !rows.length) {
    return { currencies: buildDefaultCurrencySettingsList() };
  }
  const normalizedRows = normalizeCurrencySettingsList(rows.map((row, index) => ({
    id: Number(row?.id || index + 1) || index + 1,
    code: row?.code,
    name: firstNonEmptyString(row?.name_ar, row?.name_en, row?.code) || String(row?.code || '').trim(),
    symbol: row?.symbol,
    flag: row?.flag,
    rate: row?.exchange_rate,
    isDefault: row?.is_default,
    is_base: row?.is_default,
    type: row?.type,
  })), buildDefaultCurrencySettingsList());
  return {
    currencies: normalizedRows,
  };
}

async function readBranchCurrencySettings(branchId) {
  const normalizedBranchId = normalizePositiveId(branchId, null);
  if (!normalizedBranchId) {
    return {};
  }
  const row = await tursoSync.queryOne(`
    SELECT currency_settings_json
    FROM branches
    WHERE id = ?
    LIMIT 1
  `, [normalizedBranchId]);
  return parseJsonObjectText(row?.currency_settings_json);
}

async function resolveCurrencySettingsForRequest(event, payload = {}) {
  const mainBranchId = getDefaultMainBranchIdSync();
  const branchId = await resolveBranchIdForRequest(event, payload, mainBranchId);
  const [defaultSettings, branchSettings] = await Promise.all([
    readDefaultCurrencySettings(),
    readBranchCurrencySettings(branchId),
  ]);
  const normalizedDefault = normalizeCurrencySettingsPayload(defaultSettings, buildDefaultCurrencySettingsList());
  const hasBranchOverride = Array.isArray(branchSettings?.currencies) && branchSettings.currencies.length > 0;
  const normalizedBranch = normalizeCurrencySettingsPayload(branchSettings, normalizedDefault.currencies);
  const data = hasBranchOverride ? normalizedBranch : normalizedDefault;
  data.branch_id = branchId || mainBranchId;
  data.has_branch_override = hasBranchOverride;
  data.defaultCurrency = data.currencies.find((item) => item.code === data.defaultCurrencyCode) || data.currencies.find((item) => item.isDefault || item.is_base) || data.currencies[0] || null;
  return data;
}

function normalizePartyAccessScope(value, fallback = 'single') {
  const normalized = String(value || '').trim().toLowerCase();
  if (normalized === 'single' || normalized === 'multiple' || normalized === 'all') {
    return normalized;
  }
  if (normalized === 'multi') {
    return 'multiple';
  }
  if (normalized === 'branch' || normalized === 'selected') {
    return 'single';
  }
  return fallback;
}

function getPartyTableName(scope) {
  return scope === 'supplier' ? 'suppliers' : 'customers';
}

function getPartyBranchAssignmentsTable(scope) {
  return scope === 'supplier' ? 'supplier_branches' : 'customer_branches';
}

function getPartyBranchAssignmentsOwnerField(scope) {
  return scope === 'supplier' ? 'supplier_id' : 'customer_id';
}

function buildPartyBranchAccessWhereClause(scope, alias, branchIds = [], mainBranchId = null) {
  const fallbackBranchId = normalizePositiveId(mainBranchId, getDefaultMainBranchIdSync()) || getDefaultMainBranchIdSync();
  const effectiveBranchIds = normalizeBranchIdList(branchIds).length ? normalizeBranchIdList(branchIds) : [fallbackBranchId];
  const assignmentsTable = getPartyBranchAssignmentsTable(scope);
  const ownerField = getPartyBranchAssignmentsOwnerField(scope);
  const placeholders = effectiveBranchIds.map(() => '?').join(', ');
  return {
    sql: `(
      COALESCE(${alias}.access_scope, 'single') = 'all'
      OR EXISTS (
        SELECT 1
        FROM ${assignmentsTable} access_map
        WHERE access_map.${ownerField} = ${alias}.id
          AND access_map.branch_id IN (${placeholders})
      )
      OR (
        NOT EXISTS (
          SELECT 1
          FROM ${assignmentsTable} access_fallback
          WHERE access_fallback.${ownerField} = ${alias}.id
        )
        AND COALESCE(${alias}.branch_id, ${fallbackBranchId}) IN (${placeholders})
      )
    )`,
    params: [...effectiveBranchIds, ...effectiveBranchIds],
  };
}

async function resolvePartyBranchAccessForSave(event, payload = {}, fallbackBranchId = null) {
  const requestPayload = payload && typeof payload === 'object' ? payload : {};
  const authenticatedUser = getAuthenticatedUserFromEvent(event);
  let allowedBranchIds = getAllowedBranchIdsForAuthenticatedUser(authenticatedUser, fallbackBranchId);
  if (!allowedBranchIds.length) {
    allowedBranchIds = normalizeBranchIdList([
      requestPayload?.branch_id,
      requestPayload?.branchId,
      requestPayload?.selectedBranchId,
      fallbackBranchId,
      getDefaultMainBranchIdSync(),
    ]);
  }
  if (!allowedBranchIds.length) {
    allowedBranchIds = [getDefaultMainBranchIdSync()];
  }

  const requestedScope = normalizePartyAccessScope(
    requestPayload?.access_scope
      ?? requestPayload?.accessScope
      ?? requestPayload?.branch_access_scope
      ?? requestPayload?.branchAccessScope,
    'single'
  );
  const requestedPrimaryBranchId = normalizePositiveId(
    requestPayload?.branch_id || requestPayload?.branchId || requestPayload?.selectedBranchId,
    null
  );
  let selectedBranchIds = normalizeBranchIdList(requestPayload?.branch_ids ?? requestPayload?.branchIds)
    .filter((branchId) => allowedBranchIds.includes(branchId));
  let primaryBranchId = requestedPrimaryBranchId && allowedBranchIds.includes(requestedPrimaryBranchId)
    ? requestedPrimaryBranchId
    : null;

  if (requestedScope !== 'all') {
    if (!selectedBranchIds.length && primaryBranchId) {
      selectedBranchIds = [primaryBranchId];
    }
    if (!selectedBranchIds.length) {
      selectedBranchIds = [allowedBranchIds[0]];
    }
  }

  const branchIdsToValidate = requestedScope === 'all'
    ? normalizeBranchIdList([primaryBranchId || allowedBranchIds[0]])
    : selectedBranchIds;
  const validationBranchIds = branchIdsToValidate.length ? branchIdsToValidate : [allowedBranchIds[0] || getDefaultMainBranchIdSync()];
  const placeholders = validationBranchIds.map(() => '?').join(', ');
  const existingBranches = await tursoSync.queryAll(
    `SELECT id FROM branches WHERE id IN (${placeholders})`,
    validationBranchIds
  );
  const existingBranchIds = normalizeBranchIdList(existingBranches.map((row) => row?.id));
  if (!existingBranchIds.length) {
    throw new Error('لا توجد فروع صالحة متاحة');
  }

  if (requestedScope === 'all' && allowedBranchIds.length > 1) {
    return {
      accessScope: 'all',
      branchId: existingBranchIds.includes(primaryBranchId) ? primaryBranchId : existingBranchIds[0],
      branchIds: [],
    };
  }

  selectedBranchIds = selectedBranchIds.filter((branchId) => existingBranchIds.includes(branchId));
  if (!selectedBranchIds.length) {
    selectedBranchIds = [existingBranchIds[0]];
  }
  if (!primaryBranchId || !selectedBranchIds.includes(primaryBranchId)) {
    primaryBranchId = selectedBranchIds[0];
  }

  return {
    accessScope: selectedBranchIds.length > 1 ? 'multiple' : 'single',
    branchId: primaryBranchId,
    branchIds: selectedBranchIds,
  };
}

async function savePartyBranchAssignments(scope, partyId, branchIds = [], createdAt = null) {
  const normalizedPartyId = normalizePositiveId(partyId, 0);
  if (!normalizedPartyId) {
    throw new Error('معرّف الطرف غير صالح');
  }
  const assignmentsTable = getPartyBranchAssignmentsTable(scope);
  const ownerField = getPartyBranchAssignmentsOwnerField(scope);
  const effectiveBranchIds = normalizeBranchIdList(branchIds);
  await tursoSync.run(`DELETE FROM ${assignmentsTable} WHERE ${ownerField} = ?`, [normalizedPartyId]);
  const assignmentCreatedAt = createdAt || new Date().toISOString();
  for (const branchId of effectiveBranchIds) {
    await tursoSync.run(
      `INSERT INTO ${assignmentsTable} (${ownerField}, branch_id, created_at) VALUES (?, ?, ?)`,
      [normalizedPartyId, branchId, assignmentCreatedAt]
    );
  }
}

async function getPartyBranchAccessInfo(scope, partyId) {
  const normalizedPartyId = normalizePositiveId(partyId, 0);
  if (!normalizedPartyId) {
    return null;
  }
  const tableName = getPartyTableName(scope);
  const assignmentsTable = getPartyBranchAssignmentsTable(scope);
  const ownerField = getPartyBranchAssignmentsOwnerField(scope);
  const mainBranchId = getDefaultMainBranchIdSync();
  const row = await tursoSync.queryOne(
    `SELECT id, name, account_id, created_at, branch_id, COALESCE(access_scope, 'single') AS access_scope
     FROM ${tableName}
     WHERE id = ?`,
    [normalizedPartyId]
  );
  if (!row) {
    return null;
  }
  const assignmentRows = await tursoSync.queryAll(
    `SELECT branch_id FROM ${assignmentsTable} WHERE ${ownerField} = ? ORDER BY branch_id ASC`,
    [normalizedPartyId]
  );
  const primaryBranchId = normalizePositiveId(row?.branch_id, mainBranchId) || mainBranchId;
  const assignedBranchIds = normalizeBranchIdList(assignmentRows.map((item) => item?.branch_id));
  const normalizedScope = normalizePartyAccessScope(row?.access_scope, 'single');
  return {
    ...row,
    branch_id: primaryBranchId,
    access_scope: normalizedScope === 'all' ? 'all' : (assignedBranchIds.length > 1 ? 'multiple' : 'single'),
    assigned_branch_ids: assignedBranchIds.length ? assignedBranchIds : [primaryBranchId],
  };
}

function partyAccessAllowsBranch(accessInfo, branchId) {
  const normalizedBranchId = normalizePositiveId(branchId, null);
  if (!accessInfo || !normalizedBranchId) {
    return false;
  }
  const accessScope = normalizePartyAccessScope(accessInfo?.access_scope, 'single');
  if (accessScope === 'all') {
    return true;
  }
  const assignedBranchIds = normalizeBranchIdList(accessInfo?.assigned_branch_ids);
  if (assignedBranchIds.length) {
    return assignedBranchIds.includes(normalizedBranchId);
  }
  return normalizePositiveId(accessInfo?.branch_id, null) === normalizedBranchId;
}

function getPartyBroadcastBranchId(accessInfo) {
  if (!accessInfo) {
    return null;
  }
  const accessScope = normalizePartyAccessScope(accessInfo?.access_scope, 'single');
  if (accessScope === 'all') {
    return null;
  }
  const assignedBranchIds = normalizeBranchIdList(accessInfo?.assigned_branch_ids);
  if (assignedBranchIds.length > 1) {
    return null;
  }
  return normalizePositiveId(assignedBranchIds[0] || accessInfo?.branch_id, null);
}

function hasExplicitPartyAccessSelection(payload = {}) {
  return payload && typeof payload === 'object' && (
    payload?.access_scope !== undefined ||
    payload?.accessScope !== undefined ||
    payload?.branch_access_scope !== undefined ||
    payload?.branchAccessScope !== undefined ||
    payload?.branch_ids !== undefined ||
    payload?.branchIds !== undefined
  );
}

async function saveUserBranchAssignments(userId, payload = {}) {
  const normalizedUserId = normalizePositiveId(userId, 0);
  if (!normalizedUserId) {
    throw new Error('معرّف المستخدم غير صالح');
  }

  const existingAssignments = await tursoSync.queryAll(
    `SELECT branch_id, is_default, can_login, read_only
     FROM user_branches
     WHERE user_id = ?
     ORDER BY COALESCE(is_default, 0) DESC, branch_id ASC`,
    [normalizedUserId]
  );
  const hasExplicitBranchIds = Array.isArray(payload?.branch_ids) || Array.isArray(payload?.branchIds);
  const requestedBranchIds = normalizeBranchIdList(payload?.branch_ids ?? payload?.branchIds);
  const branchIds = hasExplicitBranchIds
    ? (requestedBranchIds.length ? requestedBranchIds : [getDefaultMainBranchIdSync()])
    : (existingAssignments.length
        ? normalizeBranchIdList(existingAssignments.map((row) => row?.branch_id))
        : [getDefaultMainBranchIdSync()]);
  const placeholders = branchIds.map(() => '?').join(', ');
  const existingBranches = await tursoSync.queryAll(
    `SELECT id FROM branches WHERE id IN (${placeholders})`,
    branchIds
  );
  if (existingBranches.length !== branchIds.length) {
    throw new Error('بعض الفروع المحددة غير موجودة');
  }

  const existingDefaultBranchId = normalizePositiveId(
    existingAssignments.find((row) => Number(row?.is_default || 0) === 1)?.branch_id,
    null
  );
  const requestedDefaultBranchId = normalizePositiveId(payload?.default_branch_id ?? payload?.defaultBranchId, null);
  const defaultBranchId = branchIds.includes(requestedDefaultBranchId)
    ? requestedDefaultBranchId
    : (branchIds.includes(existingDefaultBranchId) ? existingDefaultBranchId : branchIds[0]);
  const canLoginByBranch = (payload?.can_login_by_branch && typeof payload.can_login_by_branch === 'object')
    ? payload.can_login_by_branch
    : ((payload?.canLoginByBranch && typeof payload.canLoginByBranch === 'object') ? payload.canLoginByBranch : {});
  const hasExplicitCanLoginConfig = payload?.can_login_by_branch !== undefined || payload?.canLoginByBranch !== undefined;
  const readOnlyByBranch = (payload?.read_only_by_branch && typeof payload.read_only_by_branch === 'object')
    ? payload.read_only_by_branch
    : ((payload?.readOnlyByBranch && typeof payload.readOnlyByBranch === 'object') ? payload.readOnlyByBranch : {});
  const hasExplicitReadOnlyConfig = payload?.read_only_by_branch !== undefined || payload?.readOnlyByBranch !== undefined;
  const existingCanLoginByBranch = {};
  const existingReadOnlyByBranch = {};
  existingAssignments.forEach((row) => {
    const branchId = normalizePositiveId(row?.branch_id, null);
    if (branchId) {
      existingCanLoginByBranch[String(branchId)] = Number(row?.can_login ?? 1) === 1 ? 1 : 0;
      existingReadOnlyByBranch[String(branchId)] = Number(row?.read_only || 0) === 1 ? 1 : 0;
    }
  });

  await tursoSync.run('DELETE FROM user_branches WHERE user_id = ?', [normalizedUserId]);
  const createdAt = new Date().toISOString();
  for (const branchId of branchIds) {
    const loginFlagRaw = canLoginByBranch[String(branchId)] ?? canLoginByBranch[branchId];
    const fallbackCanLogin = existingCanLoginByBranch[String(branchId)] ?? existingCanLoginByBranch[branchId];
    const readOnlyFlagRaw = readOnlyByBranch[String(branchId)] ?? readOnlyByBranch[branchId];
    const fallbackReadOnly = existingReadOnlyByBranch[String(branchId)] ?? existingReadOnlyByBranch[branchId];
    const canLogin = branchId === defaultBranchId
      ? 1
      : (loginFlagRaw !== undefined
          ? (loginFlagRaw ? 1 : 0)
          : (fallbackCanLogin !== undefined && !hasExplicitCanLoginConfig ? (fallbackCanLogin ? 1 : 0) : 1));
    const readOnly = readOnlyFlagRaw !== undefined
      ? (readOnlyFlagRaw ? 1 : 0)
      : (fallbackReadOnly !== undefined && !hasExplicitReadOnlyConfig ? (fallbackReadOnly ? 1 : 0) : 0);
    await tursoSync.run(
      `INSERT INTO user_branches (user_id, branch_id, is_default, can_login, read_only, created_at)
       VALUES (?, ?, ?, ?, ?, ?)`,
      [normalizedUserId, branchId, branchId === defaultBranchId ? 1 : 0, canLogin, readOnly, createdAt]
    );
  }

  return { branchIds, defaultBranchId };
}

// Initialize the database with proper path handling
// البرنامج Portable - قاعدة البيانات في مجلد البرنامج نفسه
const isDev = !app.isPackaged;

// تحديد المسار الأساسي للبرنامج (Portable Mode)
