function migrateLegacyLicenseFiles() {
  const fileNames = ['license.dat', 'license-history.json'];
  const legacyDirs = [dataFolder, dataDir];
  try {
    fs.mkdirSync(licenseDataPath, { recursive: true });
  } catch (_) {}

  for (const fileName of fileNames) {
    const nextPath = path.join(licenseDataPath, fileName);
    if (fs.existsSync(nextPath)) {
      continue;
    }
    for (const legacyDir of legacyDirs) {
      const legacyPath = path.join(legacyDir, fileName);
      try {
        if (fs.existsSync(legacyPath)) {
          fs.copyFileSync(legacyPath, nextPath);
          break;
        }
      } catch (_) {}
    }
  }
}

function migrateLegacyMachineIdCache() {
  const fileName = 'machine-id.json';
  const legacyDirs = [dataDir];
  try {
    fs.mkdirSync(licenseDataPath, { recursive: true });
  } catch (_) {}
  const nextPath = path.join(licenseDataPath, fileName);
  if (fs.existsSync(nextPath)) {
    return;
  }
  for (const legacyDir of legacyDirs) {
    const legacyPath = path.join(legacyDir, fileName);
    try {
      if (fs.existsSync(legacyPath)) {
        fs.copyFileSync(legacyPath, nextPath);
        break;
      }
    } catch (_) {}
  }
}

 migrateLegacyLicenseFiles();
