 const UNLICENSED_GENERAL_CHANNELS = new Set([
   'get-app-logo',
   'open-external-url',
 ]);

 const UNLICENSED_ACTIVATION_CHANNELS = new Set([
   'license-get-machine-id',
   'license-check-status',
   'license-activate',
   'generate-license-code',
   'open-license-generator',
   'verify-dev-password',
   'get-license-history',
   'save-license-to-history',
 ]);

 const UNLICENSED_LOGIN_CHANNELS = new Set([
   'get-company-info',
   'get-cloud-mode',
   'select-database-path',
   'connect-to-database',
   'get-current-db-path',
   'save-db-path',
   'check-if-cloud-storage',
 ]);

 const UNLICENSED_DB_ERROR_CHANNELS = new Set([
   'db:create-new',
   'db:list-backups',
   'db:restore-backup',
   'db:browse',
   'db:connect',
   'db:retry',
   'app:restart',
   'app:quit',
 ]);

 function getLicenseStatusSafe() {
   try {
     return licenseManager.checkLicenseStatus(licenseDataPath);
   } catch (_) {
     return {
       licensed: false,
       valid: false,
       expired: false,
       message: 'البرنامج غير مفعل'
     };
   }
}

 function isLicenseActive(status = null) {
  const currentStatus = status || getLicenseStatusSafe();
  return !!(currentStatus && currentStatus.licensed === true && currentStatus.valid === true);
}
function getScreenFilePath(screenName) {
   return path.join(__dirname, 'screens', screenName, 'index.html');
 }

 function normalizeComparableFilePath(filePath) {
   return path.normalize(String(filePath || '').replace(/\//g, path.sep)).toLowerCase();
 }

 function getFilePathFromUrl(rawUrl) {
   try {
     if (!rawUrl || typeof rawUrl !== 'string' || !rawUrl.startsWith('file://')) {
       return '';
     }
     const parsed = new URL(rawUrl);
     let pathname = decodeURIComponent(parsed.pathname || '');
     if (/^\/[A-Za-z]:\//.test(pathname)) {
       pathname = pathname.slice(1);
     }
     return path.normalize(pathname);
   } catch (_) {
     return '';
   }
 }

 function isActivationScreenFile(filePath) {
   return normalizeComparableFilePath(filePath) === normalizeComparableFilePath(getScreenFilePath('activation'));
 }

 function isLoginScreenFile(filePath) {
   return normalizeComparableFilePath(filePath) === normalizeComparableFilePath(getScreenFilePath('login'));
 }

 function isDbErrorScreenFile(filePath) {
   return normalizeComparableFilePath(filePath) === normalizeComparableFilePath(getScreenFilePath('db-error'));
 }

 function isProtectedScreenFile(filePath) {
   const normalizedPath = normalizeComparableFilePath(filePath);
   const screensRoot = normalizeComparableFilePath(path.join(__dirname, 'screens'));
   if (!normalizedPath || !normalizedPath.startsWith(screensRoot)) {
     return false;
   }
   if (isActivationScreenFile(normalizedPath) || isDbErrorScreenFile(normalizedPath)) {
     return false;
   }
   return true;
 }

 function isChannelAllowedWithoutLicense(channel, senderPath) {
   if (UNLICENSED_GENERAL_CHANNELS.has(channel)) {
     return true;
   }
   if (UNLICENSED_ACTIVATION_CHANNELS.has(channel)) {
     return isActivationScreenFile(senderPath);
   }
   if (UNLICENSED_LOGIN_CHANNELS.has(channel)) {
     return isLoginScreenFile(senderPath);
   }
   if (UNLICENSED_DB_ERROR_CHANNELS.has(channel)) {
     return isDbErrorScreenFile(senderPath);
   }
   return false;
 }

 function redirectToActivation(targetWindow = null) {
   const mainWindow = (targetWindow && !targetWindow.isDestroyed()) ? targetWindow : win;
   try {
     const windows = BrowserWindow.getAllWindows();
     windows.forEach((browserWindow) => {
       try {
         if (!browserWindow || browserWindow.isDestroyed() || browserWindow === mainWindow) return;
         browserWindow.close();
       } catch (_) {}
     });
   } catch (_) {}
   if (!mainWindow || mainWindow.isDestroyed()) {
     return;
   }
   const activationPath = getScreenFilePath('activation');
   const currentPath = getFilePathFromUrl(mainWindow.webContents?.getURL?.() || '');
   if (normalizeComparableFilePath(currentPath) === normalizeComparableFilePath(activationPath)) {
     return;
   }
   mainWindow.loadFile(activationPath).catch((error) => {
     console.error('[Main] Failed to redirect to activation screen:', error.message);
   });
 }

 const originalIpcMainHandle = ipcMain.handle.bind(ipcMain);
 ipcMain.handle = (channel, listener) => {
   return originalIpcMainHandle(channel, async (event, ...args) => {
     const status = getLicenseStatusSafe();
     if (!isLicenseActive(status)) {
       const senderPath = getFilePathFromUrl(event?.senderFrame?.url || event?.sender?.getURL?.() || '');
       if (!isChannelAllowedWithoutLicense(channel, senderPath)) {
         const targetWindow = BrowserWindow.fromWebContents(event.sender);
         redirectToActivation(targetWindow);
         return {
           success: false,
           licensed: false,
           valid: false,
           expired: !!status?.expired,
           error: status?.message || 'الترخيص غير صالح أو منتهي'
         };
       }
     }
     return listener(event, ...args);
   });
 };

 const originalIpcMainOn = ipcMain.on.bind(ipcMain);
 ipcMain.on = (channel, listener) => {
   return originalIpcMainOn(channel, (event, ...args) => {
     const status = getLicenseStatusSafe();
     if (!isLicenseActive(status)) {
       const senderPath = getFilePathFromUrl(event?.senderFrame?.url || event?.sender?.getURL?.() || '');
       if (!isChannelAllowedWithoutLicense(channel, senderPath)) {
         const targetWindow = BrowserWindow.fromWebContents(event.sender);
         redirectToActivation(targetWindow);
         return;
       }
     }
     return listener(event, ...args);
   });
 };

function readSettings(){
  try{
    if (!fs.existsSync(settingsFile)) return {};
    const raw = fs.readFileSync(settingsFile, 'utf8');
    return JSON.parse(raw || '{}');
  }catch(_){ return {}; }
}

function writeSettings(obj){
  fs.mkdirSync(dataDir, { recursive: true });
  fs.writeFileSync(settingsFile, JSON.stringify(obj || {}, null, 2), 'utf8');
}

