// Function to connect to database
function connectDatabase(customPath = null) {
  let targetPath = customPath || dbPath; // Define outside try block
  
  try {
    // Check if file exists, if not create directory and let SQLite create it
    const dbDir = path.dirname(targetPath);
    if (!fs.existsSync(dbDir)) {
      fs.mkdirSync(dbDir, { recursive: true });
      console.log('✅ Created database directory:', dbDir);
    }
    
    // If database doesn't exist, SQLite will create it
    if (!fs.existsSync(targetPath)) {
      console.log('📝 Database file will be created:', targetPath);
    }
    
    // Close existing connection if any
    if (db) {
      try { db.close(); } catch(_) {}
    }
    
    // Connect to new database
    db = new Database(targetPath);
    
    // Enable foreign keys
    db.pragma('foreign_keys = ON');
    
    // ===== Multi-user/OneDrive optimizations =====
    // 1. Enable WAL mode for better concurrent access
    try {
      db.pragma('journal_mode = WAL');
      console.log('✅ WAL mode enabled for better concurrency');
    } catch (walErr) {
      console.warn('⚠️ Could not enable WAL mode:', walErr.message);
    }
    
    // 2. Set busy timeout to 10 seconds (wait instead of failing immediately)
    db.pragma('busy_timeout = 10000');
    console.log('✅ Busy timeout set to 10 seconds');
    
    // 3. Set synchronous mode to NORMAL for OneDrive (balance between safety and speed)
    db.pragma('synchronous = NORMAL');
    
    // 4. Check if database is on cloud storage (OneDrive, Dropbox, etc.)
    const isCloudPath = targetPath.toLowerCase().includes('onedrive') || 
                        targetPath.toLowerCase().includes('dropbox') ||
                        targetPath.toLowerCase().includes('google drive') ||
                        targetPath.toLowerCase().includes('icloud');
    
    dbPath = targetPath;
    tursoSync.setLocalDb(db);
    tursoSync.invalidateCache();
    
    console.log('✅ Connected to database:', dbPath);
    
    return { 
      success: true, 
      path: dbPath,
      isCloudStorage: isCloudPath,
      warning: isCloudPath ? 'تحذير: قاعدة البيانات على خدمة سحابية. احذر من الاستخدام المتزامن!' : null
    };
  } catch (err) {
    console.error('❌ Database connection failed:', err.message);
    console.error('Attempted path:', targetPath);
    
    // If custom path failed and it's different from default, try default as fallback
    // استخدام المسار المحمول (بجانب ملف EXE) وليس داخل app.asar
    const defaultDbPath = path.join(appBaseDir, 'database', 'database.db');
    if (customPath && customPath !== defaultDbPath) {
      console.log('⚠️ Falling back to default database...');
      try {
        if (db) {
          try { db.close(); } catch(_) {}
        }
        
        // Ensure directory exists
        const defaultDir = path.dirname(defaultDbPath);
        if (!fs.existsSync(defaultDir)) {
          fs.mkdirSync(defaultDir, { recursive: true });
        }
        
        db = new Database(defaultDbPath);
        db.pragma('foreign_keys = ON');
        db.pragma('journal_mode = WAL');
        db.pragma('busy_timeout = 10000');
        dbPath = defaultDbPath;
        tursoSync.setLocalDb(db);
        tursoSync.invalidateCache();
        console.log('✅ Connected to default database as fallback');
        return { 
          success: true, 
          path: dbPath,
          isCloudStorage: false,
          warning: 'تعذر الاتصال بقاعدة البيانات المخصصة. تم الاتصال بالقاعدة الافتراضية.'
        };
      } catch (fallbackErr) {
        console.error('❌ Fallback also failed:', fallbackErr.message);
        db = null; // Ensure db is null on complete failure
      }
    }
    
    db = null; // Ensure db is null on failure
    return { success: false, error: err.message, path: targetPath };
  }
}

// Helper function to retry database operations on SQLITE_BUSY
function retryOnBusy(operation, maxRetries = 5, delayMs = 200) {
  for (let attempt = 1; attempt <= maxRetries; attempt++) {
    try {
      return operation();
    } catch (err) {
      // Check if error is SQLITE_BUSY or database locked
      const isBusy = err.message && (
        err.message.includes('SQLITE_BUSY') || 
        err.message.includes('database is locked') ||
        err.code === 'SQLITE_BUSY'
      );
      
      if (isBusy && attempt < maxRetries) {
        console.warn(`⚠️ Database busy, retrying (${attempt}/${maxRetries})...`);
        // Exponential backoff
        const waitTime = delayMs * Math.pow(2, attempt - 1);
        // Synchronous sleep (blocking)
        const start = Date.now();
        while (Date.now() - start < waitTime) {
          // Busy wait
        }
        continue;
      }
      // Re-throw if not busy error or max retries reached
      throw err;
    }
  }
}

// Function to create automatic backup
function createAutoBackup() {
  try {
    if (!db) {
      console.warn('⚠️ Auto-backup skipped - no database connection');
      return;
    }

    // Get actual database path
    const actualDbPath = db.name || dbPath;
    
    console.log('\n' + '='.repeat(60));
    console.log('🔄 Starting automatic backup...');
    console.log('='.repeat(60));
    console.log('Source database:', actualDbPath);
    
    // Perform WAL checkpoint to ensure all data is flushed
    try {
      console.log('🔄 Performing WAL checkpoint before backup...');
      db.pragma('wal_checkpoint(FULL)');
      console.log('✅ WAL checkpoint completed');
    } catch (walErr) {
      console.warn('⚠️ WAL checkpoint warning:', walErr.message);
    }
    
    // Create timestamp for backup filename using LOCAL time
    const now = new Date();
    const year = now.getFullYear();
    const month = String(now.getMonth() + 1).padStart(2, '0');
    const day = String(now.getDate()).padStart(2, '0');
    const hours = String(now.getHours()).padStart(2, '0');
    const minutes = String(now.getMinutes()).padStart(2, '0');
    const seconds = String(now.getSeconds()).padStart(2, '0');
    
    // Format: YYYY-MM-DD_HH-MM-SS (local time)
    const timestamp = `${year}-${month}-${day}_${hours}-${minutes}-${seconds}`;
    
    const backupFileName = `database_backup_${timestamp}.db`;
    const backupFilePath = path.join(backupFolder, backupFileName);
    
    // Copy database file
    fs.copyFileSync(actualDbPath, backupFilePath);
    console.log('✅ Database backup created:', backupFileName);
    
    // Also backup WAL and SHM files if they exist
    const walPath = actualDbPath + '-wal';
    const shmPath = actualDbPath + '-shm';
    
    if (fs.existsSync(walPath)) {
      try {
        fs.copyFileSync(walPath, backupFilePath + '-wal');
        console.log('✅ WAL file also backed up');
      } catch (e) {
        console.log('⚠️ WAL backup skipped:', e.message);
      }
    }
    
    if (fs.existsSync(shmPath)) {
      try {
        fs.copyFileSync(shmPath, backupFilePath + '-shm');
        console.log('✅ SHM file also backed up');
      } catch (e) {
        console.log('⚠️ SHM backup skipped:', e.message);
      }
    }
    
    // Clean up old backups based on settings
    try {
      const appSettings = readSettings();
      const backupSettings = appSettings.backupSettings || { keepCount: 30 };
      cleanupOldBackups(backupSettings.keepCount);
    } catch (e) {
      cleanupOldBackups(30); // Fallback to default
    }
    
    console.log('✅ Auto-backup completed successfully');
    console.log('='.repeat(60) + '\n');
    
  } catch (err) {
    console.error('❌ Auto-backup failed:', err.message);
    console.error('='.repeat(60) + '\n');
  }
}

// Function to clean up old backups
function cleanupOldBackups(keepCount = 30) {
  try {
    const files = fs.readdirSync(backupFolder)
      .filter(f => f.startsWith('database_backup_') && f.endsWith('.db'))
      .map(f => ({
        name: f,
        path: path.join(backupFolder, f),
        time: fs.statSync(path.join(backupFolder, f)).mtime.getTime()
      }))
      .sort((a, b) => b.time - a.time); // Sort by newest first
    
    if (files.length > keepCount) {
      const filesToDelete = files.slice(keepCount);
      console.log(`🗑️ Cleaning up ${filesToDelete.length} old backup(s)...`);
      
      filesToDelete.forEach(file => {
        try {
          fs.unlinkSync(file.path);
          // Also delete WAL and SHM files
          const walPath = file.path + '-wal';
          const shmPath = file.path + '-shm';
          if (fs.existsSync(walPath)) fs.unlinkSync(walPath);
          if (fs.existsSync(shmPath)) fs.unlinkSync(shmPath);
          console.log(`   ✅ Deleted: ${file.name}`);
        } catch (delErr) {
          console.warn(`   ⚠️ Could not delete ${file.name}:`, delErr.message);
        }
      });
    }
  } catch (err) {
    console.warn('⚠️ Cleanup warning:', err.message);
  }
}

