// إنشاء قاعدة بيانات جديدة
ipcMain.handle('db:create-new', async () => {
  try {
    const newDbPath = path.join(appBaseDir, 'database', 'database.db');
    const dbDir = path.dirname(newDbPath);
    
    console.log('📁 Creating new database at:', newDbPath);
    
    if (!fs.existsSync(dbDir)) {
      fs.mkdirSync(dbDir, { recursive: true });
    }
    
    // إغلاق الاتصال القديم بشكل كامل
    if (db) {
      try { 
        db.close(); 
        console.log('🔌 Closed existing connection');
      } catch(_) {}
      db = null;
    }
    
    // انتظار قصير للتأكد من تحرير الملف
    await new Promise(resolve => setTimeout(resolve, 100));
    
    // حذف الملف التالف وملفات WAL/SHM
    const filesToDelete = [
      newDbPath,
      newDbPath + '-wal',
      newDbPath + '-shm',
      newDbPath + '-journal'
    ];
    
    for (const filePath of filesToDelete) {
      if (fs.existsSync(filePath)) {
        try {
          fs.unlinkSync(filePath);
          console.log('🗑️ Deleted:', path.basename(filePath));
        } catch (delErr) {
          console.error('❌ Could not delete:', path.basename(filePath), delErr.message);
          // محاولة إعادة التسمية بدلاً من الحذف
          try {
            const backupName = filePath + '.corrupt.' + Date.now();
            fs.renameSync(filePath, backupName);
            console.log('📦 Renamed corrupt file to:', path.basename(backupName));
          } catch (renameErr) {
            console.error('❌ Could not rename either:', renameErr.message);
          }
        }
      }
    }
    
    // انتظار إضافي
    await new Promise(resolve => setTimeout(resolve, 100));
    
    db = new Database(newDbPath);
    db.pragma('foreign_keys = ON');
    db.pragma('journal_mode = WAL');
    dbPath = newDbPath;
    
    console.log('✅ New database created:', newDbPath);
    return { success: true, path: newDbPath };
  } catch (err) {
    console.error('❌ Failed to create new database:', err.message);
    return { success: false, error: err.message };
  }
});

// قائمة النسخ الاحتياطية
ipcMain.handle('db:list-backups', async () => {
  try {
    const backupDir = path.join(appBaseDir, 'database', 'backup-databases');
    if (!fs.existsSync(backupDir)) {
      return { success: true, backups: [] };
    }
    
    const files = fs.readdirSync(backupDir)
      .filter(f => f.endsWith('.db') && f.startsWith('database_backup_'))
      .map(f => {
        const filePath = path.join(backupDir, f);
        const stats = fs.statSync(filePath);
        const match = f.match(/database_backup_(\d{4}-\d{2}-\d{2})_(\d{2}-\d{2}-\d{2})\.db/);
        let dateStr = '';
        if (match) {
          dateStr = match[1] + ' ' + match[2].replace(/-/g, ':');
        } else {
          dateStr = stats.mtime.toLocaleString('ar-u-ca-gregory-nu-latn');
        }
        return {
          name: f,
          path: filePath,
          date: dateStr,
          size: stats.size,
          mtime: stats.mtime
        };
      })
      .sort((a, b) => b.mtime - a.mtime)
      .slice(0, 10);
    
    return { success: true, backups: files };
  } catch (err) {
    console.error('❌ Failed to list backups:', err.message);
    return { success: false, error: err.message };
  }
});

// استعادة نسخة احتياطية
ipcMain.handle('db:restore-backup', async (_e, backupPath) => {
  try {
    if (!backupPath || !fs.existsSync(backupPath)) {
      return { success: false, error: 'ملف النسخة الاحتياطية غير موجود' };
    }
    
    const targetPath = path.join(appBaseDir, 'database', 'database.db');
    const targetDir = path.dirname(targetPath);
    
    if (!fs.existsSync(targetDir)) {
      fs.mkdirSync(targetDir, { recursive: true });
    }
    
    if (db) {
      try { db.close(); } catch(_) {}
    }
    
    fs.copyFileSync(backupPath, targetPath);
    
    db = new Database(targetPath);
    db.pragma('foreign_keys = ON');
    db.pragma('journal_mode = WAL');
    dbPath = targetPath;
    
    console.log('✅ Backup restored from:', backupPath);
    return { success: true, path: targetPath };
  } catch (err) {
    console.error('❌ Failed to restore backup:', err.message);
    return { success: false, error: err.message };
  }
});

