// Initialize database connection with error handling
let connectionResult = null;

try {
  console.log('\n' + '='.repeat(60));
  console.log('🔌 Initializing Database Connection');
  console.log('='.repeat(60));
  console.log('Default database path:', dbPath);

  // Check if custom path is stored in settings
  try {
    const settings = readSettings();
    if (settings.customDbPath) {
      console.log('📌 Custom database path found in settings:', settings.customDbPath);
      if (fs.existsSync(settings.customDbPath)) {
        dbPath = settings.customDbPath;
        console.log('✅ Custom path is accessible, will use it');
      } else {
        console.warn('⚠️ Custom database path not accessible:', settings.customDbPath);
        console.warn('⚠️ This may be due to: offline OneDrive, network issue, or moved file');
        console.warn('⚠️ Falling back to default database...');
        // Use portable path (next to EXE, not inside app.asar)
        dbPath = path.join(appBaseDir, 'database', 'database.db');
      }
    }
  } catch (err) {
    console.error('❌ Error reading settings:', err.message);
  }

  console.log('Connecting to database at:', dbPath);
  connectionResult = connectDatabase(dbPath);
  console.log('Connection result:', connectionResult ? 'Success: ' + connectionResult.success : 'NULL');

  // Check if database connection was successful
  if (!connectionResult || !connectionResult.success || !db) {
    console.error('❌ CRITICAL: Failed to connect to database!');
    console.error('Database path:', dbPath);
    console.error('Connection result:', connectionResult);
    
    // Show professional error dialog with recovery options
    const errorPath = encodeURIComponent(dbPath || 'غير محدد');
    const errorMsg = encodeURIComponent(connectionResult ? connectionResult.error : 'unable to open database file');
    
    app.whenReady().then(() => {
      const errorWindow = new BrowserWindow({
        width: 650,
        height: 750,
        resizable: true,
        minimizable: true,
        maximizable: false,
        center: true,
        title: 'خطأ في قاعدة البيانات',
        webPreferences: {
          nodeIntegration: false,
          contextIsolation: true,
          preload: path.join(__dirname, 'preload.js')
        }
      });
      
      errorWindow.loadFile(path.join(__dirname, 'screens', 'db-error', 'index.html'), {
        query: { path: errorPath, error: errorMsg }
      });
      
      // لا نغلق التطبيق تلقائياً - المستخدم يختار الإجراء
    }).catch((err) => {
      console.error('Failed to show error window:', err);
      const { dialog } = require('electron');
      dialog.showErrorBox('خطأ في الاتصال بقاعدة البيانات', 
        `فشل الاتصال بقاعدة البيانات!\n\nالمسار: ${dbPath}\n\nالخطأ: ${connectionResult ? connectionResult.error : 'غير معروف'}`);
      app.exit(1);
    });
    
    // Don't throw - let the error window handle recovery
    return;
  }
} catch (error) {
  console.error('❌ Fatal error during database initialization:', error.message);
  console.error(error.stack);
  
  // Show professional error dialog
  const errorPath = encodeURIComponent(dbPath || 'غير محدد');
  const errorMsg = encodeURIComponent(error.message || 'unknown error');
  
  app.whenReady().then(() => {
    const errorWindow = new BrowserWindow({
      width: 650,
      height: 700,
      resizable: false,
      frame: false,
      center: true,
      alwaysOnTop: true,
      webPreferences: {
        nodeIntegration: false,
        contextIsolation: true,
        preload: path.join(__dirname, 'preload.js')
      }
    });
    
    errorWindow.loadFile(path.join(__dirname, 'screens', 'db-error', 'index.html'), {
      query: { path: errorPath, error: errorMsg }
    });
  }).catch(() => {
    const { dialog } = require('electron');
    dialog.showErrorBox('خطأ فادح', 'حدث خطأ أثناء تهيئة قاعدة البيانات:\n\n' + error.message);
    app.exit(1);
  });
  
  // Set db to null to prevent further execution
  db = null;
}

// Only continue if database connection succeeded
