// Create categories table for customers/suppliers classification
const createCategoriesTableStmt = db.prepare(`
  CREATE TABLE IF NOT EXISTS categories (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    name TEXT NOT NULL UNIQUE,
    type TEXT DEFAULT 'both',
    created_at TEXT NOT NULL
  )
`);
createCategoriesTableStmt.run();

// Migration: infer category type from actual usage (legacy categories were created with type='both')
try {
  const cats = db.prepare('SELECT id, name, type FROM categories').all();
  const inCustomersStmt = db.prepare('SELECT 1 FROM customers WHERE category = ? LIMIT 1');
  const inSuppliersStmt = db.prepare('SELECT 1 FROM suppliers WHERE category = ? LIMIT 1');
  const updStmt = db.prepare("UPDATE categories SET type = ? WHERE id = ?");

  for (const cat of cats) {
    const currentType = (cat.type || '').toString().trim().toLowerCase();
    if (currentType && currentType !== 'both') continue;

    const inCustomers = !!inCustomersStmt.get(cat.name);
    const inSuppliers = !!inSuppliersStmt.get(cat.name);

    if (inCustomers && !inSuppliers) {
      updStmt.run('customer', cat.id);
    } else if (inSuppliers && !inCustomers) {
      updStmt.run('supplier', cat.id);
    }
  }
} catch (_) {}

