// Create default_boxes table for storing default box settings
function ensureDefaultBoxesTableMigratedSync() {
  try {
    const existingTable = db.prepare("SELECT name FROM sqlite_master WHERE type = 'table' AND name = 'default_boxes'").get();
    if (!existingTable) {
      db.prepare(`
        CREATE TABLE IF NOT EXISTS default_boxes (
          branch_id INTEGER NOT NULL,
          box_type TEXT NOT NULL,
          account_id INTEGER,
          PRIMARY KEY (branch_id, box_type),
          FOREIGN KEY (branch_id) REFERENCES branches(id) ON DELETE CASCADE,
          FOREIGN KEY (account_id) REFERENCES accounts(id)
        )
      `).run();
    } else {
      const tableCols = db.prepare('PRAGMA table_info(default_boxes)').all();
      const hasBranchId = tableCols.some((column) => column.name === 'branch_id');
      if (!hasBranchId) {
        db.prepare('ALTER TABLE default_boxes RENAME TO default_boxes_legacy').run();
        db.prepare(`
          CREATE TABLE IF NOT EXISTS default_boxes (
            branch_id INTEGER NOT NULL,
            box_type TEXT NOT NULL,
            account_id INTEGER,
            PRIMARY KEY (branch_id, box_type),
            FOREIGN KEY (branch_id) REFERENCES branches(id) ON DELETE CASCADE,
            FOREIGN KEY (account_id) REFERENCES accounts(id)
          )
        `).run();
        const mainBranchId = getDefaultMainBranchIdSync();
        try {
          db.prepare(`
            INSERT INTO default_boxes (branch_id, box_type, account_id)
            SELECT ?, box_type, account_id
            FROM default_boxes_legacy
          `).run(mainBranchId);
        } catch (_) {}
        db.prepare('DROP TABLE IF EXISTS default_boxes_legacy').run();
      }
    }

    db.prepare('CREATE INDEX IF NOT EXISTS idx_default_boxes_branch_id ON default_boxes(branch_id)').run();
    db.prepare('CREATE INDEX IF NOT EXISTS idx_default_boxes_account_id ON default_boxes(account_id)').run();
  } catch (e) {
    console.log('Default boxes schema:', e.message);
  }
}

ensureDefaultBoxesTableMigratedSync();

function ensureBranchDefaultBoxesSync(branchId) {
  const normalizedBranchId = Number(branchId || 0) || getDefaultMainBranchIdSync();
  const fallbackCodes = {
    cash: '1111',
    gold: '11211',
    worked_gold: '11221',
    silver: '11231',
    diamond: '11241',
  };
  const matchesBoxType = (code, boxType) => {
    const normalizedCode = String(code || '').trim();
    if (!normalizedCode) return false;
    if (boxType === 'cash') return normalizedCode.startsWith('111') && normalizedCode.length > 3;
    if (boxType === 'gold') return normalizedCode.startsWith('1121') && normalizedCode.length > 4;
    if (boxType === 'worked_gold') return normalizedCode.startsWith('1122') && normalizedCode.length > 4;
    if (boxType === 'silver') return normalizedCode.startsWith('1123') && normalizedCode.length > 4;
    if (boxType === 'diamond') return normalizedCode.startsWith('1124') && normalizedCode.length > 4;
    return false;
  };

  Object.entries(fallbackCodes).forEach(([boxType, fallbackCode]) => {
    const existing = db.prepare('SELECT account_id FROM default_boxes WHERE branch_id = ? AND box_type = ? LIMIT 1').get(normalizedBranchId, boxType);
    let isValid = false;

    if (existing?.account_id) {
      const account = db.prepare(`
        SELECT id, code, is_parent, is_system, branch_id
        FROM accounts
        WHERE id = ?
        LIMIT 1
      `).get(existing.account_id);
      const accountBranchId = Number(account?.branch_id || 0) || null;
      const branchMismatch = accountBranchId && accountBranchId !== normalizedBranchId && Number(account?.is_system || 0) !== 1;
      isValid = Boolean(
        account
        && Number(account?.is_parent || 0) !== 1
        && !branchMismatch
        && matchesBoxType(account?.code, boxType)
      );
    }

    if (isValid) {
      return;
    }

    const fallbackAccount = db.prepare('SELECT id FROM accounts WHERE code = ? LIMIT 1').get(fallbackCode);
    if (!fallbackAccount?.id) {
      return;
    }

    if (existing) {
      db.prepare('UPDATE default_boxes SET account_id = ? WHERE branch_id = ? AND box_type = ?').run(fallbackAccount.id, normalizedBranchId, boxType);
    } else {
      db.prepare('INSERT INTO default_boxes (branch_id, box_type, account_id) VALUES (?, ?, ?)').run(normalizedBranchId, boxType, fallbackAccount.id);
    }
  });
}

function ensureAllBranchesDefaultBoxesSync() {
  try {
    const branches = db.prepare('SELECT id FROM branches').all();
    if (Array.isArray(branches) && branches.length) {
      branches.forEach((branch) => ensureBranchDefaultBoxesSync(branch.id));
      return;
    }
  } catch (_) {}

  ensureBranchDefaultBoxesSync(getDefaultMainBranchIdSync());
}

