// Migration: Create accounts for existing customers without account_id
try {
  const parent114 = db.prepare("SELECT id FROM accounts WHERE code = '114'").get();
  if (parent114) {
    const customersWithoutAccount = db.prepare("SELECT id, name, created_at FROM customers WHERE account_id IS NULL").all();
    // تحديد أسماء الأعمدة الفعلية في الجدول
    const accCols = db.prepare("PRAGMA table_info(accounts)").all().map(c => c.name);
    const hasType = accCols.includes('type');
    const hasAccountType = accCols.includes('account_type');
    const hasImmutable = accCols.includes('immutable');
    const hasIsSystem = accCols.includes('is_system');
    
    // بناء أسماء الأعمدة والقيم ديناميكياً
    let typeCols = '', typeVals = '';
    if (hasType && hasAccountType) {
      typeCols = 'type, account_type'; typeVals = "'asset', 'asset'";
    } else if (hasAccountType) {
      typeCols = 'account_type'; typeVals = "'asset'";
    } else {
      typeCols = 'type'; typeVals = "'asset'";
    }
    
    let sysCols = '', sysVals = '';
    if (hasImmutable && hasIsSystem) {
      sysCols = 'immutable, is_system'; sysVals = '0, 0';
    } else if (hasIsSystem) {
      sysCols = 'is_system'; sysVals = '0';
    } else {
      sysCols = 'immutable'; sysVals = '0';
    }
    
    for (const cust of customersWithoutAccount) {
      const accountCode = `114${cust.id}`;
      const existingAcc = db.prepare("SELECT id FROM accounts WHERE code = ?").get(accountCode);
      if (!existingAcc) {
        const accResult = db.prepare(`
          INSERT INTO accounts (code, name, name_en, parent_id, ${typeCols}, nature, level, is_parent, ${sysCols}, active, created_at)
          VALUES (?, ?, ?, ?, ${typeVals}, 'debit', 4, 0, ${sysVals}, 1, ?)
        `).run(accountCode, cust.name, cust.name, parent114.id, cust.created_at || getLocalDateTime());
        db.prepare("UPDATE customers SET account_id = ? WHERE id = ?").run(accResult.lastInsertRowid, cust.id);
      } else {
        db.prepare("UPDATE customers SET account_id = ? WHERE id = ?").run(existingAcc.id, cust.id);
      }
    }
    if (customersWithoutAccount.length > 0) {
      console.log(`✅ Created accounts for ${customersWithoutAccount.length} existing customers`);
    }
  }
} catch(e) {
  console.log('Customer accounts migration:', e.message);
}

