const createUserMessagesTableStmt = db.prepare(`
  CREATE TABLE IF NOT EXISTS user_messages (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    sender_user_id INTEGER NOT NULL,
    recipient_user_id INTEGER NOT NULL,
    message_text TEXT NOT NULL,
    message_type TEXT DEFAULT 'text',
    delivery_status TEXT DEFAULT 'sent',
    read_at TEXT,
    created_at TEXT NOT NULL,
    updated_at TEXT NOT NULL,
    FOREIGN KEY (sender_user_id) REFERENCES users(id) ON DELETE CASCADE,
    FOREIGN KEY (recipient_user_id) REFERENCES users(id) ON DELETE CASCADE
  )
`);
createUserMessagesTableStmt.run();

try {
  const userBranchCols = db.prepare('PRAGMA table_info(user_branches)').all();
  const userBranchColNames = userBranchCols.map((c) => c.name);
  if (!userBranchColNames.includes('is_default')) {
    db.prepare('ALTER TABLE user_branches ADD COLUMN is_default INTEGER DEFAULT 0').run();
  }
  if (!userBranchColNames.includes('can_login')) {
    db.prepare('ALTER TABLE user_branches ADD COLUMN can_login INTEGER DEFAULT 1').run();
  }
  if (!userBranchColNames.includes('read_only')) {
    db.prepare('ALTER TABLE user_branches ADD COLUMN read_only INTEGER DEFAULT 0').run();
  }
  if (!userBranchColNames.includes('created_at')) {
    db.prepare('ALTER TABLE user_branches ADD COLUMN created_at TEXT').run();
  }

  const mainBranchId = getDefaultMainBranchIdSync();
  const users = db.prepare(`
    SELECT u.id
    FROM users u
    WHERE NOT EXISTS (
      SELECT 1 FROM user_branches ub WHERE ub.user_id = u.id
    )
    ORDER BY u.id ASC
  `).all();
  const insertUserBranchStmt = db.prepare(`
    INSERT OR IGNORE INTO user_branches (user_id, branch_id, is_default, can_login, read_only, created_at)
    VALUES (?, ?, ?, 1, 0, ?)
  `);
  const nowIso = new Date().toISOString();
  for (const user of users) {
    insertUserBranchStmt.run(user.id, mainBranchId, 1, nowIso);
  }
  db.prepare(`
    UPDATE user_branches
    SET created_at = COALESCE(created_at, ?), can_login = COALESCE(can_login, 1), read_only = COALESCE(read_only, 0)
    WHERE created_at IS NULL OR can_login IS NULL OR read_only IS NULL
  `).run(nowIso);
  db.prepare(`
    UPDATE user_branches
    SET is_default = 1
    WHERE (user_id, branch_id) IN (
      SELECT ub.user_id, ub.branch_id
      FROM user_branches ub
      JOIN (
        SELECT user_id, MIN(branch_id) AS branch_id
        FROM user_branches
        GROUP BY user_id
      ) first_branch ON first_branch.user_id = ub.user_id AND first_branch.branch_id = ub.branch_id
      WHERE ub.user_id NOT IN (
        SELECT user_id FROM user_branches WHERE COALESCE(is_default, 0) = 1
      )
    )
  `).run();
  db.prepare('CREATE INDEX IF NOT EXISTS idx_user_branches_branch_id ON user_branches(branch_id)').run();
} catch (e) {
  console.log('User branches migration:', e.message);
}

