// Migration: Update old reports permissions naming
try {
  const oldToNew = [
    {old: 'reports.view', new: 'reports_view_statement'},
    {old: 'reports.customer_statement', new: 'reports_view_statement'},
    {old: 'reports.supplier_statement', new: 'reports_view_statement'},
    {old: 'reports.account_statement', new: 'reports_view_statement'},
    {old: 'reports.export', new: 'reports_export'}
  ];
  
  oldToNew.forEach(mapping => {
    const oldPerm = db.prepare("SELECT id FROM permissions WHERE name = ?").get(mapping.old);
    const newPerm = db.prepare("SELECT id FROM permissions WHERE name = ?").get(mapping.new);
    
    if (oldPerm && newPerm) {
      // Copy user permissions from old to new
      const userPerms = db.prepare("SELECT user_id FROM user_permissions WHERE permission_id = ?").all(oldPerm.id);
      const grantPerm = db.prepare('INSERT OR IGNORE INTO user_permissions (user_id, permission_id, granted_at) VALUES (?, ?, ?)');
      const now = new Date().toISOString();
      
      userPerms.forEach(up => {
        grantPerm.run(up.user_id, newPerm.id, now);
      });
      
      // Delete old permission
      db.prepare("DELETE FROM user_permissions WHERE permission_id = ?").run(oldPerm.id);
      db.prepare("DELETE FROM permissions WHERE id = ?").run(oldPerm.id);
    }
  });
} catch(e) { }

