// Ensure default admin (Smart Accountant) ALWAYS has ALL permissions on every startup
// This guarantees full permissions even if they were removed manually
try {
  const defaultAdmin = db.prepare("SELECT id FROM users WHERE username = 'Smart Accountant'").get();
  if (defaultAdmin && defaultAdmin.id) {
    // Delete all existing permissions for default admin first
    db.prepare('DELETE FROM user_permissions WHERE user_id = ?').run(defaultAdmin.id);
    
    // Re-grant ALL permissions
    const allPermissions = db.prepare('SELECT id FROM permissions').all();
    const grantAllPerms = db.prepare('INSERT INTO user_permissions (user_id, permission_id, granted_at) VALUES (?, ?, ?)');
    const now = new Date().toISOString();
    allPermissions.forEach(perm => {
      try {
        grantAllPerms.run(defaultAdmin.id, perm.id, now);
      } catch (e) {}
    });
    console.log('✅ Default admin (Smart Accountant) granted ALL permissions');
  }
} catch (e) {
  console.error('Error ensuring default admin permissions:', e.message);
}

