 let win;
 let licenseWatchdogTimer = null;

function attachSmartErrorDevTools(targetWindow) {
  if (!targetWindow || targetWindow.isDestroyed() || !targetWindow.webContents) return;
  const wc = targetWindow.webContents;
  let lastOpenAt = 0;

  const openForError = (reason, details = '') => {
    try {
      const now = Date.now();
      if (now - lastOpenAt < 1500) return;
      lastOpenAt = now;
      console.error(`[Main] Smart DevTools trigger: ${reason}${details ? ` :: ${details}` : ''}`);
      if (!wc.isDestroyed() && !wc.isDevToolsOpened()) {
        wc.openDevTools({ mode: 'detach', activate: true });
      }
    } catch (_) {}
  };

  wc.on('did-fail-load', (_event, errorCode, errorDescription, validatedURL) => {
    openForError('did-fail-load', `${errorCode} ${errorDescription || ''} ${validatedURL || ''}`.trim());
  });

  wc.on('preload-error', (_event, preloadPath, error) => {
    openForError('preload-error', `${preloadPath || ''} ${error?.message || error || ''}`.trim());
  });

  wc.on('render-process-gone', (_event, details) => {
    openForError('render-process-gone', `${details?.reason || ''} ${details?.exitCode || ''}`.trim());
  });

  wc.on('console-message', (_event, detailsOrLevel, legacyMessage, legacyLine, legacySourceId) => {
    const details = (detailsOrLevel && typeof detailsOrLevel === 'object' && !Array.isArray(detailsOrLevel))
      ? detailsOrLevel
      : {
          level: detailsOrLevel,
          message: legacyMessage,
          line: legacyLine,
          sourceId: legacySourceId,
        };
    const text = String(details?.message || '').trim();
    const src = String(details?.sourceId || '').trim();
    const normalized = text.toLowerCase();
    const numericLevel = Number(details?.level);
    const isConsoleErrorLevel = Number.isFinite(numericLevel) && numericLevel >= 3;
    const hasErrorSignature = /uncaught|unhandled(?:\s+promise)?(?:\s+rejection)?|exception|typeerror|referenceerror|syntaxerror/.test(normalized);
    if ((!isConsoleErrorLevel && !hasErrorSignature) || !text) return;
    if (normalized.includes('favicon')) return;
    if (src.startsWith('devtools://')) return;
    openForError('console-message', `${src}:${details?.line || 0} ${text}`.trim());
  });

  targetWindow.on('unresponsive', () => {
    openForError('window-unresponsive');
  });
}

function getInitialAppScreen() {
  try {
    const status = licenseManager.checkLicenseStatus(licenseDataPath);
    if (status && (status.licensed === true || status.valid === true)) {
      return path.join(__dirname, 'screens', 'login', 'index.html');
    }
  } catch (_) {}
  return path.join(__dirname, 'screens', 'activation', 'index.html');
}

function createWindow() {
   const area = screen.getPrimaryDisplay ? screen.getPrimaryDisplay().workAreaSize : { width: 1440, height: 900 };
   win = new BrowserWindow({
     width: Math.max(1280, Math.min(area.width, 1600)),
     height: Math.max(760, Math.min(area.height, 1000)),
     minWidth: 1100,
     minHeight: 680,
     show: false,
     autoHideMenuBar: true,
     backgroundColor: '#0f172a',
     webPreferences: {
       preload: path.join(__dirname, 'preload.js'),
       contextIsolation: true,
       nodeIntegration: false,
     }
   });

   attachSmartErrorDevTools(win);

   const enforceCurrentWindowLicense = () => {
     try {
       if (!win || win.isDestroyed() || !win.webContents) return;
       const currentPath = getFilePathFromUrl(win.webContents.getURL() || '');
       if (isProtectedScreenFile(currentPath) && !isLicenseActive()) {
         redirectToActivation(win);
       }
     } catch (_) {}
   };

   win.webContents.on('will-navigate', (event, targetUrl) => {
     const targetPath = getFilePathFromUrl(targetUrl || '');
     if (!isProtectedScreenFile(targetPath) || isLicenseActive()) {
       return;
     }
     event.preventDefault();
     redirectToActivation(win);
   });

   win.webContents.on('did-finish-load', () => {
     enforceCurrentWindowLicense();
   });

   try {
     Menu.setApplicationMenu(null);
   } catch (_) {}

   win.once('ready-to-show', () => {
     try {
       if (win && !win.isDestroyed()) {
         win.maximize();
         win.show();
       }
     } catch (_) {}
   });
 win.on('closed', () => {
     try {
       if (licenseWatchdogTimer) {
         clearInterval(licenseWatchdogTimer);
         licenseWatchdogTimer = null;
       }
     } catch (_) {}
     win = null;
   });

   win.on('focus', () => {
     enforceCurrentWindowLicense();
   });

   try {
     if (licenseWatchdogTimer) {
       clearInterval(licenseWatchdogTimer);
     }
   } catch (_) {}
   licenseWatchdogTimer = setInterval(() => {
     enforceCurrentWindowLicense();
   }, 15000);
   try {
     if (licenseWatchdogTimer && typeof licenseWatchdogTimer.unref === 'function') {
       licenseWatchdogTimer.unref();
     }
   } catch (_) {}

   const initialScreen = getInitialAppScreen();
   win.loadFile(initialScreen).catch((error) => {
     console.error('[Main] Failed to load initial screen:', error.message);
   });

   return win;
 }

 let mt5Proc = null;
 let mt5BridgeStdout = null;
 let mt5BridgeStderr = null;
 let mt5BridgeRequestSeq = 0;
 let mt5HourlyReconnectTimer = null;
 let mt5OrdersMonitorTimer = null;
 const mt5PendingRequests = new Map();
 const mt5LatestTicks = new Map();

 function broadcastToAllWindows(channel, payload) {
   try {
     const windows = BrowserWindow.getAllWindows();
     windows.forEach((browserWindow) => {
       try {
         if (!browserWindow || browserWindow.isDestroyed() || !browserWindow.webContents) return;
         browserWindow.webContents.send(channel, payload);
       } catch (_) {}
     });
   } catch (_) {}
 }

 function rejectAllMt5PendingRequests(error) {
   const err = error instanceof Error ? error : new Error(String(error || 'MT5 bridge stopped'));
   for (const pending of mt5PendingRequests.values()) {
     try {
       clearTimeout(pending.timeoutId);
       pending.reject(err);
     } catch (_) {}
   }
   mt5PendingRequests.clear();
 }

 function rememberMt5Tick(message) {
   const symbol = String(message?.symbol || '').trim();
   if (!symbol) return;

   const bid = Number(message?.bid);
   const ask = Number(message?.ask);
   const mid = Number(message?.mid);
   const prevClose = Number(message?.prev_close);
   const ts = Number(message?.ts);

   const tick = {
     symbol,
     bid: Number.isFinite(bid) ? bid : null,
     ask: Number.isFinite(ask) ? ask : null,
     mid: Number.isFinite(mid) ? mid : null,
     prev_close: Number.isFinite(prevClose) ? prevClose : null,
     ts: Number.isFinite(ts) ? ts : Date.now(),
   };

   const upper = symbol.toUpperCase();
   const keys = new Set([symbol, upper]);
   if (upper.endsWith('M') && upper.length > 1) {
     keys.add(upper.slice(0, -1));
   }

   for (const key of keys) {
     mt5LatestTicks.set(key, tick);
   }
 }

 function getLatestMt5Tick(...symbols) {
   for (const candidate of symbols) {
     const value = String(candidate || '').trim();
     if (!value) continue;
     const direct = mt5LatestTicks.get(value);
     if (direct) return direct;
     const upper = value.toUpperCase();
     const upperMatch = mt5LatestTicks.get(upper);
     if (upperMatch) return upperMatch;
     if (!upper.endsWith('M')) {
       const suffixed = mt5LatestTicks.get(`${upper}M`);
       if (suffixed) return suffixed;
     }
   }
   return null;
 }

 function resolveMt5BridgeLaunchSpec() {
   const exeCandidates = [];
   const scriptCandidates = [];

   if (app.isPackaged) {
     exeCandidates.push(
       path.join(process.resourcesPath, 'mt5_bridge.exe'),
       path.join(process.resourcesPath, 'resources', 'mt5_bridge.exe')
     );
     scriptCandidates.push(
       path.join(process.resourcesPath, 'mt5_bridge.py'),
       path.join(process.resourcesPath, 'resources', 'mt5_bridge.py')
     );
   } else {
     exeCandidates.push(path.join(__dirname, 'resources', 'mt5_bridge.exe'));
     scriptCandidates.push(path.join(__dirname, 'resources', 'mt5_bridge.py'));
   }

   const bridgeExe = exeCandidates.find(candidate => fs.existsSync(candidate));
   if (bridgeExe) {
     return {
       command: bridgeExe,
       args: ['--symbols', 'XAUUSDm,XAGUSDm', '--poll-ms', '150', '--heartbeat-ms', '1000'],
       cwd: path.dirname(bridgeExe),
     };
   }

   const bridgeScript = scriptCandidates.find(candidate => fs.existsSync(candidate));
   if (bridgeScript) {
     const pythonCommand = process.env.PYTHON || 'python';
     return {
       command: pythonCommand,
       args: [bridgeScript, '--symbols', 'XAUUSDm,XAGUSDm', '--poll-ms', '150', '--heartbeat-ms', '1000'],
       cwd: path.dirname(bridgeScript),
     };
   }

   return null;
 }

 function handleMt5BridgeLine(line) {
   let message = null;
   try {
     message = JSON.parse(String(line || '').trim());
   } catch (_) {
     return;
   }

   if (!message || typeof message !== 'object') return;

   if (message.type === 'tick') {
     rememberMt5Tick(message);
     return;
   }

   if (message.type === 'response') {
     const requestId = Number(message.id);
     if (!Number.isFinite(requestId)) return;
     const pending = mt5PendingRequests.get(requestId);
     if (!pending) return;
     clearTimeout(pending.timeoutId);
     mt5PendingRequests.delete(requestId);
     if (message.ok) {
       pending.resolve(message.data || {});
     } else {
       const error = new Error(message.error || 'MT5 bridge command failed');
       error.data = message.data || null;
       pending.reject(error);
     }
     return;
   }

   if (message.type === 'error') {
     console.error('[MT5] Bridge error:', message.message || message.error || JSON.stringify(message));
     return;
   }
 }

 function startMt5Bridge() {
   if (mt5Proc && !mt5Proc.killed) {
     return true;
   }

   const launchSpec = resolveMt5BridgeLaunchSpec();
   if (!launchSpec) {
     console.warn('[MT5] Bridge executable/script not found');
     return false;
   }

   try {
     mt5Proc = spawn(launchSpec.command, launchSpec.args, {
       cwd: launchSpec.cwd,
       stdio: ['pipe', 'pipe', 'pipe'],
       windowsHide: true,
     });
   } catch (error) {
     mt5Proc = null;
     console.error('[MT5] Failed to start bridge:', error.message);
     return false;
   }

   mt5BridgeStdout = readline.createInterface({ input: mt5Proc.stdout });
   mt5BridgeStdout.on('line', handleMt5BridgeLine);

   mt5BridgeStderr = readline.createInterface({ input: mt5Proc.stderr });
   mt5BridgeStderr.on('line', (line) => {
     const text = String(line || '').trim();
     if (text) {
       console.log('[MT5][stderr]', text);
     }
   });

   mt5Proc.on('error', (error) => {
     console.error('[MT5] Bridge process error:', error.message);
     rejectAllMt5PendingRequests(error);
   });

   mt5Proc.on('exit', (code, signal) => {
     console.warn(`[MT5] Bridge exited (code=${code}, signal=${signal || 'none'})`);
     try {
       mt5BridgeStdout?.close();
     } catch (_) {}
     try {
       mt5BridgeStderr?.close();
     } catch (_) {}
     mt5BridgeStdout = null;
     mt5BridgeStderr = null;
     mt5Proc = null;
     rejectAllMt5PendingRequests(new Error('MT5 bridge stopped'));
   });

   return true;
 }

 function stopMt5Bridge() {
   if (mt5HourlyReconnectTimer) {
     clearInterval(mt5HourlyReconnectTimer);
     mt5HourlyReconnectTimer = null;
   }
   if (mt5OrdersMonitorTimer) {
     clearInterval(mt5OrdersMonitorTimer);
     mt5OrdersMonitorTimer = null;
   }
   if (!mt5Proc) return;
   try {
     rejectAllMt5PendingRequests(new Error('MT5 bridge stopped'));
     mt5Proc.kill();
   } catch (_) {}
   mt5Proc = null;
 }

 function requestMt5Restart(reason = 'MT5 restart requested') {
   console.log('[MT5]', reason);
   stopMt5Bridge();
   setTimeout(() => {
     try {
       startMt5Bridge();
       startMt5HourlyReconnect();
       startMt5OrdersMonitor();
     } catch (error) {
       console.error('[MT5] Restart failed:', error.message);
     }
   }, 300);
 }

 function startMt5HourlyReconnect() {
   if (mt5HourlyReconnectTimer) {
     clearInterval(mt5HourlyReconnectTimer);
   }
   mt5HourlyReconnectTimer = setInterval(() => {
     requestMt5Restart('Scheduled MT5 reconnect');
   }, 60 * 60 * 1000);
 }

 function sendMt5BridgeCommand(payload, timeoutMs = 15000) {
   return new Promise((resolve, reject) => {
     if (!mt5Proc || !mt5Proc.stdin || !mt5Proc.stdin.writable) {
       reject(new Error('MT5 bridge not running'));
       return;
     }

     const requestId = ++mt5BridgeRequestSeq;
     const timeoutId = setTimeout(() => {
       mt5PendingRequests.delete(requestId);
       reject(new Error('MT5 bridge timeout'));
     }, Math.max(1000, Number(timeoutMs) || 15000));

     mt5PendingRequests.set(requestId, { resolve, reject, timeoutId });

     try {
       mt5Proc.stdin.write(`${JSON.stringify({ ...(payload || {}), id: requestId })}\n`);
     } catch (error) {
       clearTimeout(timeoutId);
       mt5PendingRequests.delete(requestId);
       reject(error);
     }
   });
 }

 async function pollMt5PendingOrders() {
   if (!mt5Proc || !mt5Proc.stdin || !mt5Proc.stdin.writable) return;

   let rows = [];
   try {
     rows = await tursoSync.queryAll(`
       SELECT id, mt5_order_ticket, mt5_symbol, mt5_volume, mt5_price, created_by, modified_by
       FROM orders
       WHERE execute_on_mt5 = 1
         AND status IN ('pending', 'processing')
         AND mt5_order_ticket IS NOT NULL
         AND TRIM(mt5_order_ticket) <> ''
     `);
   } catch (_) {
     return;
   }

   for (const row of rows) {
     const orderId = Number(row?.id || 0);
     const orderTicket = String(row?.mt5_order_ticket || '').trim();
     if (!Number.isFinite(orderId) || orderId <= 0 || !orderTicket) continue;

     try {
       const result = await sendMt5BridgeCommand({ cmd: 'deal_by_order', ticket: orderTicket }, 15000);
       if (!result || result.found !== true || !result.deal) continue;

       const dt = getLocalDateTime();
       const parts = String(dt || '').split(' ');
       const executionDate = parts[0] || null;
       const executionTime = parts[1] || null;

       await tursoSync.run(`
         UPDATE orders SET
           status = ?,
           execution_date = ?,
           execution_time = ?,
           mt5_deal_ticket = ?,
           mt5_symbol = ?,
           mt5_volume = ?,
           mt5_price = ?,
           mt5_error = NULL,
           modified_at = ?
         WHERE id = ?
       `, [
         'completed',
         executionDate,
         executionTime,
         String(result.deal),
         result.symbol ? String(result.symbol) : (row?.mt5_symbol || null),
         Number(result.volume != null ? result.volume : row?.mt5_volume) || null,
         Number(result.price != null ? result.price : row?.mt5_price) || null,
         dt,
         orderId
       ]);

       broadcastToAllWindows('orders-updated', {
         id: orderId,
         orderId,
         status: 'completed',
         originDeviceId: currentDeviceId,
       });

       broadcastCloudDataUpdated({
         source: 'local',
         action: 'update',
         tables: ['orders'],
         entityType: 'orders',
         documentId: orderId,
         orderId,
         branchId: normalizePositiveId(row?.branch_id, getDefaultMainBranchIdSync()) || getDefaultMainBranchIdSync(),
         actorUserId: Number(row?.modified_by || row?.created_by) || null,
         actorName: await resolveUserDisplayNameById(row?.modified_by || row?.created_by),
         notificationSubType: 'ordersCompleted',
         status: 'completed',
         changes: 1,
       });
     } catch (_) {}
   }
 }

 function startMt5OrdersMonitor() {
   if (mt5OrdersMonitorTimer) {
     clearInterval(mt5OrdersMonitorTimer);
   }
   mt5OrdersMonitorTimer = setInterval(() => {
     pollMt5PendingOrders().catch(() => {});
   }, 15000);
 }

// ===== Generic database query handler =====
// This must be registered BEFORE any window creation
ipcMain.handle('db-query', async (event, payload) => {
  try {
    const { sql, params } = payload;
    
    if (!sql) {
      return [];
    }
    
    const trimmedSql = sql.trim();
    
    // Use tursoSync for cloud/local queries
    if (trimmedSql.toUpperCase().startsWith('SELECT')) {
      const rows = await tursoSync.queryAll(trimmedSql, params || []);
      return rows; // Return array directly
    } else {
      const result = await tursoSync.run(trimmedSql, params || []);
      return { success: true, changes: result.rowsAffected, lastInsertRowid: result.lastInsertRowid };
    }
  } catch (error) {
    console.error('db-query error:', error.message);
    console.error('SQL:', payload?.sql);
    console.error('Params:', payload?.params);
    return [];
  }
});

