 function buildLiveMarketSnapshot() {
  try {
    const xauTick = getLatestMt5Tick('XAUUSDm', 'XAUUSD');
    const xagTick = getLatestMt5Tick('XAGUSDm', 'XAGUSD');

    if (!xauTick) {
      return {
        success: false,
        error: mt5Proc && mt5Proc.stdin && mt5Proc.stdin.writable ? 'MT5 price not available yet' : 'MT5 bridge not running',
        source: 'mt5'
      };
    }

    const xauBid = Number(xauTick?.bid);
    const xauAsk = Number(xauTick?.ask);
    const xauMid = Number(xauTick?.mid);
    const xauPrice = Number.isFinite(xauMid)
      ? xauMid
      : ((Number.isFinite(xauBid) ? xauBid : 0) + (Number.isFinite(xauAsk) ? xauAsk : 0)) / 2;
    const xauPrevClose = Number(xauTick?.prev_close);
    const xauChange = Number.isFinite(xauPrevClose) && xauPrevClose !== 0 ? xauPrice - xauPrevClose : 0;
    const xauPercent = Number.isFinite(xauPrevClose) && xauPrevClose !== 0 ? (xauChange / xauPrevClose) * 100 : 0;

    let xagPrice = null;
    let xagChange = 0;
    let xagPercent = 0;
    if (xagTick) {
      const xagBid = Number(xagTick?.bid);
      const xagAsk = Number(xagTick?.ask);
      const xagMid = Number(xagTick?.mid);
      xagPrice = Number.isFinite(xagMid)
        ? xagMid
        : ((Number.isFinite(xagBid) ? xagBid : 0) + (Number.isFinite(xagAsk) ? xagAsk : 0)) / 2;
      const xagPrevClose = Number(xagTick?.prev_close);
      xagChange = Number.isFinite(xagPrevClose) && xagPrevClose !== 0 ? xagPrice - xagPrevClose : 0;
      xagPercent = Number.isFinite(xagPrevClose) && xagPrevClose !== 0 ? (xagChange / xagPrevClose) * 100 : 0;
    }

    return {
      success: true,
      source: 'mt5',
      price: xauPrice,
      bid: Number.isFinite(xauBid) ? xauBid : null,
      ask: Number.isFinite(xauAsk) ? xauAsk : null,
      change: xauChange,
      percent: xauPercent,
      ts: Number(xauTick?.ts || Date.now()),
      xagPrice,
      xagChange,
      xagPercent,
    };
  } catch (error) {
    return { success: false, error: error?.message || String(error), source: 'mt5' };
  }
 }

