function sanitizeExportFileSegment(value = '') {
  return String(value || '')
    .trim()
    .replace(/[<>:"/\\|?*\u0000-\u001F]+/g, ' ')
    .replace(/\s+/g, '-')
    .replace(/-+/g, '-')
    .replace(/^-|-$/g, '')
    .slice(0, 48);
}

function buildExportTimestamp(date = new Date()) {
  const year = date.getFullYear();
  const month = String(date.getMonth() + 1).padStart(2, '0');
  const day = String(date.getDate()).padStart(2, '0');
  const hours = String(date.getHours()).padStart(2, '0');
  const minutes = String(date.getMinutes()).padStart(2, '0');
  const seconds = String(date.getSeconds()).padStart(2, '0');
  return `${year}${month}${day}-${hours}${minutes}${seconds}`;
}

function getAssistantStatementExportDir() {
  const dir = path.join(dataDir, 'assistant-exports', 'statements');
  try {
    fs.mkdirSync(dir, { recursive: true });
  } catch (_) {}
  return dir;
}

function toFileUri(filePath = '') {
  if (!filePath) return '';
  return `file:///${String(filePath).replace(/\\/g, '/')}`;
}

async function waitForRenderedWindow(browserWindow, delayMs = 350) {
  if (!browserWindow || browserWindow.isDestroyed() || !browserWindow.webContents) {
    return;
  }
  try {
    await browserWindow.webContents.executeJavaScript(`
      (async () => {
        try {
          if (document.fonts && document.fonts.ready) {
            await document.fonts.ready;
          }
        } catch (_) {}
        await new Promise((resolve) => setTimeout(resolve, ${Math.max(0, Number(delayMs) || 0)}));
        return true;
      })()
    `, true);
  } catch (_) {}
}

function destroyBrowserWindowSafe(browserWindow) {
  try {
    if (browserWindow && !browserWindow.isDestroyed()) {
      browserWindow.destroy();
    }
  } catch (_) {}
}

async function exportAssistantStatement(payload = {}) {
  const type = String(payload?.type || '').trim().toLowerCase();
  const entityId = Number(payload?.id || 0);
  const entityName = String(payload?.name || '').trim();
  const orientation = String(payload?.orientation || 'portrait').trim().toLowerCase() === 'landscape' ? 'landscape' : 'portrait';
  const model = ['all', 'both', 'silver_cash', 'cash', 'gold', 'silver'].includes(String(payload?.model || '').trim().toLowerCase())
    ? String(payload.model).trim().toLowerCase()
    : 'both';
  const template = ['normal', 'simple', 'detailed', 'gold_detailed', 'accounting'].includes(String(payload?.template || '').trim().toLowerCase())
    ? String(payload.template).trim().toLowerCase()
    : 'normal';
  const definition = payload?.definition || null;
  const row = payload?.row && typeof payload.row === 'object' ? payload.row : {};
  const branchWindowContext = normalizeReportsBranchWindowContext(payload);

  if (!['customer', 'supplier', 'account'].includes(type)) {
    return { success: false, error: 'نوع كشف الحساب غير مدعوم حالياً.' };
  }

  if (!Number.isFinite(entityId) || entityId <= 0) {
    return { success: false, error: 'رقم العنصر غير صالح لتصدير كشف الحساب.' };
  }

  const reportsFilePath = path.join(__dirname, 'screens', 'reports', 'index.html');
  const exportDir = getAssistantStatementExportDir();
  const timestamp = buildExportTimestamp(new Date());
  const safeName = sanitizeExportFileSegment(entityName || String(row?.name || ''));
  const baseName = ['statement', type, String(entityId), safeName || null, timestamp].filter(Boolean).join('-');
  const pdfPath = path.join(exportDir, `${baseName}.pdf`);
  const pngPath = path.join(exportDir, `${baseName}.png`);
  let reportWindow = null;
  let previewWindow = null;

  try {
    reportWindow = new BrowserWindow({
      show: false,
      width: orientation === 'landscape' ? 1680 : 1480,
      height: orientation === 'landscape' ? 1080 : 1200,
      autoHideMenuBar: true,
      backgroundColor: '#ffffff',
      paintWhenInitiallyHidden: true,
      webPreferences: {
        preload: path.join(__dirname, 'preload.js'),
        contextIsolation: true,
        nodeIntegration: false,
      }
    });
    try { reportWindow.setMenuBarVisibility(false); } catch (_) {}
    await reportWindow.loadFile(reportsFilePath, {
      query: {
        embedded: 'true',
        entityType: type,
        refId: String(entityId),
        branchScope: branchWindowContext.branchScopeMode,
        branchId: branchWindowContext.branchId ? String(branchWindowContext.branchId) : '',
        allowedBranchIds: branchWindowContext.allowedBranchIds.join(','),
        branchCode: branchWindowContext.branchCode,
        branchName: branchWindowContext.branchName,
        autoLoad: 'false',
      }
    });
    await waitForRenderedWindow(reportWindow, 450);

    const printResult = await reportWindow.webContents.executeJavaScript(`
      (async () => {
        const btnOpenStatement = document.getElementById('btnOpenStatement');
        if (btnOpenStatement && !btnOpenStatement.classList.contains('active')) {
          btnOpenStatement.click();
        }
        const typeSelect = document.getElementById('p_stmt_type');
        const refIdInput = document.getElementById('p_stmt_ref_id');
        const modelSelect = document.getElementById('p_stmt_model');
        const templateSelect = document.getElementById('p_stmt_template');
        if (!typeSelect || !refIdInput) {
          throw new Error('Statement controls are not available');
        }
        typeSelect.value = ${JSON.stringify(type)};
        if (modelSelect) {
          modelSelect.value = ${JSON.stringify(model)};
        }
        if (templateSelect) {
          templateSelect.value = ${JSON.stringify(template)};
        }
        refIdInput.value = ${JSON.stringify(String(entityId))};
        const fetcher = window.fetchStatement || (typeof fetchStatement === 'function' ? fetchStatement : null);
        if (typeof fetcher !== 'function') {
          throw new Error('fetchStatement is not available');
        }
        await fetcher();
        await new Promise((resolve) => setTimeout(resolve, 250));
        const rowCount = Array.from(document.querySelectorAll('#stmt_body_p tr'))
          .filter((row) => row && row.querySelectorAll('td').length > 0).length;
        if (!rowCount) {
          throw new Error('لم يتم العثور على بيانات لكشف الحساب المطلوب.');
        }
        if (typeof window.generateStatementPrintDocument !== 'function') {
          throw new Error('generateStatementPrintDocument is not available');
        }
        return await window.generateStatementPrintDocument({
          template: ${JSON.stringify(template)},
          model: ${JSON.stringify(model)},
          type: ${JSON.stringify(type)},
          refId: ${JSON.stringify(String(entityId))},
          entityData: ${JSON.stringify({
            id: entityId,
            name: entityName || String(row?.name || ''),
            full_name: String(row?.full_name || ''),
            company: String(row?.company || ''),
            region: String(row?.region || ''),
            address: String(row?.address || ''),
            full_address: String(row?.full_address || ''),
            tax_no: String(row?.tax_no || ''),
            tax_number: String(row?.tax_number || ''),
            tax_id: String(row?.tax_id || ''),
            code: String(row?.code || row?.account_number || ''),
          })}
        });
      })();
    `, true);

    const docHtml = String(printResult?.html || '').trim();
    if (!docHtml) {
      throw new Error('تعذر توليد مستند كشف الحساب.');
    }

    destroyBrowserWindowSafe(reportWindow);
    reportWindow = null;

    previewWindow = new BrowserWindow({
      show: false,
      width: orientation === 'landscape' ? 1980 : 1400,
      height: orientation === 'landscape' ? 1400 : 1980,
      autoHideMenuBar: true,
      backgroundColor: '#ffffff',
      paintWhenInitiallyHidden: true,
      webPreferences: {
        contextIsolation: true,
        nodeIntegration: false,
      }
    });
    try { previewWindow.setMenuBarVisibility(false); } catch (_) {}
    const dataUrl = 'data:text/html;charset=utf-8,' + encodeURIComponent(docHtml);
    await previewWindow.loadURL(dataUrl);
    await waitForRenderedWindow(previewWindow, 650);

    const pdfBuffer = await previewWindow.webContents.printToPDF({
      printBackground: true,
      preferCSSPageSize: true,
      landscape: orientation === 'landscape',
      margins: { top: 0, bottom: 0, left: 0, right: 0 },
    });
    const capturedImage = await previewWindow.webContents.capturePage();

    fs.writeFileSync(pdfPath, pdfBuffer);
    fs.writeFileSync(pngPath, capturedImage.toPNG());

    const entityTypeLabel = definition?.label || (type === 'customer' ? 'العميل' : type === 'supplier' ? 'المورد' : 'الحساب');
    const attachmentTitle = `كشف حساب ${entityTypeLabel} ${entityName || `رقم ${entityId}`}`;

    return {
      success: true,
      attachment: {
        kind: 'statement_export',
        title: attachmentTitle,
        subtitle: `تم إنشاء ملف PDF مع معاينة سريعة للصورة بالنمط ${orientation === 'landscape' ? 'الأفقي' : 'العمودي'}.`,
        entityType: type,
        entityLabel: entityTypeLabel,
        entityName: entityName || '',
        entityId,
        orientation,
        pdfPath,
        pdfUrl: toFileUri(pdfPath),
        previewPath: pngPath,
        previewUrl: toFileUri(pngPath),
        folderPath: exportDir,
        fileName: path.basename(pdfPath),
        createdAt: new Date().toISOString(),
      }
    };
  } catch (error) {
    return {
      success: false,
      error: error?.message || 'تعذر تصدير كشف الحساب.'
    };
  } finally {
    destroyBrowserWindowSafe(reportWindow);
    destroyBrowserWindowSafe(previewWindow);
  }
}

ipcMain.handle('assistant-save-generated-file', async (_e, payload = {}) => {
  try {
    const sourcePath = String(payload?.sourcePath || '').trim();
    if (!sourcePath || !fs.existsSync(sourcePath)) {
      return { success: false, error: 'الملف المطلوب غير موجود.' };
    }

    const fallbackName = path.basename(sourcePath);
    const defaultName = String(payload?.defaultName || fallbackName).trim() || fallbackName;
    const extension = path.extname(defaultName || sourcePath).replace(/^\./, '').toLowerCase();
    const result = await dialog.showSaveDialog({
      title: 'حفظ المرفق',
      defaultPath: path.join(app.getPath('downloads'), defaultName),
      filters: extension ? [{ name: extension.toUpperCase(), extensions: [extension] }] : undefined,
    });

    if (result.canceled || !result.filePath) {
      return { success: false, canceled: true };
    }

    fs.copyFileSync(sourcePath, result.filePath);
    return { success: true, filePath: result.filePath };
  } catch (error) {
    return { success: false, error: error.message };
  }
});

