// Copy image to clipboard (base64 PNG data)
ipcMain.handle('copy-image-to-clipboard', async (_e, base64Data) => {
  try {
    const { nativeImage, clipboard } = require('electron');
    // Remove data URL prefix if present
    const base64Clean = base64Data.replace(/^data:image\/png;base64,/, '');
    const buffer = Buffer.from(base64Clean, 'base64');
    const image = nativeImage.createFromBuffer(buffer);
    clipboard.writeImage(image);
    return { success: true };
  } catch (error) {
    return { success: false, error: error.message };
  }
});

// Generate QR code locally and return as data URL
ipcMain.handle('generate-qrcode-data-url', async (_e, payload = {}) => {
  try {
    const text = String(payload?.text || '').trim();
    const width = Math.max(64, Math.min(Number(payload?.width || 160), 1024));
    const margin = Math.max(0, Math.min(Number(payload?.margin ?? 1), 8));

    if (!text) {
      return { success: false, error: 'QR text is empty' };
    }

    const dataUrl = await QRCode.toDataURL(text, {
      errorCorrectionLevel: 'M',
      margin,
      width,
      color: {
        dark: '#0f172a',
        light: '#ffffff'
      }
    });

    return { success: true, dataUrl };
  } catch (error) {
    return { success: false, error: error.message };
  }
});

