ipcMain.handle('receipt-list', async (event, options = {}) => {
  try {
    const mainBranchId = getDefaultMainBranchIdSync();
    const scopeInfo = await resolveBranchScopeForRequest(event, options, mainBranchId);
    const branchIds = getEffectiveBranchIdsForScope(scopeInfo, mainBranchId);
    const branchFilter = buildCoalescedBranchWhereClause('r.branch_id', branchIds, mainBranchId);
    const rows = await tursoSync.queryAll(`
      SELECT r.id, r.branch_local_number, r.date, r.time, r.memo, r.branch_id,
             COALESCE(SUM(rl.amount), 0) AS amount,
             COALESCE(SUM(rl.weight), 0) AS weight
      FROM receipts r
      LEFT JOIN receipt_lines rl ON rl.receipt_id = r.id
      WHERE ${branchFilter.sql}
      GROUP BY r.id, r.branch_local_number, r.date, r.time, r.memo, r.branch_id
      ORDER BY COALESCE(r.branch_local_number, r.id) DESC, r.id DESC
    `, branchFilter.params);
    return { success: true, data: rows };
  } catch (error) {
    return { success: false, error: error.message };
  }
});

ipcMain.handle('receipt-get', async (event, id) => {
  try {
    const requestInfo = parseDocumentRequestPayload(id);
    const mainBranchId = getDefaultMainBranchIdSync();
    const scopeInfo = await resolveBranchScopeForRequest(event, requestInfo.payload, mainBranchId);
    const branchIds = getEffectiveBranchIdsForScope(scopeInfo, mainBranchId);
    const branchFilter = buildCoalescedBranchWhereClause('r.branch_id', branchIds, mainBranchId);
    const receiptId = await resolveBranchScopedDocumentId('receipts', requestInfo, branchIds, { mainBranchId });
    if (!receiptId) {
      return { success: false, error: 'رقم السند غير صالح' };
    }
    const header = await tursoSync.queryOne(`
      SELECT r.id, r.branch_local_number, r.date, r.time, r.memo, r.cash_account_id, r.gold_account_id, r.silver_account_id, r.branch_id,
             r.created_by, r.created_at, r.updated_by, r.updated_at,
             u1.full_name AS created_by_name, u1.username AS created_by_username,
             u2.full_name AS updated_by_name, u2.username AS updated_by_username
      FROM receipts r
      LEFT JOIN users u1 ON r.created_by = u1.id
      LEFT JOIN users u2 ON r.updated_by = u2.id
      WHERE r.id = ? AND ${branchFilter.sql}
    `, [receiptId, ...branchFilter.params]);
    if (!header) {
      return { success: false, error: 'لم يتم العثور على سند القبض' };
    }
    const lines = await tursoSync.queryAll(`
      SELECT id, receipt_id, customer_id, supplier_id, account_id, amount, weight, karat, account_no, note
      FROM receipt_lines
      WHERE receipt_id = ?
      ORDER BY id ASC
    `, [receiptId]);
    return { success: true, data: { header, lines } };
  } catch (error) {
    return { success: false, error: error.message };
  }
});

ipcMain.handle('receipt-add', async (event, payload) => {
  try {
    const p = payload || {};
    const lines = Array.isArray(p.lines) ? p.lines : [];
    if (!lines.length) {
      return { success: false, error: 'لا توجد أسطر للحفظ' };
    }
    const branchId = await resolveBranchIdForRequest(event, p, getDefaultMainBranchIdSync());
    const branchWriteAccess = await ensureAuthenticatedUserCanMutateBranch(event, branchId);
    if (!branchWriteAccess.allowed) {
      return branchWriteAccess.response;
    }
    const branchReferencesCheck = await ensureEntityReferencesBelongToBranch(
      collectTransactionBranchScopedReferences(p, lines),
      branchId
    );
    if (!branchReferencesCheck.allowed) {
      return { success: false, error: branchReferencesCheck.error, branchMismatch: true, details: branchReferencesCheck.details };
    }

    const inactiveCheck = await checkInactiveReferences(collectTransactionBranchScopedReferences(p, lines));
    if (!inactiveCheck.allowed) {
      return {
        success: false,
        error: inactiveCheck.error,
        inactiveEntity: true,
        details: inactiveCheck.details,
      };
    }

    const accountIdsToCheck = [p.cash_account_id, p.gold_account_id, p.silver_account_id];
    for (const line of lines) {
      if (line.account_id) accountIdsToCheck.push(line.account_id);
    }
    const parentCheck = await checkNoParentAccounts(accountIdsToCheck);
    if (!parentCheck.allowed) {
      return { success: false, error: parentCheck.error, isParentAccount: true };
    }

    const date = p.date || (() => {
      const d = new Date();
      return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;
    })();
    const time = p.time || new Date().toTimeString().slice(0, 5);
    const memo = p.note || p.memo || null;
    const cashId = p.cash_account_id || null;
    const goldId = p.gold_account_id || null;
    const silverId = p.silver_account_id || null;
    const createdBy = p.created_by || null;
    const createdAt = getLocalDateTime();
    const requestedBranchLocalNumber = normalizePositiveId(
      p.branch_local_number ?? p.branchLocalNumber ?? p.id,
      null
    );
    const branchLocalNumber = await resolveBranchLocalNumberForInsert('receipts', branchId, requestedBranchLocalNumber);
    const row = await tursoSync.queryOne('SELECT COALESCE(MAX(id), 0) AS maxId FROM receipts');
    const receiptId = Number(row?.maxId || 0) + 1;

    await tursoSync.run(`
      INSERT INTO receipts (id, date, time, memo, cash_account_id, gold_account_id, silver_account_id, created_by, created_at, branch_id, branch_local_number)
      VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
    `, [receiptId, date, time, memo, cashId, goldId, silverId, createdBy, createdAt, branchId, branchLocalNumber]);

    for (const line of lines) {
      await tursoSync.run(`
        INSERT INTO receipt_lines (receipt_id, customer_id, supplier_id, account_id, amount, weight, karat, account_no, note)
        VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)
      `, [
        receiptId,
        line.customer_id ?? null,
        line.supplier_id ?? null,
        line.account_id ?? null,
        Number(line.amount || 0) || 0,
        Number(line.weight || 0) || 0,
        line.karat || null,
        line.account_no || null,
        line.note || null,
      ]);
    }

    try {
      await deleteAutoJournalBySourceAsync('receipt', receiptId);
      const journalLines = [];
      const cashBoxAccountId = cashId || getAccountIdByCode(DEFAULT_ACCOUNTS.CASH_BOX);
      const goldBoxAccountId = goldId || getAccountIdByCode(DEFAULT_ACCOUNTS.GOLD_BOX);
      const silverBoxAccountId = silverId || getAccountIdByCode(DEFAULT_ACCOUNTS.SILVER_BOX) || 999;
      const silverKarats = ['999', '925', '900', '800'];
      const headerMemo = memo || '';

      for (const line of lines) {
        const amount = Number(line.amount || 0);
        const weight = Number(line.weight || 0);
        const lineNote = line.note || line.description || '';
        const lineKarat = line.karat ? String(line.karat) : null;
        const isSilver = lineKarat && silverKarats.includes(lineKarat);

        let entityName = '';
        let entityType = '';
        if (line.customer_id) {
          const customer = await tursoSync.queryOne('SELECT name FROM customers WHERE id = ?', [line.customer_id]);
          entityName = customer ? customer.name : '';
          entityType = 'للعميل';
        } else if (line.supplier_id) {
          const supplier = await tursoSync.queryOne('SELECT name FROM suppliers WHERE id = ?', [line.supplier_id]);
          entityName = supplier ? supplier.name : '';
          entityType = 'للمورد';
        } else if (line.account_id) {
          const account = await tursoSync.queryOne('SELECT name FROM accounts WHERE id = ?', [line.account_id]);
          entityName = account ? account.name : '';
          entityType = 'للحساب';
        }
        const entitySuffix = entityName ? ` ${entityType} ( ${entityName} )` : '';

        if (amount > 0 && cashBoxAccountId) {
          const entityMemo = lineNote || 'قبض نقدي';
          const boxMemo = (headerMemo || 'قبض نقدي') + entitySuffix;
          journalLines.push({ account_id: cashBoxAccountId, debit: amount, credit: 0, currency_type: 'ريال', memo: boxMemo });
          journalLines.push({ customer_id: line.customer_id || null, supplier_id: line.supplier_id || null, account_id: line.account_id || null, debit: 0, credit: amount, currency_type: 'ريال', memo: entityMemo });
        }

        if (weight > 0) {
          const boxAccountId = isSilver ? silverBoxAccountId : goldBoxAccountId;
          const currencyType = isSilver ? 'فضة' : 'ذهب';
          const entityMemo = lineNote || (isSilver ? 'قبض فضة' : 'قبض ذهب');
          const boxMemo = (headerMemo || (isSilver ? 'قبض فضة' : 'قبض ذهب')) + entitySuffix;
          if (boxAccountId) {
            journalLines.push({ account_id: boxAccountId, debit: weight, credit: 0, currency_type: currencyType, karat: lineKarat, memo: boxMemo });
          }
          journalLines.push({ customer_id: line.customer_id || null, supplier_id: line.supplier_id || null, account_id: line.account_id || null, debit: 0, credit: weight, currency_type: currencyType, karat: lineKarat, memo: entityMemo });
        }
      }

      if (journalLines.length > 0) {
        await createAutoJournalEntry('receipt', receiptId, date, `قيد تلقائي - سند قبض رقم ${branchLocalNumber}`, journalLines, createdBy, { branchId });
      }
    } catch (journalError) {
      console.error('Error creating auto journal for receipt:', journalError);
    }

    broadcastCloudDataUpdated({
      source: 'local',
      action: 'insert',
      tables: ['receipts'],
      entityType: 'receipt',
      documentId: Number(receiptId) || 0,
      branchId,
      actorUserId: Number(createdBy) || null,
      actorName: await resolveUserDisplayNameById(createdBy),
      changes: 1,
    });

    void sendWaTransactionNotification('receipt', {
      actionText: 'تمت عملية قبض',
      actorName: await resolveUserDisplayNameById(createdBy),
      documentNo: branchLocalNumber,
      documentId: receiptId,
      ref: lines.find((l) => l?.customer_id || l?.supplier_id || l?.account_id) || {},
      movement: extractMovementSummaryFromReceiptOrVoucherLines(lines),
    });

    return { success: true, id: receiptId, branch_local_number: branchLocalNumber };
  } catch (error) {
    return { success: false, error: error.message };
  }
});

ipcMain.handle('receipt-update', async (event, payload) => {
  try {
    const p = payload || {};
    const receiptId = Number(p.id || 0);
    if (!receiptId) {
      return { success: false, error: 'معرّف السند مفقود' };
    }
    const lines = Array.isArray(p.lines) ? p.lines : [];
    if (!lines.length) {
      return { success: false, error: 'لا توجد أسطر للحفظ' };
    }
    const branchId = await resolveBranchIdForRequest(event, p, getDefaultMainBranchIdSync());
    const branchReferencesCheck = await ensureEntityReferencesBelongToBranch(
      collectTransactionBranchScopedReferences(p, lines),
      branchId
    );
    if (!branchReferencesCheck.allowed) {
      return { success: false, error: branchReferencesCheck.error, branchMismatch: true, details: branchReferencesCheck.details };
    }

    const existingReceipt = await tursoSync.queryOne('SELECT id, branch_id, branch_local_number FROM receipts WHERE id = ?', [receiptId]);
    if (!existingReceipt) {
      return { success: false, error: 'لم يتم العثور على السند' };
    }
    const existingBranchId = normalizePositiveId(existingReceipt?.branch_id, getDefaultMainBranchIdSync()) || getDefaultMainBranchIdSync();
    if (existingBranchId !== branchId) {
      return { success: false, error: 'السند لا يتبع الفرع الحالي' };
    }

    const receiptDisplayNumber = normalizePositiveId(existingReceipt?.branch_local_number, null)
      || normalizePositiveId(p.branch_local_number ?? p.branchLocalNumber, null)
      || receiptId;

    const inactiveCheck = await checkInactiveReferences(collectTransactionBranchScopedReferences(p, lines));
    if (!inactiveCheck.allowed) {
      return {
        success: false,
        error: inactiveCheck.error,
        inactiveEntity: true,
        details: inactiveCheck.details,
      };
    }

    const accountIdsToCheck = [p.cash_account_id, p.gold_account_id, p.silver_account_id];
    for (const line of lines) {
      if (line.account_id) accountIdsToCheck.push(line.account_id);
    }
    const parentCheck = await checkNoParentAccounts(accountIdsToCheck);
    if (!parentCheck.allowed) {
      return { success: false, error: parentCheck.error, isParentAccount: true };
    }

    const date = p.date || (() => {
      const d = new Date();
      return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;
    })();
    const time = p.time || new Date().toTimeString().slice(0, 5);
    const memo = p.note || p.memo || null;
    const cashId = p.cash_account_id || null;
    const goldId = p.gold_account_id || null;
    const silverId = p.silver_account_id || null;
    const updatedBy = p.updated_by || null;
    const updatedAt = getLocalDateTime();
    const broadcastActorUserId = Number(updatedBy) || null;
    const broadcastActorName = await resolveUserDisplayNameById(updatedBy);

    await tursoSync.run(`
      UPDATE receipts
      SET date = ?, time = ?, memo = ?, cash_account_id = ?, gold_account_id = ?, silver_account_id = ?, updated_by = ?, updated_at = ?, branch_id = ?
      WHERE id = ?
    `, [date, time, memo, cashId, goldId, silverId, updatedBy, updatedAt, branchId, receiptId]);

    await tursoSync.run('DELETE FROM receipt_lines WHERE receipt_id = ?', [receiptId]);
    for (const line of lines) {
      await tursoSync.run(`
        INSERT INTO receipt_lines (receipt_id, customer_id, supplier_id, account_id, amount, weight, karat, account_no, note)
        VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)
      `, [
        receiptId,
        line.customer_id ?? null,
        line.supplier_id ?? null,
        line.account_id ?? null,
        Number(line.amount || 0) || 0,
        Number(line.weight || 0) || 0,
        line.karat || null,
        line.account_no || null,
        line.note || null,
      ]);
    }

    try {
      await deleteAutoJournalBySourceAsync('receipt', receiptId);
      const journalLines = [];
      const cashBoxAccountId = cashId || getAccountIdByCode(DEFAULT_ACCOUNTS.CASH_BOX);
      const goldBoxAccountId = goldId || getAccountIdByCode(DEFAULT_ACCOUNTS.GOLD_BOX);
      const silverBoxAccountId = silverId || getAccountIdByCode(DEFAULT_ACCOUNTS.SILVER_BOX) || 999;
      const silverKarats = ['999', '925', '900', '800'];
      const headerMemo = memo || '';

      for (const line of lines) {
        const amount = Number(line.amount || 0);
        const weight = Number(line.weight || 0);
        const lineNote = line.note || line.description || '';
        const lineKarat = line.karat ? String(line.karat) : null;
        const isSilver = lineKarat && silverKarats.includes(lineKarat);

        let entityName = '';
        let entityType = '';
        if (line.customer_id) {
          const customer = await tursoSync.queryOne('SELECT name FROM customers WHERE id = ?', [line.customer_id]);
          entityName = customer ? customer.name : '';
          entityType = 'للعميل';
        } else if (line.supplier_id) {
          const supplier = await tursoSync.queryOne('SELECT name FROM suppliers WHERE id = ?', [line.supplier_id]);
          entityName = supplier ? supplier.name : '';
          entityType = 'للمورد';
        } else if (line.account_id) {
          const account = await tursoSync.queryOne('SELECT name FROM accounts WHERE id = ?', [line.account_id]);
          entityName = account ? account.name : '';
          entityType = 'للحساب';
        }
        const entitySuffix = entityName ? ` ${entityType} ( ${entityName} )` : '';

        if (amount > 0 && cashBoxAccountId) {
          const entityMemo = lineNote || 'قبض نقدي';
          const boxMemo = (headerMemo || 'قبض نقدي') + entitySuffix;
          journalLines.push({ account_id: cashBoxAccountId, debit: amount, credit: 0, currency_type: 'ريال', memo: boxMemo });
          journalLines.push({ customer_id: line.customer_id || null, supplier_id: line.supplier_id || null, account_id: line.account_id || null, debit: 0, credit: amount, currency_type: 'ريال', memo: entityMemo });
        }

        if (weight > 0) {
          const boxAccountId = isSilver ? silverBoxAccountId : goldBoxAccountId;
          const currencyType = isSilver ? 'فضة' : 'ذهب';
          const entityMemo = lineNote || (isSilver ? 'قبض فضة' : 'قبض ذهب');
          const boxMemo = (headerMemo || (isSilver ? 'قبض فضة' : 'قبض ذهب')) + entitySuffix;
          if (boxAccountId) {
            journalLines.push({ account_id: boxAccountId, debit: weight, credit: 0, currency_type: currencyType, karat: lineKarat, memo: boxMemo });
          }
          journalLines.push({ customer_id: line.customer_id || null, supplier_id: line.supplier_id || null, account_id: line.account_id || null, debit: 0, credit: weight, currency_type: currencyType, karat: lineKarat, memo: entityMemo });
        }
      }

      if (journalLines.length > 0) {
        await createAutoJournalEntry('receipt', receiptId, date, `قيد تلقائي - سند قبض رقم ${receiptDisplayNumber}`, journalLines, updatedBy, { branchId });
      }
    } catch (journalError) {
      console.error('Error updating auto journal for receipt:', journalError);
    }

    broadcastCloudDataUpdated({
      source: 'local',
      action: 'update',
      tables: ['receipts'],
      entityType: 'receipt',
      documentId: Number(receiptId) || 0,
      branchId,
      actorUserId: broadcastActorUserId,
      actorName: broadcastActorName,
      changes: 1,
    });

    void sendWaTransactionNotification('receipt', {
      actionText: 'تم تعديل عملية قبض',
      actorName: broadcastActorName,
      documentNo: receiptDisplayNumber,
      documentId: receiptId,
      ref: lines.find((l) => l?.customer_id || l?.supplier_id || l?.account_id) || {},
      movement: extractMovementSummaryFromReceiptOrVoucherLines(lines),
    });

    return { success: true, id: receiptId, branch_local_number: receiptDisplayNumber };
  } catch (error) {
    return { success: false, error: error.message };
  }
});

ipcMain.handle('receipt-remove', async (event, id) => {
  try {
    const { id: receiptId, payload: requestPayload } = parseDocumentRequestPayload(id);
    const branchId = await resolveBranchIdForRequest(event, requestPayload, getDefaultMainBranchIdSync());
    const branchWriteAccess = await ensureAuthenticatedUserCanMutateBranch(event, branchId);
    if (!branchWriteAccess.allowed) {
      return branchWriteAccess.response;
    }
    if (!receiptId) {
      return { success: false, error: 'رقم السند غير صالح' };
    }

    const receiptRow = await tursoSync.queryOne('SELECT created_by, updated_by, branch_id, branch_local_number FROM receipts WHERE id = ?', [receiptId]);
    if (!receiptRow) {
      return { success: false, error: 'لم يتم العثور على سند القبض' };
    }
    const receiptBranchId = normalizePositiveId(receiptRow?.branch_id, getDefaultMainBranchIdSync()) || getDefaultMainBranchIdSync();
    if (receiptBranchId !== branchId) {
      return { success: false, error: 'السند لا يتبع الفرع الحالي' };
    }
    const { actorUserId, actorName } = await resolveBroadcastActor(
      event,
      requestPayload,
      receiptRow?.updated_by || receiptRow?.created_by
    );

    const displayDocumentId = Number(receiptRow?.branch_local_number) || Number(receiptId) || 0;

    await deleteAutoJournalBySourceAsync('receipt', receiptId);
    const delLines = await tursoSync.run('DELETE FROM receipt_lines WHERE receipt_id = ?', [receiptId]);
    const info = await tursoSync.run('DELETE FROM receipts WHERE id = ?', [receiptId]);
    if (!Number(info?.changes || 0)) {
      return { success: false, error: 'لم يتم العثور على سند القبض' };
    }

    broadcastCloudDataUpdated({
      source: 'local',
      action: 'delete',
      tables: ['receipts'],
      entityType: 'receipt',
      documentId: Number(receiptId) || 0,
      displayDocumentId,
      branchId,
      actorUserId,
      actorName,
      changes: Number(info?.changes) || 1,
    });

    return { success: true, removed_header: Number(info?.changes) || 0, removed_lines: Number(delLines?.changes) || 0 };
  } catch (error) {
    return { success: false, error: error.message };
  }
});

