ipcMain.handle('opening-list', async (_e, _options = {}) => {
  try {
    const mainBranchId = getDefaultMainBranchIdSync();
    const scopeInfo = await resolveBranchScopeForRequest(_e, _options, mainBranchId);
    const branchIds = getEffectiveBranchIdsForScope(scopeInfo, mainBranchId);
    const branchFilter = buildCoalescedBranchWhereClause('branch_id', branchIds, mainBranchId);
    const rows = await tursoSync.queryAll(`
      SELECT id, branch_local_number, date, memo, branch_id
      FROM openings
      WHERE ${branchFilter.sql}
      ORDER BY COALESCE(branch_local_number, id) DESC, id DESC
    `, branchFilter.params);
    return { success: true, data: rows };
  } catch (error) {
    return { success: false, error: error.message };
  }
});

ipcMain.handle('opening-get', async (event, id) => {
  try {
    const requestInfo = parseDocumentRequestPayload(id);
    const mainBranchId = getDefaultMainBranchIdSync();
    const scopeInfo = await resolveBranchScopeForRequest(event, requestInfo.payload, mainBranchId);
    const branchIds = getEffectiveBranchIdsForScope(scopeInfo, mainBranchId);
    const branchFilter = buildCoalescedBranchWhereClause('o.branch_id', branchIds, mainBranchId);
    const openingId = await resolveBranchScopedDocumentId('openings', requestInfo, branchIds, { mainBranchId });
    if (!openingId) {
      return { success: false, error: 'رقم الرصيد الافتتاحي غير صالح' };
    }
    const header = await tursoSync.queryOne(`
      SELECT o.id, o.branch_local_number, o.date, '' AS time, o.memo, o.branch_id,
             o.created_by, o.created_at, o.updated_by, o.updated_at,
             u1.full_name AS created_by_name, u1.username AS created_by_username,
             u2.full_name AS updated_by_name, u2.username AS updated_by_username
      FROM openings o
      LEFT JOIN users u1 ON o.created_by = u1.id
      LEFT JOIN users u2 ON o.updated_by = u2.id
      WHERE o.id = ? AND ${branchFilter.sql}
    `, [openingId, ...branchFilter.params]);
    if (!header) {
      return { success: false, error: 'لم يتم العثور على الرصيد الافتتاحي' };
    }
    const lines = await tursoSync.queryAll(`
      SELECT id, opening_id, account_id, customer_id, supplier_id, amount, weight, karat, note
      FROM opening_lines
      WHERE opening_id = ?
      ORDER BY id ASC
    `, [openingId]);
    return { success: true, data: { header, lines } };
  } catch (error) {
    return { success: false, error: error.message };
  }
});

ipcMain.handle('opening-add', async (event, payload) => {
  try {
    const p = payload || {};
    const lines = Array.isArray(p.lines) ? p.lines : [];
    if (!lines.length) {
      return { success: false, error: 'لا توجد أسطر للحفظ' };
    }
    const branchId = await resolveBranchIdForRequest(event, p, getDefaultMainBranchIdSync());
    const branchWriteAccess = await ensureAuthenticatedUserCanMutateBranch(event, branchId);
    if (!branchWriteAccess.allowed) {
      return branchWriteAccess.response;
    }
    const branchReferencesCheck = await ensureEntityReferencesBelongToBranch(
      collectTransactionBranchScopedReferences({}, lines),
      branchId
    );
    if (!branchReferencesCheck.allowed) {
      return { success: false, error: branchReferencesCheck.error, branchMismatch: true, details: branchReferencesCheck.details };
    }

    const inactiveCheck = await checkInactiveReferences(collectTransactionBranchScopedReferences({}, lines));
    if (!inactiveCheck.allowed) {
      return {
        success: false,
        error: inactiveCheck.error,
        inactiveEntity: true,
        details: inactiveCheck.details,
      };
    }

    const openingDebtLimitCheck = await findDebtLimitFailureForAmounts(
      collectDebtLimitAmountsFromOpeningLines(lines),
      { branchId }
    );
    if (!openingDebtLimitCheck.allowed) {
      return {
        success: false,
        error: openingDebtLimitCheck.error,
        debtLimitExceeded: true,
        details: openingDebtLimitCheck.details,
      };
    }

    const parentCheck = await checkNoParentAccounts(lines.map((line) => line.account_id).filter((value) => value));
    if (!parentCheck.allowed) {
      return { success: false, error: parentCheck.error, isParentAccount: true };
    }

    const date = p.date || (() => {
      const d = new Date();
      return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;
    })();
    const memo = p.memo || p.note || null;
    const createdBy = p.created_by || null;
    const createdAt = getLocalDateTime();
    const requestedBranchLocalNumber = normalizePositiveId(
      p.branch_local_number ?? p.branchLocalNumber ?? p.id,
      null
    );
    const branchLocalNumber = await resolveBranchLocalNumberForInsert('openings', branchId, requestedBranchLocalNumber);
    const row = await tursoSync.queryOne('SELECT COALESCE(MAX(id), 0) AS maxId FROM openings');
    const openingId = Number(row?.maxId || 0) + 1;

    await tursoSync.run(`
      INSERT INTO openings (id, date, memo, created_by, created_at, branch_id, branch_local_number)
      VALUES (?, ?, ?, ?, ?, ?, ?)
    `, [openingId, date, memo, createdBy, createdAt, branchId, branchLocalNumber]);

    for (const line of lines) {
      await tursoSync.run(`
        INSERT INTO opening_lines (opening_id, account_id, customer_id, supplier_id, amount, weight, karat, note)
        VALUES (?, ?, ?, ?, ?, ?, ?, ?)
      `, [
        openingId,
        line.account_id ?? null,
        line.customer_id ?? null,
        line.supplier_id ?? null,
        Number(line.amount || 0) || 0,
        Number(line.weight || 0) || 0,
        line.karat || null,
        line.note || null,
      ]);
    }

    try {
      await deleteOpeningJournalEntryAsync(openingId);
      const openingJournalResult = await createOpeningJournalEntry(openingId, date, memo || `رصيد افتتاحي رقم ${branchLocalNumber}`, lines, createdBy, { branchId });
      if (!openingJournalResult?.success) {
        clearOpeningJournalIntegrityRepairCache();
        await ensureOpeningJournalEntriesIntegrity([branchId]);
        const repairedOpeningJournal = await tursoSync.queryOne("SELECT id FROM journal_entries WHERE source_type = 'opening' AND source_id = ? LIMIT 1", [openingId]);
        if (!repairedOpeningJournal) {
          await deleteOpeningJournalEntryAsync(openingId);
          await tursoSync.run('DELETE FROM opening_lines WHERE opening_id = ?', [openingId]);
          await tursoSync.run('DELETE FROM openings WHERE id = ?', [openingId]);
          return { success: false, error: openingJournalResult.error || 'تعذر إنشاء قيد الرصيد الافتتاحي' };
        }
      }
    } catch (journalError) {
      console.error('Error creating opening journal entry:', journalError);
      await deleteOpeningJournalEntryAsync(openingId);
      await tursoSync.run('DELETE FROM opening_lines WHERE opening_id = ?', [openingId]);
      await tursoSync.run('DELETE FROM openings WHERE id = ?', [openingId]);
      return { success: false, error: journalError?.message || 'تعذر إنشاء قيد الرصيد الافتتاحي' };
    }

    clearOpeningJournalIntegrityRepairCache();

    broadcastCloudDataUpdated({
      source: 'local',
      action: 'insert',
      tables: ['openings'],
      entityType: 'opening',
      documentId: Number(openingId) || 0,
      branchId,
      actorUserId: Number(createdBy) || null,
      actorName: await resolveUserDisplayNameById(createdBy),
      changes: 1,
    });

    return { success: true, id: openingId, branch_local_number: branchLocalNumber };
  } catch (error) {
    return { success: false, error: error.message };
  }
});

ipcMain.handle('opening-update', async (event, payload) => {
  try {
    const p = payload || {};
    const openingId = Number(p.id || 0);
    if (!openingId) {
      return { success: false, error: 'معرّف الرصيد الافتتاحي مفقود' };
    }
    const lines = Array.isArray(p.lines) ? p.lines : [];
    if (!lines.length) {
      return { success: false, error: 'لا توجد أسطر للحفظ' };
    }
    const branchId = await resolveBranchIdForRequest(event, p, getDefaultMainBranchIdSync());
    const branchWriteAccess = await ensureAuthenticatedUserCanMutateBranch(event, branchId);
    if (!branchWriteAccess.allowed) {
      return branchWriteAccess.response;
    }
    const branchReferencesCheck = await ensureEntityReferencesBelongToBranch(
      collectTransactionBranchScopedReferences({}, lines),
      branchId
    );
    if (!branchReferencesCheck.allowed) {
      return { success: false, error: branchReferencesCheck.error, branchMismatch: true, details: branchReferencesCheck.details };
    }
    const existingOpening = await tursoSync.queryOne('SELECT id, branch_id, branch_local_number FROM openings WHERE id = ?', [openingId]);
    if (existingOpening) {
      const existingBranchId = normalizePositiveId(existingOpening?.branch_id, getDefaultMainBranchIdSync()) || getDefaultMainBranchIdSync();
      if (existingBranchId !== branchId) {
        return { success: false, error: 'الرصيد الافتتاحي لا يتبع الفرع الحالي' };
      }
    }
    const openingDisplayNumber = normalizePositiveId(existingOpening?.branch_local_number, null)
      || normalizePositiveId(p.branch_local_number ?? p.branchLocalNumber, null)
      || openingId;

    const inactiveCheck = await checkInactiveReferences(collectTransactionBranchScopedReferences({}, lines));
    if (!inactiveCheck.allowed) {
      return {
        success: false,
        error: inactiveCheck.error,
        inactiveEntity: true,
        details: inactiveCheck.details,
      };
    }

    const parentCheck = await checkNoParentAccounts(lines.map((line) => line.account_id).filter((value) => value));
    if (!parentCheck.allowed) {
      return { success: false, error: parentCheck.error, isParentAccount: true };
    }

    const date = p.date || (() => {
      const d = new Date();
      return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;
    })();
    const memo = p.memo || p.note || null;
    const updatedBy = p.updated_by || null;
    const updatedAt = getLocalDateTime();
    if (!existingOpening) {
      return { success: false, error: 'لم يتم العثور على الرصيد الافتتاحي' };
    }

    const existingOpeningLines = await tursoSync.queryAll(
      'SELECT account_id, customer_id, supplier_id, amount FROM opening_lines WHERE opening_id = ?',
      [openingId]
    );
    const openingDebtLimitCheck = await findDebtLimitFailureForNetAmounts(
      collectDebtLimitAmountsFromOpeningLines(existingOpeningLines),
      collectDebtLimitAmountsFromOpeningLines(lines),
      { branchId }
    );
    if (!openingDebtLimitCheck.allowed) {
      return {
        success: false,
        error: openingDebtLimitCheck.error,
        debtLimitExceeded: true,
        details: openingDebtLimitCheck.details,
      };
    }

    const broadcastActorUserId = Number(updatedBy) || null;
    const broadcastActorName = await resolveUserDisplayNameById(updatedBy);

    await tursoSync.run(`
      UPDATE openings
      SET date = ?, memo = ?, updated_by = ?, updated_at = ?, branch_id = ?
      WHERE id = ?
    `, [date, memo, updatedBy, updatedAt, branchId, openingId]);

    await tursoSync.run('DELETE FROM opening_lines WHERE opening_id = ?', [openingId]);
    for (const line of lines) {
      await tursoSync.run(`
        INSERT INTO opening_lines (opening_id, account_id, customer_id, supplier_id, amount, weight, karat, note)
        VALUES (?, ?, ?, ?, ?, ?, ?, ?)
      `, [
        openingId,
        line.account_id ?? null,
        line.customer_id ?? null,
        line.supplier_id ?? null,
        Number(line.amount || 0) || 0,
        Number(line.weight || 0) || 0,
        line.karat || null,
        line.note || null,
      ]);
    }

    try {
      await deleteOpeningJournalEntryAsync(openingId);
      const openingJournalResult = await createOpeningJournalEntry(openingId, date, memo || `رصيد افتتاحي رقم ${openingDisplayNumber}`, lines, updatedBy, { branchId });
      if (!openingJournalResult?.success) {
        clearOpeningJournalIntegrityRepairCache();
        await ensureOpeningJournalEntriesIntegrity([branchId]);
        const repairedOpeningJournal = await tursoSync.queryOne("SELECT id FROM journal_entries WHERE source_type = 'opening' AND source_id = ? LIMIT 1", [openingId]);
        if (!repairedOpeningJournal) {
          return { success: false, error: openingJournalResult.error || 'تعذر تحديث قيد الرصيد الافتتاحي' };
        }
      }
    } catch (journalError) {
      console.error('Error updating opening journal entry:', journalError);
      return { success: false, error: journalError?.message || 'تعذر تحديث قيد الرصيد الافتتاحي' };
    }

    clearOpeningJournalIntegrityRepairCache();

    broadcastCloudDataUpdated({
      source: 'local',
      action: 'update',
      tables: ['openings'],
      entityType: 'opening',
      documentId: Number(openingId) || 0,
      branchId,
      actorUserId: broadcastActorUserId,
      actorName: broadcastActorName,
      changes: 1,
    });

    return { success: true, id: openingId, branch_local_number: openingDisplayNumber };
  } catch (error) {
    return { success: false, error: error.message };
  }
});

