ipcMain.handle('voucher-update', async (event, payload) => {
  try{
    const p = payload || {}; const id = Number(p.id);
    if (!id) return { success:false, error:'معرّف السند مفقود' };
    const date = p.date || new Date().toISOString().split('T')[0];
    const memo = p.note || null;
    const cashId = p.cash_account_id || null;
    const goldId = p.gold_account_id || null;
    const silverId = p.silver_account_id || null;
    const lines = Array.isArray(p.lines) ? p.lines : [];
    const branchId = await resolveBranchIdForRequest(event, p, getDefaultMainBranchIdSync());
    const branchWriteAccess = await ensureAuthenticatedUserCanMutateBranch(event, branchId);
    if (!branchWriteAccess.allowed) {
      return branchWriteAccess.response;
    }
    const branchReferencesCheck = await ensureEntityReferencesBelongToBranch(
      collectTransactionBranchScopedReferences(p, lines),
      branchId
    );
    if (!branchReferencesCheck.allowed) {
      return { success:false, error: branchReferencesCheck.error, branchMismatch: true, details: branchReferencesCheck.details };
    }
    const updatedBy = p.updated_by || null;
    const updatedAt = getLocalDateTime();
    const existingVoucher = await tursoSync.queryOne('SELECT id, branch_id, branch_local_number FROM vouchers WHERE id = ?', [id]);
    if (existingVoucher) {
      const existingBranchId = normalizePositiveId(existingVoucher?.branch_id, getDefaultMainBranchIdSync()) || getDefaultMainBranchIdSync();
      if (existingBranchId !== branchId) {
        return { success:false, error:'السند لا يتبع الفرع الحالي' };
      }
    }
    const voucherDisplayNumber = normalizePositiveId(existingVoucher?.branch_local_number, null)
      || normalizePositiveId(p.branch_local_number ?? p.branchLocalNumber, null)
      || id;
    
    // فحص سقف المديونية - جمع المبالغ لنفس العميل/المورد/الحساب
    const oldLines = existingVoucher
      ? await tursoSync.queryAll('SELECT customer_id, supplier_id, account_id, amount FROM voucher_lines WHERE voucher_id = ?', [id])
      : [];
    
    // جمع المبالغ القديمة حسب العميل/المورد/الحساب
    const oldAmountsByEntity = new Map();
    for (const oldLine of oldLines) {
      const key = `c${oldLine.customer_id || 0}_s${oldLine.supplier_id || 0}_a${oldLine.account_id || 0}`;
      oldAmountsByEntity.set(key, (oldAmountsByEntity.get(key) || 0) + Number(oldLine.amount || 0));
    }
    
    // جمع المبالغ الجديدة حسب العميل/المورد/الحساب
    const newAmountsByEntity = new Map();
    for (const line of lines) {
      const amount = Number(line.amount || 0);
      if (amount > 0) {
        const key = `c${line.customer_id || 0}_s${line.supplier_id || 0}_a${line.account_id || 0}`;
        
        if (!newAmountsByEntity.has(key)) {
          newAmountsByEntity.set(key, {
            customer_id: line.customer_id || null,
            supplier_id: line.supplier_id || null,
            account_id: line.account_id || null,
            totalAmount: 0
          });
        }
        
        newAmountsByEntity.get(key).totalAmount += amount;
      }
    }
    
    // فحص كل عميل/مورد/حساب: الفرق = المبلغ الجديد - المبلغ القديم
    for (const [key, entity] of newAmountsByEntity) {
      const oldAmount = oldAmountsByEntity.get(key) || 0;
      const netChange = entity.totalAmount - oldAmount;
      
      if (netChange !== 0) {
        const check = await checkDebtLimit({
          customer_id: entity.customer_id,
          supplier_id: entity.supplier_id,
          account_id: entity.account_id,
          debit_amount: netChange > 0 ? netChange : 0,
          credit_amount: netChange < 0 ? Math.abs(netChange) : 0,
          branch_id: branchId
        });
        
        if (!check.allowed) {
          return {
            success: false,
            error: check.error,
            debtLimitExceeded: true,
            details: check.details
          };
        }
      }
    }

    const inactiveCheck = await checkInactiveReferences(collectTransactionBranchScopedReferences(p, lines));
    if (!inactiveCheck.allowed) {
      return {
        success: false,
        error: inactiveCheck.error,
        inactiveEntity: true,
        details: inactiveCheck.details
      };
    }
    
    // التحقق من عدم التسجيل على حسابات رئيسية
    const accountIdsToCheck = [cashId, goldId, silverId];
    for (const line of lines) {
      if (line.account_id) accountIdsToCheck.push(line.account_id);
    }
    const parentCheck = await checkNoParentAccounts(accountIdsToCheck);
    if (!parentCheck.allowed) {
      return { success: false, error: parentCheck.error, isParentAccount: true };
    }
    
    const existsInCloud = await tursoSync.queryOne('SELECT 1 FROM vouchers WHERE id = ?', [id]);
    if (!existsInCloud) {
      return { success:false, error:'لم يتم العثور على السند' };
    }
    const time = new Date().toLocaleTimeString('en-GB');
    const broadcastActorUserId = Number(updatedBy) || null;
    const broadcastActorName = await resolveUserDisplayNameById(updatedBy);
    await tursoSync.run(`UPDATE vouchers SET date=?, memo=?, cash_account_id=?, gold_account_id=?, silver_account_id=?, updated_by=?, updated_at=?, branch_id=? WHERE id=?`,
      [date, memo, cashId, goldId, silverId, updatedBy, updatedAt, branchId, id]);
    await tursoSync.run(`DELETE FROM voucher_lines WHERE voucher_id=?`, [id]);
    if (lines.length){
      for (const L of lines){
        await tursoSync.run(`INSERT INTO voucher_lines (voucher_id, customer_id, supplier_id, account_id, amount, weight, karat, account_no, note)
                              VALUES (?,?,?,?,?,?,?,?,?)`,
          [id, L.customer_id ?? null, L.supplier_id ?? null, L.account_id ?? null,
                Number(L.amount||0)||0, Number(L.weight||0)||0, L.karat || null, L.account_no || null, L.note || null]);
      }
    }
    
    // Update auto journal entry for voucher
    try {
      await deleteAutoJournalBySourceAsync('voucher', id);
      
      const journalLines = [];
      // استخدام الصناديق المحددة في رأس السند أو الافتراضية
      const cashBoxAccountId = cashId || getAccountIdByCode(DEFAULT_ACCOUNTS.CASH_BOX);
      const goldBoxAccountId = goldId || getAccountIdByCode(DEFAULT_ACCOUNTS.GOLD_BOX);
      const silverId = p.silver_account_id || 999;
      const silverKarats = ['999', '925', '900', '800'];
      const headerMemo = memo || ''; // بيان رأس السند للصندوق
      
      for (const L of lines) {
        const amount = Number(L.amount || 0);
        const weight = Number(L.weight || 0);
        const lineNote = L.note || L.description || ''; // بيان السطر للعميل
        // استخدام العيار الفعلي من السطر - لا نستخدم قيمة افتراضية
        const lineKarat = L.karat ? String(L.karat) : null;
        const isSilver = lineKarat && silverKarats.includes(lineKarat);
        
        // جلب اسم العميل/المورد/الحساب لبيان الصندوق
        let entityName = '';
        let entityType = '';
        if (L.customer_id) {
          const cust = await tursoSync.queryOne('SELECT name FROM customers WHERE id = ?', [L.customer_id]);
          entityName = cust ? cust.name : '';
          entityType = 'للعميل';
        } else if (L.supplier_id) {
          const supp = await tursoSync.queryOne('SELECT name FROM suppliers WHERE id = ?', [L.supplier_id]);
          entityName = supp ? supp.name : '';
          entityType = 'للمورد';
        } else if (L.account_id) {
          const acct = await tursoSync.queryOne('SELECT name FROM accounts WHERE id = ?', [L.account_id]);
          entityName = acct ? acct.name : '';
          entityType = 'للحساب';
        }
        const entitySuffix = entityName ? ` ${entityType} ( ${entityName} )` : '';
        
        if (amount > 0) {
          const customerMemo = lineNote || 'صرف نقدي'; // بيان العميل من السطر
          const boxMemo = (headerMemo || 'صرف نقدي') + entitySuffix; // بيان الصندوق مع اسم الطرف
          journalLines.push({ customer_id: L.customer_id || null, supplier_id: L.supplier_id || null, account_id: L.account_id || null, debit: amount, credit: 0, currency_type: 'ريال', memo: customerMemo });
          journalLines.push({ account_id: cashBoxAccountId, debit: 0, credit: amount, currency_type: 'ريال', memo: boxMemo });
        }
        
        if (weight > 0) {
          const boxAccountId = isSilver ? silverId : goldBoxAccountId;
          const currencyType = isSilver ? 'فضة' : 'ذهب';
          const customerMemo = lineNote || (isSilver ? 'صرف فضة' : 'صرف ذهب'); // بيان العميل من السطر
          const boxMemo = (headerMemo || (isSilver ? 'صرف فضة' : 'صرف ذهب')) + entitySuffix; // بيان الصندوق مع اسم الطرف
          journalLines.push({ customer_id: L.customer_id || null, supplier_id: L.supplier_id || null, account_id: L.account_id || null, debit: weight, credit: 0, currency_type: currencyType, karat: lineKarat, memo: customerMemo });
          journalLines.push({ account_id: boxAccountId, debit: 0, credit: weight, currency_type: currencyType, karat: lineKarat, memo: boxMemo });
        }
      }
      
      if (journalLines.length > 0) {
        await createAutoJournalEntry('voucher', id, date, `قيد تلقائي - سند صرف رقم ${voucherDisplayNumber}`, journalLines, updatedBy, { branchId });
      }
    } catch (journalError) {
      console.error('Error updating auto journal for voucher:', journalError);
    }
    
    broadcastCloudDataUpdated({
      source: 'local',
      action: 'update',
      tables: ['vouchers'],
      entityType: 'voucher',
      documentId: Number(id) || 0,
      branchId,
      actorUserId: broadcastActorUserId,
      actorName: broadcastActorName,
      changes: 1,
    });

    void sendWaTransactionNotification('voucher', {
      actionText: 'تم تعديل عملية صرف',
      actorName: broadcastActorName,
      documentNo: voucherDisplayNumber,
      documentId: id,
      ref: lines.find((l) => l?.customer_id || l?.supplier_id || l?.account_id) || {},
      movement: extractMovementSummaryFromReceiptOrVoucherLines(lines),
    });
    return { success:true, id, branch_local_number: voucherDisplayNumber };
  }catch(error){ return { success:false, error: error.message }; }
});

ipcMain.handle('voucher-list', async (event, options = {}) => {
  try{
    const mainBranchId = getDefaultMainBranchIdSync();
    const scopeInfo = await resolveBranchScopeForRequest(event, options, mainBranchId);
    const branchIds = getEffectiveBranchIdsForScope(scopeInfo, mainBranchId);
    const branchFilter = buildCoalescedBranchWhereClause('v.branch_id', branchIds, mainBranchId);
    const rows = await tursoSync.queryAll(`
      SELECT v.id, v.branch_local_number, v.date, v.time, v.memo, v.branch_id,
             COALESCE(a.name, (SELECT account_no FROM voucher_lines WHERE voucher_id=v.id LIMIT 1)) AS account,
             COALESCE((SELECT SUM(amount) FROM voucher_lines WHERE voucher_id=v.id), 0) AS amount
      FROM vouchers v
      LEFT JOIN accounts a ON a.id = v.cash_account_id
      WHERE ${branchFilter.sql}
      ORDER BY COALESCE(v.branch_local_number, v.id) DESC, v.id DESC`, branchFilter.params);
    return { success:true, data: rows };
  }catch(error){ return { success:false, error: error.message }; }
});

ipcMain.handle('voucher-get', async (event, id) => {
  try{
    const requestInfo = parseDocumentRequestPayload(id);
    const mainBranchId = getDefaultMainBranchIdSync();
    const scopeInfo = await resolveBranchScopeForRequest(event, requestInfo.payload, mainBranchId);
    const branchIds = getEffectiveBranchIdsForScope(scopeInfo, mainBranchId);
    const branchFilter = buildCoalescedBranchWhereClause('v.branch_id', branchIds, mainBranchId);
    const voucherId = await resolveBranchScopedDocumentId('vouchers', requestInfo, branchIds, { mainBranchId });
    if (!voucherId) return { success:false, error:'رقم السند غير صالح' };
    const hdr = await tursoSync.queryOne(`
      SELECT v.id, v.branch_local_number, v.date, v.time, v.memo, v.cash_account_id, v.gold_account_id, v.silver_account_id, v.branch_id,
             v.created_by, v.created_at, v.updated_by, v.updated_at,
             u1.full_name AS created_by_name, u1.username AS created_by_username,
             u2.full_name AS updated_by_name, u2.username AS updated_by_username
      FROM vouchers v
      LEFT JOIN users u1 ON v.created_by = u1.id
      LEFT JOIN users u2 ON v.updated_by = u2.id
      WHERE v.id = ? AND ${branchFilter.sql}`, [voucherId, ...branchFilter.params]);
    if (!hdr) return { success:false, error:'لم يتم العثور على السند' };
    const lines = await tursoSync.queryAll(`SELECT id, voucher_id, customer_id, supplier_id, account_id, amount, weight, karat, account_no, note FROM voucher_lines WHERE voucher_id=? ORDER BY id ASC`, [voucherId]);
    return { success:true, data: { header: hdr, lines } };
  }catch(error){ return { success:false, error: error.message }; }
});

// Remove voucher (header + lines via ON DELETE CASCADE)
ipcMain.handle('voucher-remove', async (event, id) => {
  try{
    const { id: vid, payload: requestPayload } = parseDocumentRequestPayload(id);
    const branchId = await resolveBranchIdForRequest(event, requestPayload, getDefaultMainBranchIdSync());
    const branchWriteAccess = await ensureAuthenticatedUserCanMutateBranch(event, branchId);
    if (!branchWriteAccess.allowed) {
      return branchWriteAccess.response;
    }
    if (!vid) return { success:false, error:'رقم السند غير صالح' };

    const voucherRow = await tursoSync.queryOne('SELECT created_by, updated_by, branch_id, branch_local_number FROM vouchers WHERE id = ?', [vid]);
    if (!voucherRow) return { success:false, error:'لم يتم العثور على السند' };
    const voucherBranchId = normalizePositiveId(voucherRow?.branch_id, getDefaultMainBranchIdSync()) || getDefaultMainBranchIdSync();
    if (voucherBranchId !== branchId) return { success:false, error:'السند لا يتبع الفرع الحالي' };
    const { actorUserId, actorName } = await resolveBroadcastActor(
      event,
      requestPayload,
      voucherRow?.updated_by || voucherRow?.created_by
    );
    
    // Delete auto journal first
    await deleteAutoJournalBySourceAsync('voucher', vid);
    
    // Delete details first, then header
    const delLines = await tursoSync.run('DELETE FROM voucher_lines WHERE voucher_id = ?', [vid]);
    const info = await tursoSync.run('DELETE FROM vouchers WHERE id = ?', [vid]);
    
    if (info.changes > 0) {
      broadcastCloudDataUpdated({
        source: 'local',
        action: 'delete',
        tables: ['vouchers'],
        entityType: 'voucher',
        documentId: Number(vid) || 0,
        displayDocumentId: Number(voucherRow?.branch_local_number) || Number(vid) || 0,
        branchId,
        actorUserId,
        actorName,
        changes: Number(info.changes) || 1,
      });
      return { success:true, removed_header: info.changes, removed_lines: delLines.changes };
    }
    return { success:false, error:'لم يتم العثور على السند' };
  }catch(error){ return { success:false, error: error.message }; }
});

ipcMain.handle('voucher-add', async (event, payload) => {
  const p = payload || {};
  const date = p.date || new Date().toISOString().split('T')[0];
  const time = new Date().toLocaleTimeString('en-GB');
  const memo = p.note || null;
  const cashId = p.cash_account_id || null;
  const goldId = p.gold_account_id || null;
  const silverId = p.silver_account_id || null;
  const lines = Array.isArray(p.lines) ? p.lines : [];
  const fallbackAmount = Number(p.amount || 0) || 0;
  const fallbackAccNo = p.account || null;
  const createdBy = p.created_by || null; // User ID from frontend
  const createdAt = getLocalDateTime();
  const branchId = await resolveBranchIdForRequest(event, p, getDefaultMainBranchIdSync());
  const branchWriteAccess = await ensureAuthenticatedUserCanMutateBranch(event, branchId);
  if (!branchWriteAccess.allowed) {
    return branchWriteAccess.response;
  }

  // فحص سقف المديونية - جمع المبالغ لنفس العميل/المورد/الحساب أولاً
  const linesToCheck = lines.length ? lines : [{ amount: fallbackAmount, account_no: fallbackAccNo }];
  const branchReferencesCheck = await ensureEntityReferencesBelongToBranch(
    collectTransactionBranchScopedReferences(p, linesToCheck),
    branchId
  );
  if (!branchReferencesCheck.allowed) {
    return {
      success: false,
      error: branchReferencesCheck.error,
      branchMismatch: true,
      details: branchReferencesCheck.details
    };
  }
  
  // جمع المبالغ حسب العميل/المورد/الحساب
  const amountsByEntity = new Map();
  
  for (const line of linesToCheck) {
    const amount = Number(line.amount || 0);
    if (amount > 0) {
      const key = `c${line.customer_id || 0}_s${line.supplier_id || 0}_a${line.account_id || 0}`;
      
      if (!amountsByEntity.has(key)) {
        amountsByEntity.set(key, {
          customer_id: line.customer_id || null,
          supplier_id: line.supplier_id || null,
          account_id: line.account_id || null,
          totalAmount: 0
        });
      }
      
      amountsByEntity.get(key).totalAmount += amount;
    }
  }
  
  // الآن فحص المجموع لكل عميل/مورد/حساب
  for (const [key, entity] of amountsByEntity) {
    const check = await checkDebtLimit({
      customer_id: entity.customer_id,
      supplier_id: entity.supplier_id,
      account_id: entity.account_id,
      debit_amount: entity.totalAmount,
      credit_amount: 0,
      branch_id: branchId
    });
    
    if (!check.allowed) {
      return {
        success: false,
        error: check.error,
        debtLimitExceeded: true,
        details: check.details
      };
    }
  }
  
  // فحص العملاء/الموردين/الحسابات غير النشطين
  const inactiveCheck = await checkInactiveReferences(collectTransactionBranchScopedReferences(p, linesToCheck));
  if (!inactiveCheck.allowed) {
    return {
      success: false,
      error: inactiveCheck.error,
      inactiveEntity: true,
      details: inactiveCheck.details
    };
  }
  
  // التحقق من عدم التسجيل على حسابات رئيسية
  const accountIdsToCheck = [cashId, goldId, silverId];
  for (const line of linesToCheck) {
    if (line.account_id) accountIdsToCheck.push(line.account_id);
  }
  const parentCheck = await checkNoParentAccounts(accountIdsToCheck);
  if (!parentCheck.allowed) {
    return { success: false, error: parentCheck.error, isParentAccount: true };
  }
  
  try{ 
    const requestedBranchLocalNumber = normalizePositiveId(
      p.branch_local_number ?? p.branchLocalNumber ?? p.id ?? p.voucher_id,
      null
    );
    const branchLocalNumber = await resolveBranchLocalNumberForInsert('vouchers', branchId, requestedBranchLocalNumber);
    const row = await tursoSync.queryOne('SELECT COALESCE(MAX(id),0) AS maxId FROM vouchers');
    const vid = row && row.maxId ? Number(row.maxId) + 1 : 1;
    
    console.log('[voucher-add] Inserting voucher header:', { vid, branchLocalNumber, date, time, memo, cashId, goldId, silverId, createdBy, createdAt });
    const insertResult = await tursoSync.run(`INSERT INTO vouchers (id,date,time,memo,cash_account_id,gold_account_id,silver_account_id,created_by,created_at,branch_id,branch_local_number) VALUES (?,?,?,?,?,?,?,?,?,?,?)`,
      [vid, date, time, memo, cashId, goldId, silverId, createdBy, createdAt, branchId, branchLocalNumber]);
    console.log('[voucher-add] Voucher header insert result:', insertResult);
    if (lines.length){
      for (const L of lines){
        await tursoSync.run(`INSERT INTO voucher_lines (voucher_id, customer_id, supplier_id, account_id, amount, weight, karat, account_no, note)
                              VALUES (?,?,?,?,?,?,?,?,?)`,
          [vid, L.customer_id ?? null, L.supplier_id ?? null, L.account_id ?? null,
                Number(L.amount||0)||0, Number(L.weight||0)||0, L.karat || null, L.account_no || null, L.note || null]);
      }
    } else {
      await tursoSync.run(`INSERT INTO voucher_lines (voucher_id, amount, account_no, note) VALUES (?,?,?,NULL)`, [vid, fallbackAmount, fallbackAccNo]);
    }
    const id = vid; 
    
    // Create auto journal entry for voucher
    try {
      const journalLines = [];
      // استخدام الصناديق المحددة في رأس السند أو الافتراضية
      const cashBoxAccountId = cashId || getAccountIdByCode(DEFAULT_ACCOUNTS.CASH_BOX);
      const goldBoxAccountId = goldId || getAccountIdByCode(DEFAULT_ACCOUNTS.GOLD_BOX);
      const silverId = p.silver_account_id || 999;
      const silverKarats = ['999', '925', '900', '800'];
      const headerMemo = memo || ''; // بيان رأس السند للصندوق
      
      for (const L of lines) {
        const amount = Number(L.amount || 0);
        const weight = Number(L.weight || 0);
        const lineNote = L.note || L.description || ''; // بيان السطر للعميل
        // استخدام العيار الفعلي من السطر - لا نستخدم قيمة افتراضية
        const lineKarat = L.karat ? String(L.karat) : null;
        const isSilver = lineKarat && silverKarats.includes(lineKarat);
        
        // جلب اسم العميل/المورد/الحساب لبيان الصندوق
        let entityName = '';
        let entityType = '';
        if (L.customer_id) {
          const cust = await tursoSync.queryOne('SELECT name FROM customers WHERE id = ?', [L.customer_id]);
          entityName = cust ? cust.name : '';
          entityType = 'للعميل';
        } else if (L.supplier_id) {
          const supp = await tursoSync.queryOne('SELECT name FROM suppliers WHERE id = ?', [L.supplier_id]);
          entityName = supp ? supp.name : '';
          entityType = 'للمورد';
        } else if (L.account_id) {
          const acct = await tursoSync.queryOne('SELECT name FROM accounts WHERE id = ?', [L.account_id]);
          entityName = acct ? acct.name : '';
          entityType = 'للحساب';
        }
        const entitySuffix = entityName ? ` ${entityType} ( ${entityName} )` : '';
        
        // Cash voucher: Customer/Supplier/Account debit (received money), Cash box credit
        if (amount > 0) {
          const customerMemo = lineNote || 'صرف نقدي'; // بيان العميل من السطر
          const boxMemo = (headerMemo || 'صرف نقدي') + entitySuffix; // بيان الصندوق مع اسم الطرف
          journalLines.push({ customer_id: L.customer_id || null, supplier_id: L.supplier_id || null, account_id: L.account_id || null, debit: amount, credit: 0, currency_type: 'ريال', memo: customerMemo });
          journalLines.push({ account_id: cashBoxAccountId, debit: 0, credit: amount, currency_type: 'ريال', memo: boxMemo });
        }
        
        // Gold/Silver voucher: Customer/Supplier debit (received), Box credit (out)
        if (weight > 0) {
          const boxAccountId = isSilver ? silverId : goldBoxAccountId;
          const currencyType = isSilver ? 'فضة' : 'ذهب';
          const customerMemo = lineNote || (isSilver ? 'صرف فضة' : 'صرف ذهب'); // بيان العميل من السطر
          const boxMemo = (headerMemo || (isSilver ? 'صرف فضة' : 'صرف ذهب')) + entitySuffix; // بيان الصندوق مع اسم الطرف
          journalLines.push({ customer_id: L.customer_id || null, supplier_id: L.supplier_id || null, account_id: L.account_id || null, debit: weight, credit: 0, currency_type: currencyType, karat: lineKarat, memo: customerMemo });
          journalLines.push({ account_id: boxAccountId, debit: 0, credit: weight, currency_type: currencyType, karat: lineKarat, memo: boxMemo });
        }
      }
      
      if (journalLines.length > 0) {
        await createAutoJournalEntry('voucher', id, date, `قيد تلقائي - سند صرف رقم ${branchLocalNumber}`, journalLines, createdBy, { branchId });
      }
    } catch (journalError) {
      console.error('Error creating auto journal for voucher:', journalError);
    }
    
    broadcastCloudDataUpdated({
      source: 'local',
      action: 'insert',
      tables: ['vouchers'],
      entityType: 'voucher',
      documentId: Number(id) || 0,
      branchId,
      actorUserId: Number(createdBy) || null,
      actorName: await resolveUserDisplayNameById(createdBy),
      changes: 1,
    });

    void sendWaTransactionNotification('voucher', {
      actionText: 'تمت عملية صرف',
      actorName: await resolveUserDisplayNameById(createdBy),
      documentNo: branchLocalNumber,
      documentId: id,
      ref: lines.find((l) => l?.customer_id || l?.supplier_id || l?.account_id) || {},
      movement: extractMovementSummaryFromReceiptOrVoucherLines(lines),
    });
    return { success:true, id, branch_local_number: branchLocalNumber }; 
  }catch(error){ return { success:false, error: error.message }; }
});

ipcMain.handle('user-add', async (_e, payload) => {
  try {
    const p = payload || {};
    const username = p.username || null;
    const password = p.password || null;
    const passwordHint = p.password_hint || null;
    const fullName = p.full_name || null;
    const role = p.role || null;
    const active = p.active || null;
    const createdBy = p.created_by || null;
    const createdAt = getLocalDateTime();
    
    if (!username || !password || !fullName || !role) {
      return { success: false, error: 'بيانات المستخدم غير مكتملة' };
    }
    
    const existing = await tursoSync.queryOne('SELECT id FROM users WHERE username = ?', [username]);
    if (existing) {
      return { success: false, error: 'اسم المستخدم موجود مسبقاً' };
    }
    
    const hashedPassword = await hashPassword(password);
    const result = await tursoSync.run(`
      INSERT INTO users (username, password, password_hint, full_name, role, active, created_by, created_at)
      VALUES (?, ?, ?, ?, ?, ?, ?, ?)
    `, [username, hashedPassword, passwordHint, fullName, role, active, createdBy, createdAt]);
    const insertedId = Number(result?.lastInsertRowid || 0) || null;
    if (insertedId) {
      await saveUserBranchAssignments(insertedId, p);
    }
    const user = insertedId
      ? await tursoSync.queryOne('SELECT id, username, password_hint, full_name, role, active, created_by, created_at FROM users WHERE id = ?', [insertedId])
      : await tursoSync.queryOne('SELECT id, username, password_hint, full_name, role, active, created_by, created_at FROM users WHERE username = ?', [username]);
    invalidateUsersCache();
    broadcastCloudDataUpdated({
      source: 'local',
      action: 'insert',
      tables: ['users', 'user_branches'],
      entityType: 'users',
      documentId: Number(user?.id) || 0,
      actorUserId: Number(user?.created_by) || null,
      changes: 1,
    });
    return { success: true, id: Number(user?.id) || null, data: user };
  } catch (error) {
    return { success: false, error: error.message };
  }
});

function normalizeAccountRecord(record = {}) {
  const isParent = Number(record?.is_parent || 0) || 0;
  const isSystem = Number(record?.is_system || 0) || 0;
  const normalizedBranchId = record?.branch_id === null || record?.branch_id === undefined || record?.branch_id === ''
    ? null
    : (Number(record.branch_id) || null);
  const isSharedAcrossBranches = isSystem === 1 || isParent === 1 || normalizedBranchId === null;
  return {
    ...record,
    id: Number(record?.id || 0) || 0,
    branch_id: isSharedAcrossBranches ? null : normalizedBranchId,
    branch_name: isSharedAcrossBranches ? '' : String(record?.branch_name || '').trim(),
    branch_code: isSharedAcrossBranches ? '' : String(record?.branch_code || '').trim(),
    parent_id: record?.parent_id === null || record?.parent_id === undefined || record?.parent_id === ''
      ? null
      : (Number(record.parent_id) || null),
    level: Number(record?.level || 0) || 1,
    is_parent: isParent,
    is_system: isSystem,
    active: record?.active === null || record?.active === undefined ? 1 : (Number(record.active) || 0),
    balance: Number(record?.balance || 0) || 0,
    debt_limit: Number(record?.debt_limit || 0) || 0,
    is_shared_across_branches: isSharedAcrossBranches ? 1 : 0,
  };
}

function invalidateAccountsCaches() {
  tursoSync.invalidateCache('accounts');
  tursoSync.invalidateCache('accountsFlat');
  tursoSync.invalidateCache('accountsStats');
  tursoSync.invalidateCache('defaultBoxes');
}

function inferAccountTypeFromCode(code) {
  const value = String(code || '').trim();
  const first = value.charAt(0);
  if (first === '2') return 'liability';
  if (first === '3') return 'equity';
  if (first === '4') return 'revenue';
  if (first === '5') return 'expense';
  return 'asset';
}

function inferAccountNature(accountType) {
  const value = String(accountType || '').trim().toLowerCase();
  if (value === 'liability' || value === 'equity' || value === 'revenue') {
    return 'credit';
  }
  return 'debit';
}

async function loadAccountsCollection(options = {}) {
  const forceFresh = Boolean(options?.forceFresh);
  const mainBranchId = getDefaultMainBranchIdSync();
  const branchId = normalizePositiveId(options?.branchId ?? options?.branch_id, mainBranchId) || mainBranchId;
  const branchIds = normalizeBranchIdList(options?.branchIds).length
    ? normalizeBranchIdList(options.branchIds)
    : [branchId];
  const useMainBranchCache = branchIds.length === 1 && branchIds[0] === mainBranchId;
  if (!forceFresh && useMainBranchCache) {
    const cached = tursoSync.getCache('accounts');
    if (Array.isArray(cached)) {
      return cached;
    }
  }

  const accountWhere = buildSystemOrBranchWhereClause('accounts', branchIds, mainBranchId);

  const rows = await tursoSync.queryAll(`
    SELECT id, code, name, name_en, parent_id, account_type, nature, level, is_parent, is_system, active, description, balance, debt_limit, created_at, branch_id,
           COALESCE((SELECT name FROM branches branch_lookup WHERE branch_lookup.id = COALESCE(accounts.branch_id, ${mainBranchId}) LIMIT 1), '') AS branch_name,
           COALESCE((SELECT code FROM branches branch_lookup WHERE branch_lookup.id = COALESCE(accounts.branch_id, ${mainBranchId}) LIMIT 1), '') AS branch_code
    FROM accounts
    WHERE ${accountWhere.sql}
    ORDER BY code ASC, id ASC
  `, accountWhere.params);
  const data = rows.map((row) => normalizeAccountRecord(row));
  if (useMainBranchCache) {
    tursoSync.setCache('accounts', data);
    tursoSync.setCache('accountsFlat', data);
  }
  return data;
}

