try { ipcMain.removeHandler('get-accounts-stats'); } catch (_) {}
ipcMain.handle('get-accounts-stats', async (event, options = {}) => {
  try {
    const forceFresh = Boolean(options?.forceFresh);
    const mainBranchId = getDefaultMainBranchIdSync();
    const scopeInfo = await resolveBranchScopeForRequest(event, options, mainBranchId);
    const branchIds = getEffectiveBranchIdsForScope(scopeInfo, mainBranchId);
    const useMainBranchCache = branchIds.length === 1 && branchIds[0] === mainBranchId;
    if (!forceFresh && useMainBranchCache) {
      const cached = tursoSync.getCache('accountsStats');
      if (cached) {
        return { success: true, data: cached };
      }
    }
    const accounts = await loadAccountsCollection({ forceFresh, branchId: scopeInfo.branchId, branchIds });
    const data = {
      total: accounts.length,
      asset: 0,
      liability: 0,
      equity: 0,
      revenue: 0,
      expense: 0,
      active: 0,
      inactive: 0,
      parents: 0,
      leafs: 0,
    };
    for (const account of accounts) {
      const type = String(account?.account_type || '').trim().toLowerCase();
      if (Object.prototype.hasOwnProperty.call(data, type)) {
        data[type] += 1;
      }
      if (Number(account?.active || 0) === 1) data.active += 1;
      else data.inactive += 1;
      if (Number(account?.is_parent || 0) === 1) data.parents += 1;
      else data.leafs += 1;
    }
    if (useMainBranchCache) {
      tursoSync.setCache('accountsStats', data);
    }
    return { success: true, data };
  } catch (error) {
    return { success: false, error: error.message };
  }
});

