try { ipcMain.removeHandler('get-next-account-code'); } catch (_) {}
ipcMain.handle('get-next-account-code', async (event, payload) => {
  try {
    const parentCodeValue = (payload && typeof payload === 'object') ? (payload.parentCode ?? payload.code) : payload;
    const parentCode = String(parentCodeValue || '').trim();
    const branchId = await resolveBranchIdForRequest(event, payload, getDefaultMainBranchIdSync());

    if (!parentCode) {
      const roots = await tursoSync.queryAll('SELECT code FROM accounts WHERE parent_id IS NULL ORDER BY code ASC, id ASC');
      const numericCodes = roots
        .map((row) => String(row?.code || '').trim())
        .filter((code) => /^\d+$/.test(code))
        .map((code) => Number(code));
      const nextCode = numericCodes.length ? String(Math.max(...numericCodes) + 1) : '1';
      return { success: true, nextCode };
    }

    const parent = await tursoSync.queryOne('SELECT id, code, branch_id, is_system, is_parent FROM accounts WHERE code = ? LIMIT 1', [parentCode]);
    if (!parent) {
      return { success: false, error: 'الحساب الأب غير موجود' };
    }
    const parentBranchId = normalizePositiveId(parent?.branch_id, null);
    if (parentBranchId && parentBranchId !== branchId && Number(parent?.is_system || 0) !== 1 && Number(parent?.is_parent || 0) !== 1) {
      return { success: false, error: 'الحساب الأب لا يتبع الفرع الحالي' };
    }

    const children = await tursoSync.queryAll('SELECT code FROM accounts WHERE parent_id = ? ORDER BY code ASC, id ASC', [parent.id]);
    const suffixes = children
      .map((row) => String(row?.code || '').trim())
      .filter((code) => code.startsWith(parentCode))
      .map((code) => code.slice(parentCode.length))
      .filter((suffix) => /^\d+$/.test(suffix));

    if (!suffixes.length) {
      return { success: true, nextCode: `${parentCode}1` };
    }

    const width = suffixes.reduce((maxWidth, suffix) => Math.max(maxWidth, suffix.length), 1);
    const maxSuffix = suffixes.reduce((maxValue, suffix) => Math.max(maxValue, Number(suffix) || 0), 0);
    return { success: true, nextCode: `${parentCode}${String(maxSuffix + 1).padStart(width, '0')}` };
  } catch (error) {
    return { success: false, error: error.message };
  }
});

