try { ipcMain.removeHandler('add-account'); } catch (_) {}
ipcMain.handle('add-account', async (event, payload = {}) => {
  try {
    const code = String(payload?.code || '').trim();
    const name = String(payload?.name || '').trim();
    if (!code || !name) {
      return { success: false, error: 'رقم الحساب واسم الحساب مطلوبان' };
    }

    const duplicate = await tursoSync.queryOne('SELECT id FROM accounts WHERE code = ? LIMIT 1', [code]);
    if (duplicate) {
      return { success: false, error: 'رقم الحساب موجود مسبقاً' };
    }

    const explicitId = Number(payload?.id || 0) || null;
    const parentId = payload?.parent_id ? Number(payload.parent_id) : null;
    const parent = parentId ? await tursoSync.queryOne('SELECT id, level, account_type, nature, branch_id, is_system, is_parent FROM accounts WHERE id = ?', [parentId]) : null;
    if (parentId && !parent) {
      return { success: false, error: 'الحساب الأب غير موجود' };
    }

    const accountType = payload?.account_type || parent?.account_type || inferAccountTypeFromCode(code);
    const nature = payload?.nature || parent?.nature || inferAccountNature(accountType);
    const level = parent ? (Number(parent.level || 1) + 1) : 1;
    const active = payload?.active === undefined ? 1 : (payload.active ? 1 : 0);
    const isParent = payload?.is_parent ? 1 : 0;
    const isSystem = payload?.is_system ? 1 : 0;
    const payloadHasExplicitAccountBranchId = Object.prototype.hasOwnProperty.call(payload || {}, 'branch_id');
    const payloadHasBranchInput = payloadHasExplicitAccountBranchId || Object.prototype.hasOwnProperty.call(payload || {}, 'branchId');
    const createdAt = payload?.created_at || getLocalDateTime();
    const requestedAccountBranchId = payloadHasExplicitAccountBranchId ? payload?.branch_id : payload?.branchId;
    let branchId = payloadHasBranchInput ? normalizePositiveId(requestedAccountBranchId, null) : null;
    const parentBranchId = normalizePositiveId(parent?.branch_id, null);
    const parentIsShared = !!parent && (Number(parent?.is_system || 0) === 1 || Number(parent?.is_parent || 0) === 1 || parentBranchId === null);
    if (!parentIsShared && parentBranchId) {
      if (payloadHasBranchInput && parentBranchId !== branchId) {
        return { success: false, error: 'يجب أن يتبع الحساب نفس فرع الحساب الأب' };
      }
      branchId = parentBranchId;
    }
    if (!isSystem && !isParent && !payloadHasBranchInput && !branchId) {
      branchId = await resolveBranchIdForRequest(event, payload, getDefaultMainBranchIdSync());
    }
    if (isSystem || isParent) {
      branchId = null;
    }

    let result;
    if (explicitId) {
      const idExists = await tursoSync.queryOne('SELECT id FROM accounts WHERE id = ? LIMIT 1', [explicitId]);
      if (idExists) {
        return { success: false, error: 'معرّف الحساب موجود مسبقاً' };
      }
      result = await tursoSync.run(
        `INSERT INTO accounts (id, code, name, name_en, parent_id, account_type, nature, level, is_parent, is_system, active, description, created_at, branch_id)
         VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
        [
          explicitId,
          code,
          name,
          payload?.name_en || null,
          parentId,
          accountType,
          nature,
          level,
          isParent,
          isSystem,
          active,
          payload?.description || null,
          createdAt,
          branchId,
        ]
      );
    } else {
      result = await tursoSync.run(
        `INSERT INTO accounts (code, name, name_en, parent_id, account_type, nature, level, is_parent, is_system, active, description, created_at, branch_id)
         VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
        [
          code,
          name,
          payload?.name_en || null,
          parentId,
          accountType,
          nature,
          level,
          isParent,
          isSystem,
          active,
          payload?.description || null,
          createdAt,
          branchId,
        ]
      );
    }

    const insertedId = explicitId || Number(result?.lastInsertRowid || 0) || null;
    if (parentId) {
      await tursoSync.run('UPDATE accounts SET is_parent = 1, branch_id = NULL WHERE id = ?', [parentId]);
    }
    invalidateAccountsCaches();
    const { actorUserId, actorName } = await resolveBroadcastActor(event, payload);
    broadcastCloudDataUpdated({
      source: 'local',
      action: 'insert',
      tables: ['accounts'],
      entityType: 'accounts',
      documentId: Number(insertedId) || 0,
      actorUserId,
      actorName,
      changes: 1,
    });
    return { success: true, id: insertedId };
  } catch (error) {
    return { success: false, error: error.message };
  }
});

try { ipcMain.removeHandler('update-account'); } catch (_) {}
ipcMain.handle('update-account', async (event, payload = {}) => {
  try {
    const id = Number(payload?.id || 0) || 0;
    if (!id) {
      return { success: false, error: 'معرّف الحساب مطلوب' };
    }
    const existing = await tursoSync.queryOne('SELECT * FROM accounts WHERE id = ?', [id]);
    if (!existing) {
      return { success: false, error: 'الحساب غير موجود' };
    }
    const merged = { ...existing, ...payload };
    const code = String(merged?.code || '').trim();
    const name = String(merged?.name || '').trim();
    if (!code || !name) {
      return { success: false, error: 'رقم الحساب واسم الحساب مطلوبان' };
    }
    const duplicate = await tursoSync.queryOne('SELECT id FROM accounts WHERE code = ? AND id != ?', [code, id]);
    if (duplicate) {
      return { success: false, error: 'رقم الحساب موجود مسبقاً' };
    }
    const payloadHasExplicitAccountBranchId = Object.prototype.hasOwnProperty.call(payload || {}, 'branch_id');
    const payloadHasBranchInput = payloadHasExplicitAccountBranchId || Object.prototype.hasOwnProperty.call(payload || {}, 'branchId');
    const parentId = merged?.parent_id ? Number(merged.parent_id) : null;
    if (parentId && parentId === id) {
      return { success: false, error: 'لا يمكن جعل الحساب أبًا لنفسه' };
    }
    const hasChildren = !!(await tursoSync.queryOne('SELECT id FROM accounts WHERE parent_id = ? LIMIT 1', [id]));
    const parent = parentId ? await tursoSync.queryOne('SELECT id, level, account_type, nature, branch_id, is_system, is_parent FROM accounts WHERE id = ?', [parentId]) : null;
    if (parentId && !parent) {
      return { success: false, error: 'الحساب الأب غير موجود' };
    }
    const accountType = merged?.account_type || parent?.account_type || inferAccountTypeFromCode(code);
    const nature = merged?.nature || parent?.nature || inferAccountNature(accountType);
    const level = parent ? (Number(parent.level || 1) + 1) : 1;
    const nextIsParent = hasChildren ? 1 : (merged?.is_parent ? 1 : 0);
    const nextIsSystem = merged?.is_system ? 1 : 0;
    const requestedAccountBranchId = payloadHasExplicitAccountBranchId ? payload?.branch_id : payload?.branchId;
    let branchId = payloadHasBranchInput
      ? normalizePositiveId(requestedAccountBranchId, null)
      : normalizePositiveId(existing?.branch_id, null);
    const parentBranchId = normalizePositiveId(parent?.branch_id, null);
    const parentIsShared = !!parent && (Number(parent?.is_system || 0) === 1 || Number(parent?.is_parent || 0) === 1 || parentBranchId === null);
    if (nextIsSystem || nextIsParent) {
      branchId = null;
    } else if (!parentIsShared && parentBranchId) {
      if (payloadHasBranchInput && parentBranchId !== branchId) {
        return { success: false, error: 'يجب أن يتبع الحساب نفس فرع الحساب الأب' };
      }
      branchId = parentBranchId;
    }
    const result = await tursoSync.run(
      `UPDATE accounts
       SET code = ?, name = ?, name_en = ?, parent_id = ?, account_type = ?, nature = ?, level = ?, is_parent = ?, is_system = ?, active = ?, description = ?, branch_id = ?
       WHERE id = ?`,
      [
        code,
        name,
        merged?.name_en || null,
        parentId,
        accountType,
        nature,
        level,
        nextIsParent,
        nextIsSystem,
        merged?.active === undefined ? (existing.active === undefined ? 1 : existing.active) : (merged.active ? 1 : 0),
        merged?.description || null,
        branchId,
        id,
      ]
    );
    invalidateAccountsCaches();
    if (Number(result?.changes) > 0) {
      const { actorUserId, actorName } = await resolveBroadcastActor(event, payload);
      broadcastCloudDataUpdated({
        source: 'local',
        action: 'update',
        tables: ['accounts'],
        entityType: 'accounts',
        documentId: Number(id) || 0,
        actorUserId,
        actorName,
        changes: Number(result?.changes) || 0,
      });
    }
    return { success: true, changes: Number(result?.changes) || 0 };
  } catch (error) {
    return { success: false, error: error.message };
  }
});

try { ipcMain.removeHandler('delete-account'); } catch (_) {}
ipcMain.handle('delete-account', async (event, id) => {
  try {
    const { id: accountId, payload: requestPayload } = parseDocumentRequestPayload(id);
    if (!accountId) {
      return { success: false, error: 'معرّف الحساب غير صالح' };
    }
    const branchId = await resolveBranchIdForRequest(event, requestPayload, getDefaultMainBranchIdSync());
    const account = await tursoSync.queryOne('SELECT id, is_system, is_parent, branch_id FROM accounts WHERE id = ?', [accountId]);
    if (!account) {
      return { success: false, error: 'الحساب غير موجود' };
    }
    if (Number(account.is_system || 0) === 1) {
      return { success: false, error: 'لا يمكن حذف حساب نظامي' };
    }
    const accountBranchId = normalizePositiveId(account?.branch_id, null);
    if (accountBranchId && accountBranchId !== branchId && Number(account.is_parent || 0) !== 1) {
      return { success: false, error: 'الحساب لا يتبع الفرع الحالي' };
    }
    const child = await tursoSync.queryOne('SELECT id FROM accounts WHERE parent_id = ? LIMIT 1', [accountId]);
    if (child) {
      return { success: false, error: 'لا يمكن حذف حساب رئيسي أو لديه فروع' };
    }
    await ensureDefaultBoxesTableReady();
    await tursoSync.run('DELETE FROM default_boxes WHERE account_id = ?', [accountId]);
    const info = await tursoSync.run('DELETE FROM accounts WHERE id = ?', [accountId]);
    invalidateAccountsCaches();
    if (Number(info?.changes) > 0) {
      const { actorUserId, actorName } = await resolveBroadcastActor(event);
      broadcastCloudDataUpdated({
        source: 'local',
        action: 'delete',
        tables: ['accounts'],
        entityType: 'accounts',
        documentId: Number(accountId) || 0,
        actorUserId,
        actorName,
        changes: Number(info?.changes) || 0,
      });
      return { success: true };
    }
    return { success: false, error: 'لم يتم العثور على الحساب' };
  } catch (error) {
    return handleForeignKeyError(error, 'حساب');
  }
});

function invalidatePartyCaches(scope) {
  const prefix = scope === 'supplier' ? 'suppliers' : 'customers';
  tursoSync.invalidateCache(prefix);
  tursoSync.invalidateCache(`${prefix}Stats`);
  tursoSync.invalidateCache(`${prefix}Debt`);
}

function normalizeCategoryType(value, fallback = null) {
  const normalized = String(value || '').trim().toLowerCase();
  if (normalized === 'customer' || normalized === 'supplier' || normalized === 'both') {
    return normalized;
  }
  return fallback;
}

function invalidateCategoryCaches() {
  [
    'categories',
    'categories:all',
    'categories:customer',
    'categories:supplier',
    'categories:both'
  ].forEach((key) => tursoSync.invalidateCache(key));
}

async function syncLinkedPartyAccountName(accountId, partyName) {
  if (!accountId) return;
  await tursoSync.run('UPDATE accounts SET name = ?, name_en = ? WHERE id = ?', [partyName, partyName, accountId]);
}

async function ensureLinkedPartyAccount(scope, partyId, partyName, createdAt) {
  const parentCode = scope === 'supplier' ? '211' : '114';
  const accountType = scope === 'supplier' ? 'liability' : 'asset';
  const nature = scope === 'supplier' ? 'credit' : 'debit';
  const branchId = normalizePositiveId(arguments[4]?.branchId ?? arguments[4]?.branch_id, getDefaultMainBranchIdSync()) || getDefaultMainBranchIdSync();
  const parent = await tursoSync.queryOne('SELECT id FROM accounts WHERE code = ?', [parentCode]);
  if (!parent || !parent.id) return null;
  const accountCode = `${parentCode}${partyId}`;
  const existing = await tursoSync.queryOne('SELECT id, branch_id FROM accounts WHERE code = ?', [accountCode]);
  if (existing && existing.id) {
    await syncLinkedPartyAccountName(existing.id, partyName);
    if (existing?.branch_id !== null && existing?.branch_id !== undefined && Number(existing.branch_id) === 0) {
      await tursoSync.run('UPDATE accounts SET branch_id = ? WHERE id = ? AND COALESCE(is_system, 0) = 0', [branchId, existing.id]);
    }
    return Number(existing.id);
  }
  const result = await tursoSync.run(
    `INSERT INTO accounts (code, name, name_en, parent_id, account_type, nature, level, is_parent, active, created_at, branch_id)
      VALUES (?, ?, ?, ?, ?, ?, 4, 0, 1, ?, ?)`,
    [accountCode, partyName, partyName, parent.id, accountType, nature, createdAt, branchId]
  );
  return Number(result?.lastInsertRowid) || null;
}

async function getPartyBalanceRows(scope, options = {}) {
  const isSupplier = scope === 'supplier';
  const tableName = isSupplier ? 'suppliers' : 'customers';
  const alias = isSupplier ? 's' : 'c';
  const entityIdField = isSupplier ? 'supplier_id' : 'customer_id';
  const requestedGoldBaseKarat = Number(options?.goldBaseKarat || 21);
  const goldBaseKarat = requestedGoldBaseKarat > 0 ? requestedGoldBaseKarat : 21;
  const mainBranchId = getDefaultMainBranchIdSync();
  const branchId = normalizePositiveId(options?.branchId ?? options?.branch_id, mainBranchId) || mainBranchId;
  const effectiveBranchIds = normalizeBranchIdList(options?.branchIds ?? options?.branch_ids);
  const branchIds = effectiveBranchIds.length ? effectiveBranchIds : [branchId];
  const accessFilter = buildPartyBranchAccessWhereClause(scope, alias, branchIds, mainBranchId);
  const placeholders = branchIds.map(() => '?').join(', ');
  return await tursoSync.queryAll(`
    SELECT
      ${alias}.id AS id,
      ${alias}.name AS name,
      COALESCE(${alias}.branch_id, ${mainBranchId}) AS branch_id,
      COALESCE((SELECT name FROM branches branch_lookup WHERE branch_lookup.id = COALESCE(${alias}.branch_id, ${mainBranchId}) LIMIT 1), '') AS branch_name,
      COALESCE((SELECT code FROM branches branch_lookup WHERE branch_lookup.id = COALESCE(${alias}.branch_id, ${mainBranchId}) LIMIT 1), '') AS branch_code,
      ROUND(
        COALESCE(SUM(CASE WHEN jl.currency_type IS NULL OR jl.currency_type = '' OR jl.currency_type LIKE '%ريال%' THEN jl.debit ELSE 0 END), 0) -
        COALESCE(SUM(CASE WHEN jl.currency_type IS NULL OR jl.currency_type = '' OR jl.currency_type LIKE '%ريال%' THEN jl.credit ELSE 0 END), 0),
        2
      ) AS cash_balance,
      ROUND(
        COALESCE(SUM(CASE
          WHEN (jl.currency_type LIKE '%ذهب%' OR jl.currency_type LIKE '%gold%')
               AND CAST(COALESCE(NULLIF(jl.karat,''), '0') AS INTEGER) NOT IN (999,925,900,800)
            THEN jl.debit * (CAST(COALESCE(NULLIF(jl.karat,''), '21') AS REAL) / ${goldBaseKarat})
          ELSE 0
        END), 0) -
        COALESCE(SUM(CASE
          WHEN (jl.currency_type LIKE '%ذهب%' OR jl.currency_type LIKE '%gold%')
               AND CAST(COALESCE(NULLIF(jl.karat,''), '0') AS INTEGER) NOT IN (999,925,900,800)
            THEN jl.credit * (CAST(COALESCE(NULLIF(jl.karat,''), '21') AS REAL) / ${goldBaseKarat})
          ELSE 0
        END), 0),
        3
      ) AS gold_balance
    FROM ${tableName} ${alias}
    LEFT JOIN journal_lines jl ON jl.${entityIdField} = ${alias}.id
    LEFT JOIN journal_entries je ON je.id = jl.journal_id
    WHERE ${accessFilter.sql}
      AND (je.id IS NULL OR COALESCE(je.branch_id, ${mainBranchId}) IN (${placeholders}))
    GROUP BY ${alias}.id, ${alias}.name, COALESCE(${alias}.branch_id, ${mainBranchId})
    ORDER BY ${alias}.id DESC
  `, [...accessFilter.params, ...branchIds]);
}

async function getPartyDebtSummary(scope, options = {}) {
  const rows = await getPartyBalanceRows(scope, options);
  return rows.reduce((acc, row) => {
    acc.cash += Number(row?.cash_balance || 0);
    acc.gold += Number(row?.gold_balance || 0);
    return acc;
  }, { cash: 0, gold: 0 });
}

ipcMain.handle('get-categories', async (_e, options = {}) => {
  try {
    const requestedType = normalizeCategoryType(options?.type, null);
    const forceFresh = !!options?.forceFresh;
    const cacheKey = `categories:${requestedType || 'all'}`;
    const cached = forceFresh ? null : tursoSync.getCache(cacheKey);
    if (cached) {
      return { success: true, data: cached };
    }

    let whereClause = '';
    const params = [];
    if (requestedType === 'customer' || requestedType === 'supplier') {
      whereClause = 'WHERE type IN (?, ?)';
      params.push(requestedType, 'both');
    } else if (requestedType === 'both') {
      whereClause = 'WHERE type = ?';
      params.push('both');
    }

    const rows = await tursoSync.queryAll(
      `SELECT id, name, type, created_at
       FROM categories
       ${whereClause}
       ORDER BY name COLLATE NOCASE ASC, id DESC`,
      params
    );
    tursoSync.setCache(cacheKey, rows);
    return { success: true, data: rows };
  } catch (error) {
    return { success: false, error: error.message };
  }
});

ipcMain.handle('add-category', async (_e, payload = {}) => {
  try {
    const categoryName = String(payload?.name || '').trim();
    if (!categoryName) {
      return { success: false, error: 'اسم التصنيف مطلوب' };
    }

    const requestedType = normalizeCategoryType(payload?.type, 'both');
    const existing = await tursoSync.queryOne(
      `SELECT id, name, type
       FROM categories
       WHERE LOWER(TRIM(name)) = LOWER(TRIM(?))
       LIMIT 1`,
      [categoryName]
    );

    if (existing) {
      const existingId = Number(existing.id) || 0;
      const existingType = normalizeCategoryType(existing.type, 'both');
      let merged = false;

      if (existingType !== requestedType && existingType !== 'both' && requestedType !== 'both') {
        const info = await tursoSync.run('UPDATE categories SET type = ? WHERE id = ?', ['both', existingId]);
        merged = Number(info?.changes || 0) > 0;
        if (merged) {
          broadcastCloudDataUpdated({
            source: 'local',
            action: 'update',
            tables: ['categories'],
            entityType: 'categories',
            documentId: existingId,
            changes: Number(info?.changes) || 0,
          });
        }
      }

      invalidateCategoryCaches();
      return { success: true, id: existingId, alreadyExists: !merged, merged };
    }

    const createdAt = getLocalDateTime();
    const info = await tursoSync.run(
      'INSERT INTO categories (name, type, created_at) VALUES (?, ?, ?)',
      [categoryName, requestedType, createdAt]
    );
    const insertedId = Number(info?.lastInsertRowid) || 0;
    invalidateCategoryCaches();
    broadcastCloudDataUpdated({
      source: 'local',
      action: 'insert',
      tables: ['categories'],
      entityType: 'categories',
      documentId: insertedId,
      changes: 1,
    });
    return { success: true, id: insertedId };
  } catch (error) {
    return { success: false, error: error.message };
  }
});

ipcMain.handle('delete-category', async (_e, payload) => {
  try {
    const categoryId = Number((payload && typeof payload === 'object') ? (payload.id ?? payload.categoryId) : payload);
    if (!Number.isFinite(categoryId) || categoryId <= 0) {
      return { success: false, error: 'معرف التصنيف غير صالح' };
    }

    const requestedScope = normalizeCategoryType((payload && typeof payload === 'object') ? payload.type : null, null);
    const category = await tursoSync.queryOne('SELECT id, name, type FROM categories WHERE id = ?', [categoryId]);
    if (!category) {
      return { success: false, error: 'لم يتم العثور على التصنيف' };
    }

    const categoryName = String(category.name || '').trim();
    const existingType = normalizeCategoryType(category.type, 'both');

    if (existingType === 'both' && (requestedScope === 'customer' || requestedScope === 'supplier')) {
      const remainingType = requestedScope === 'customer' ? 'supplier' : 'customer';
      const updateInfo = await tursoSync.run('UPDATE categories SET type = ? WHERE id = ?', [remainingType, categoryId]);
      let clearedChanges = 0;
      const affectedTables = ['categories'];

      if (requestedScope === 'customer') {
        const clearInfo = await tursoSync.run('UPDATE customers SET category = NULL WHERE category = ?', [categoryName]);
        clearedChanges += Number(clearInfo?.changes || 0);
        affectedTables.push('customers');
        invalidatePartyCaches('customer');
      } else {
        const clearInfo = await tursoSync.run('UPDATE suppliers SET category = NULL WHERE category = ?', [categoryName]);
        clearedChanges += Number(clearInfo?.changes || 0);
        affectedTables.push('suppliers');
        invalidatePartyCaches('supplier');
      }

      invalidateCategoryCaches();
      broadcastCloudDataUpdated({
        source: 'local',
        action: 'update',
        tables: affectedTables,
        entityType: 'categories',
        documentId: categoryId,
        changes: Number(updateInfo?.changes || 0) + clearedChanges,
      });
      return { success: true, downgraded: true, remainingType };
    }

    const scopesToClear = [];
    if (existingType === 'customer') {
      scopesToClear.push('customer');
    } else if (existingType === 'supplier') {
      scopesToClear.push('supplier');
    } else {
      scopesToClear.push('customer', 'supplier');
    }

    let clearedChanges = 0;
    const affectedTables = ['categories'];
    for (const scope of scopesToClear) {
      if (scope === 'customer') {
        const clearInfo = await tursoSync.run('UPDATE customers SET category = NULL WHERE category = ?', [categoryName]);
        clearedChanges += Number(clearInfo?.changes || 0);
        affectedTables.push('customers');
        invalidatePartyCaches('customer');
      } else {
        const clearInfo = await tursoSync.run('UPDATE suppliers SET category = NULL WHERE category = ?', [categoryName]);
        clearedChanges += Number(clearInfo?.changes || 0);
        affectedTables.push('suppliers');
        invalidatePartyCaches('supplier');
      }
    }

    const deleteInfo = await tursoSync.run('DELETE FROM categories WHERE id = ?', [categoryId]);
    if (Number(deleteInfo?.changes || 0) <= 0) {
      return { success: false, error: 'لم يتم العثور على التصنيف' };
    }

    invalidateCategoryCaches();
    broadcastCloudDataUpdated({
      source: 'local',
      action: 'delete',
      tables: affectedTables,
      entityType: 'categories',
      documentId: categoryId,
      changes: Number(deleteInfo?.changes || 0) + clearedChanges,
    });
    return { success: true };
  } catch (error) {
    return { success: false, error: error.message };
  }
});

ipcMain.handle('get-customers', async (event, options = {}) => {
  try {
    const forceFresh = !!options?.forceFresh;
    const mainBranchId = getDefaultMainBranchIdSync();
    const scopeInfo = await resolveBranchScopeForRequest(event, options, mainBranchId);
    const branchIds = scopeInfo.isAllBranches ? scopeInfo.allowedBranchIds : [scopeInfo.branchId];
    const accessFilter = buildPartyBranchAccessWhereClause('customer', 'c', branchIds, mainBranchId);
    const useMainBranchCache = !scopeInfo.isAllBranches && scopeInfo.branchId === mainBranchId;
    const cached = (!forceFresh && useMainBranchCache) ? tursoSync.getCache('customers') : null;
    if (cached) {
      return { success: true, data: cached };
    }
    const rows = await tursoSync.queryAll(`
      SELECT c.*, '' AS created_by_name, '' AS updated_by_name,
             COALESCE(c.branch_id, ?) AS effective_branch_id,
             COALESCE(b.name, '') AS branch_name,
             COALESCE(b.code, '') AS branch_code,
             COALESCE(c.access_scope, 'single') AS access_scope,
             COALESCE(branchAssignments.branch_count, 0) AS branch_count,
             COALESCE(branchAssignments.branch_ids_csv, '') AS branch_ids_csv,
             COALESCE(branchAssignments.branch_names, '') AS branch_names,
             COALESCE(branchAssignments.branch_codes, '') AS branch_codes
      FROM customers c
      LEFT JOIN branches b ON b.id = COALESCE(c.branch_id, ?)
      LEFT JOIN (
        SELECT cb.customer_id AS party_id,
               COUNT(*) AS branch_count,
               group_concat(cb.branch_id, ',') AS branch_ids_csv,
               group_concat(COALESCE(b2.name, ''), ', ') AS branch_names,
               group_concat(COALESCE(b2.code, ''), ', ') AS branch_codes
        FROM customer_branches cb
        LEFT JOIN branches b2 ON b2.id = cb.branch_id
        GROUP BY cb.customer_id
      ) branchAssignments ON branchAssignments.party_id = c.id
      WHERE ${accessFilter.sql}
      ORDER BY c.id DESC
    `, [mainBranchId, mainBranchId, ...accessFilter.params]);
    if (useMainBranchCache) {
      tursoSync.setCache('customers', rows);
    }
    return { success: true, data: rows };
  } catch (error) {
    return { success: false, error: error.message };
  }
});

ipcMain.handle('get-customers-stats', async (event, payload = {}) => {
  try {
    const mainBranchId = getDefaultMainBranchIdSync();
    const scopeInfo = await resolveBranchScopeForRequest(event, payload, mainBranchId);
    const branchIds = scopeInfo.isAllBranches ? scopeInfo.allowedBranchIds : [scopeInfo.branchId];
    const accessFilter = buildPartyBranchAccessWhereClause('customer', 'c', branchIds, mainBranchId);
    const useMainBranchCache = !scopeInfo.isAllBranches && scopeInfo.branchId === mainBranchId;
    const cached = useMainBranchCache ? tursoSync.getCache('customersStats') : null;
    if (cached) {
      return { success: true, ...cached };
    }
    const row = await tursoSync.queryOne(`
      SELECT
        COUNT(*) AS total,
        SUM(CASE WHEN date(substr(created_at, 1, 10)) >= date('now', 'localtime', 'start of month') THEN 1 ELSE 0 END) AS month,
        SUM(CASE WHEN date(substr(created_at, 1, 10)) >= date('now', 'localtime', '-6 days') THEN 1 ELSE 0 END) AS week
      FROM customers c
      WHERE ${accessFilter.sql}
    `, accessFilter.params);
    const stats = {
      total: Number(row?.total || 0),
      month: Number(row?.month || 0),
      week: Number(row?.week || 0),
    };
    if (useMainBranchCache) {
      tursoSync.setCache('customersStats', stats);
    }
    return { success: true, ...stats };
  } catch (error) {
    return { success: false, error: error.message };
  }
});

ipcMain.handle('get-customers-debt', async (event, payload = {}) => {
  try {
    const mainBranchId = getDefaultMainBranchIdSync();
    const scopeInfo = await resolveBranchScopeForRequest(event, payload, mainBranchId);
    const useMainBranchCache = !scopeInfo.isAllBranches && scopeInfo.branchId === mainBranchId;
    const cached = useMainBranchCache ? tursoSync.getCache('customersDebt') : null;
    if (cached) {
      return { success: true, ...cached };
    }
    const summary = await getPartyDebtSummary('customer', {
      branchId: scopeInfo.branchId,
      branchIds: scopeInfo.isAllBranches ? scopeInfo.allowedBranchIds : null,
    });
    const result = {
      cash: Number(summary.cash || 0),
      gold: Number(summary.gold || 0),
    };
    if (useMainBranchCache) {
      tursoSync.setCache('customersDebt', result);
    }
    return { success: true, ...result };
  } catch (error) {
    return { success: false, error: error.message };
  }
});

ipcMain.handle('get-open-positions', async (event, payload = {}) => {
  try {
    const scopeInfo = await resolveBranchScopeForRequest(event, payload, getDefaultMainBranchIdSync());
    const customers = await getPartyBalanceRows('customer', {
      goldBaseKarat: 24,
      branchId: scopeInfo.branchId,
      branchIds: scopeInfo.isAllBranches ? scopeInfo.allowedBranchIds : null,
    });
    const suppliers = await getPartyBalanceRows('supplier', {
      goldBaseKarat: 24,
      branchId: scopeInfo.branchId,
      branchIds: scopeInfo.isAllBranches ? scopeInfo.allowedBranchIds : null,
    });
    return {
      success: true,
      data: {
        customers: customers.filter(row => Math.abs(Number(row?.cash_balance || 0)) > 0.0001 || Math.abs(Number(row?.gold_balance || 0)) > 0.0001),
        suppliers: suppliers.filter(row => Math.abs(Number(row?.cash_balance || 0)) > 0.0001 || Math.abs(Number(row?.gold_balance || 0)) > 0.0001),
      }
    };
  } catch (error) {
    return { success: false, error: error.message };
  }
});

ipcMain.handle('add-customer', async (event, customer) => {
  try {
    const customerName = String(customer?.name || '').trim();
    if (!customerName) {
      return { success: false, error: 'اسم العميل مطلوب' };
    }
    let nextId = Number(customer?.id || 0);
    if (!nextId) {
      const row = await tursoSync.queryOne('SELECT MAX(id) as maxId FROM customers');
      nextId = Number(row?.maxId || 0) + 1;
    } else {
      const exists = await tursoSync.queryOne('SELECT 1 FROM customers WHERE id = ?', [nextId]);
      if (exists) {
        return { success: false, error: 'رقم العميل موجود مسبقاً' };
      }
    }
    const createdAt = customer?.created_at || getLocalDateTime();
    const partyAccess = await resolvePartyBranchAccessForSave(event, customer, getDefaultMainBranchIdSync());
    const accountId = await ensureLinkedPartyAccount('customer', nextId, customerName, createdAt, { branchId: partyAccess.branchId });
    await tursoSync.run(
      `INSERT INTO customers (
        id, name, tax_no, phone, region, email,
        sale_ounce_add, sale_ounce_add_enabled, sale_ounce_sub, sale_ounce_sub_enabled,
        purchase_ounce_add, purchase_ounce_add_enabled, purchase_ounce_sub, purchase_ounce_sub_enabled,
        active, created_at, updated_at, debt_limit, category, account_id, access_scope, branch_id
      ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
      [
        nextId,
        customerName,
        customer?.tax_no || null,
        customer?.phone || null,
        customer?.region || null,
        customer?.email || null,
        customer?.sale_ounce_add ?? 0,
        customer?.sale_ounce_add_enabled ? 1 : 0,
        customer?.sale_ounce_sub ?? 0,
        customer?.sale_ounce_sub_enabled ? 1 : 0,
        customer?.purchase_ounce_add ?? 0,
        customer?.purchase_ounce_add_enabled ? 1 : 0,
        customer?.purchase_ounce_sub ?? 0,
        customer?.purchase_ounce_sub_enabled ? 1 : 0,
        customer?.active === undefined ? 1 : (customer.active ? 1 : 0),
        createdAt,
        createdAt,
        customer?.debt_limit ?? 0,
        customer?.category || null,
        accountId,
        partyAccess.accessScope,
        partyAccess.branchId
      ]
    );
    await savePartyBranchAssignments('customer', nextId, partyAccess.accessScope === 'all' ? [] : partyAccess.branchIds, createdAt);
    invalidatePartyCaches('customer');
    invalidateAccountsCaches();
    broadcastCloudDataUpdated({
      source: 'local',
      action: 'insert',
      tables: ['customers', 'customer_branches', 'accounts'],
      entityType: 'customers',
      documentId: Number(nextId) || 0,
      customerId: Number(nextId) || 0,
      branchId: getPartyBroadcastBranchId({ access_scope: partyAccess.accessScope, assigned_branch_ids: partyAccess.branchIds, branch_id: partyAccess.branchId }),
      actorUserId: Number(customer?.created_by) || null,
      actorName: await resolveUserDisplayNameById(customer?.created_by),
      changes: 1,
    });
    return { success: true, id: nextId, account_id: accountId };
  } catch (error) {
    return { success: false, error: error.message };
  }
});

// IPC handler to delete a customer
ipcMain.handle('delete-customer', async (event, id) => {
  try {
    const { id: customerId, payload: requestPayload } = parseDocumentRequestPayload(id);
    if (!customerId) {
      return { success: false, error: 'رقم العميل غير صالح' };
    }
    const branchId = await resolveBranchIdForRequest(event, requestPayload, getDefaultMainBranchIdSync());
    const customerAccess = await getPartyBranchAccessInfo('customer', customerId);
    if (!customerAccess) {
      return { success: false, error: 'لم يتم العثور على العميل' };
    }
    if (!partyAccessAllowsBranch(customerAccess, branchId)) {
      return { success: false, error: 'العميل لا يتبع الفرع الحالي' };
    }
    const { actorUserId, actorName } = await resolveBroadcastActor(event, requestPayload);
    
    const info = await tursoSync.run('DELETE FROM customers WHERE id = ?', [customerId]);
    if (info.changes > 0) {
      try {
        await tursoSync.run('DELETE FROM customer_branches WHERE customer_id = ?', [customerId]);
      } catch (_) {}
      if (customerAccess && customerAccess.account_id) {
        try {
          await tursoSync.run('DELETE FROM accounts WHERE id = ? AND is_system = 0', [customerAccess.account_id]);
        } catch(delErr) {
          console.log('Could not delete linked account:', delErr.message);
        }
      }
      tursoSync.invalidateCache('customers'); // إبطال الـ cache عند الحذف
      tursoSync.invalidateCache('customersStats');
      tursoSync.invalidateCache('customersDebt');
      invalidateAccountsCaches();
      broadcastCloudDataUpdated({
        source: 'local',
        action: 'delete',
        tables: ['customers', 'customer_branches', 'accounts'],
        entityType: 'customers',
        documentId: Number(customerId) || 0,
        customerId: Number(customerId) || null,
        branchId: getPartyBroadcastBranchId(customerAccess),
        actorUserId,
        actorName,
        changes: Number(info?.changes) || 0,
      });
      return { success: true };
    } else {
      return { success: false, error: 'لم يتم العثور على العميل' };
    }
  } catch (error) {
    return handleForeignKeyError(error, 'عميل');
  }
});

// IPC handler to update a customer
ipcMain.handle('update-customer', async (event, customer) => {
  try {
    const branchId = await resolveBranchIdForRequest(event, customer, getDefaultMainBranchIdSync());
    const { actorUserId, actorName } = await resolveBroadcastActor(event, customer, customer?.updated_by || customer?.created_by);
    const existingCustomer = await getPartyBranchAccessInfo('customer', customer?.id);
    if (!existingCustomer) {
      return { success: false, error: 'لم يتم العثور على العميل' };
    }
    if (!partyAccessAllowsBranch(existingCustomer, branchId)) {
      return { success: false, error: 'العميل لا يتبع الفرع الحالي' };
    }
    const partyAccess = hasExplicitPartyAccessSelection(customer)
      ? await resolvePartyBranchAccessForSave(event, customer, existingCustomer.branch_id || getDefaultMainBranchIdSync())
      : {
          accessScope: existingCustomer.access_scope,
          branchId: existingCustomer.branch_id,
          branchIds: existingCustomer.access_scope === 'all' ? [] : normalizeBranchIdList(existingCustomer.assigned_branch_ids),
        };
    const accountId = existingCustomer.account_id || await ensureLinkedPartyAccount('customer', customer.id, customer.name, existingCustomer.created_at || getLocalDateTime(), { branchId: partyAccess.branchId });
    const info = await tursoSync.run(
      'UPDATE customers SET name = ?, tax_no = ?, phone = ?, region = ?, email = ?, sale_ounce_add = ?, sale_ounce_add_enabled = ?, sale_ounce_sub = ?, sale_ounce_sub_enabled = ?, purchase_ounce_add = ?, purchase_ounce_add_enabled = ?, purchase_ounce_sub = ?, purchase_ounce_sub_enabled = ?, active = ?, debt_limit = ?, category = ?, updated_at = ?, account_id = ?, access_scope = ?, branch_id = ? WHERE id = ?',
      [
        customer.name,
        customer.tax_no || null,
        customer.phone,
        customer.region,
        customer.email || null,
        customer.sale_ounce_add ?? 0,
        customer.sale_ounce_add_enabled ? 1 : 0,
        customer.sale_ounce_sub ?? 0,
        customer.sale_ounce_sub_enabled ? 1 : 0,
        customer.purchase_ounce_add ?? 0,
        customer.purchase_ounce_add_enabled ? 1 : 0,
        customer.purchase_ounce_sub ?? 0,
        customer.purchase_ounce_sub_enabled ? 1 : 0,
        customer.active,
        customer.debt_limit,
        customer.category || null,
        getLocalDateTime(),
        accountId,
        partyAccess.accessScope,
        partyAccess.branchId,
        customer.id
      ]
    );
    if (info.changes > 0) {
      await savePartyBranchAssignments('customer', customer.id, partyAccess.accessScope === 'all' ? [] : partyAccess.branchIds, existingCustomer.created_at || getLocalDateTime());
      // مزامنة اسم العميل مع الحساب المرتبط في شجرة الحسابات
      try {
        if (accountId) {
          await tursoSync.run(
            'UPDATE accounts SET name = ?, name_en = ?, branch_id = CASE WHEN branch_id IS NULL THEN NULL ELSE ? END WHERE id = ? AND COALESCE(is_system, 0) = 0',
            [customer.name, customer.name, partyAccess.branchId, accountId]
          );
        }
      } catch(syncErr) {
        console.log('Could not sync customer name to account:', syncErr.message);
      }
      
      tursoSync.invalidateCache('customers'); // إبطال الـ cache عند التعديل
      tursoSync.invalidateCache('customersStats');
      tursoSync.invalidateCache('customersDebt');
      invalidatePartyCaches('customer');
      invalidateAccountsCaches();
      broadcastCloudDataUpdated({
        source: 'local',
        action: 'update',
        tables: ['customers', 'customer_branches', 'accounts'],
        entityType: 'customers',
        documentId: Number(customer.id) || 0,
        customerId: Number(customer.id) || null,
        branchId: getPartyBroadcastBranchId({ access_scope: partyAccess.accessScope, assigned_branch_ids: partyAccess.branchIds, branch_id: partyAccess.branchId }),
        actorUserId,
        actorName,
        changes: Number(info?.changes) || 0,
      });
      return { success: true };
    } else {
      return { success: false, error: 'لم يتم العثور على العميل' };
    }
  } catch (error) {
    return { success: false, error: error.message };
  }
});

