ipcMain.handle('get-suppliers', async (event, options = {}) => {
  try {
    const forceFresh = !!options?.forceFresh;
    const mainBranchId = getDefaultMainBranchIdSync();
    const scopeInfo = await resolveBranchScopeForRequest(event, options, mainBranchId);
    const branchIds = scopeInfo.isAllBranches ? scopeInfo.allowedBranchIds : [scopeInfo.branchId];
    const accessFilter = buildPartyBranchAccessWhereClause('supplier', 's', branchIds, mainBranchId);
    const useMainBranchCache = !scopeInfo.isAllBranches && scopeInfo.branchId === mainBranchId;
    const cached = (!forceFresh && useMainBranchCache) ? tursoSync.getCache('suppliers') : null;
    if (cached) {
      return { success: true, data: cached };
    }
    const rows = await tursoSync.queryAll(`
      SELECT s.*, '' AS created_by_name, '' AS updated_by_name,
             COALESCE(s.branch_id, ?) AS effective_branch_id,
             COALESCE(b.name, '') AS branch_name,
             COALESCE(b.code, '') AS branch_code,
             COALESCE(s.access_scope, 'single') AS access_scope,
             COALESCE(branchAssignments.branch_count, 0) AS branch_count,
             COALESCE(branchAssignments.branch_ids_csv, '') AS branch_ids_csv,
             COALESCE(branchAssignments.branch_names, '') AS branch_names,
             COALESCE(branchAssignments.branch_codes, '') AS branch_codes
      FROM suppliers s
      LEFT JOIN branches b ON b.id = COALESCE(s.branch_id, ?)
      LEFT JOIN (
        SELECT sb.supplier_id AS party_id,
               COUNT(*) AS branch_count,
               group_concat(sb.branch_id, ',') AS branch_ids_csv,
               group_concat(COALESCE(b2.name, ''), ', ') AS branch_names,
               group_concat(COALESCE(b2.code, ''), ', ') AS branch_codes
        FROM supplier_branches sb
        LEFT JOIN branches b2 ON b2.id = sb.branch_id
        GROUP BY sb.supplier_id
      ) branchAssignments ON branchAssignments.party_id = s.id
      WHERE ${accessFilter.sql}
      ORDER BY s.id DESC
    `, [mainBranchId, mainBranchId, ...accessFilter.params]);
    if (useMainBranchCache) {
      tursoSync.setCache('suppliers', rows);
    }
    return { success: true, data: rows };
  } catch (error) {
    return { success: false, error: error.message };
  }
});

ipcMain.handle('add-supplier', async (event, supplier) => {
  try {
    const supplierName = String(supplier?.name || '').trim();
    if (!supplierName) {
      return { success: false, error: 'اسم المورد مطلوب' };
    }
    let nextId = Number(supplier?.id || 0);
    if (!nextId) {
      const row = await tursoSync.queryOne('SELECT MAX(id) as maxId FROM suppliers');
      nextId = Number(row?.maxId || 0) + 1;
    } else {
      const exists = await tursoSync.queryOne('SELECT 1 FROM suppliers WHERE id = ?', [nextId]);
      if (exists) {
        return { success: false, error: 'رقم المورد موجود مسبقاً' };
      }
    }
    const createdAt = supplier?.created_at || getLocalDateTime();
    const partyAccess = await resolvePartyBranchAccessForSave(event, supplier, getDefaultMainBranchIdSync());
    const accountId = await ensureLinkedPartyAccount('supplier', nextId, supplierName, createdAt, { branchId: partyAccess.branchId });
    await tursoSync.run(
      `INSERT INTO suppliers (
        id, name, tax_no, phone, region, active, created_at, updated_at, debt_limit, category, email,
        sale_ounce_add, sale_ounce_add_enabled, sale_ounce_sub, sale_ounce_sub_enabled,
        purchase_ounce_add, purchase_ounce_add_enabled, purchase_ounce_sub, purchase_ounce_sub_enabled, account_id, access_scope, branch_id
      ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
      [
        nextId,
        supplierName,
        supplier?.tax_no || null,
        supplier?.phone || null,
        supplier?.region || null,
        supplier?.active === undefined ? 1 : (supplier.active ? 1 : 0),
        createdAt,
        createdAt,
        supplier?.debt_limit ?? 0,
        supplier?.category || null,
        supplier?.email || null,
        supplier?.sale_ounce_add ?? 0,
        supplier?.sale_ounce_add_enabled ? 1 : 0,
        supplier?.sale_ounce_sub ?? 0,
        supplier?.sale_ounce_sub_enabled ? 1 : 0,
        supplier?.purchase_ounce_add ?? 0,
        supplier?.purchase_ounce_add_enabled ? 1 : 0,
        supplier?.purchase_ounce_sub ?? 0,
        supplier?.purchase_ounce_sub_enabled ? 1 : 0,
        accountId,
        partyAccess.accessScope,
        partyAccess.branchId
      ]
    );
    await savePartyBranchAssignments('supplier', nextId, partyAccess.accessScope === 'all' ? [] : partyAccess.branchIds, createdAt);
    invalidatePartyCaches('supplier');
    invalidateAccountsCaches();
    broadcastCloudDataUpdated({
      source: 'local',
      action: 'insert',
      tables: ['suppliers', 'supplier_branches', 'accounts'],
      entityType: 'suppliers',
      documentId: Number(nextId) || 0,
      supplierId: Number(nextId) || 0,
      branchId: getPartyBroadcastBranchId({ access_scope: partyAccess.accessScope, assigned_branch_ids: partyAccess.branchIds, branch_id: partyAccess.branchId }),
      actorUserId: Number(supplier?.created_by) || null,
      actorName: await resolveUserDisplayNameById(supplier?.created_by),
      changes: 1,
    });
    return { success: true, id: nextId, account_id: accountId };
  } catch (error) {
    return { success: false, error: error.message };
  }
});

ipcMain.handle('update-supplier', async (_e, supplier) => {
  try {
    const branchId = await resolveBranchIdForRequest(_e, supplier, getDefaultMainBranchIdSync());
    const { actorUserId, actorName } = await resolveBroadcastActor(_e, supplier, supplier?.updated_by || supplier?.created_by);
    const existingSupplier = await getPartyBranchAccessInfo('supplier', supplier?.id);
    if (!existingSupplier) {
      return { success: false, error: 'لم يتم العثور على المورد' };
    }
    if (!partyAccessAllowsBranch(existingSupplier, branchId)) {
      return { success: false, error: 'المورد لا يتبع الفرع الحالي' };
    }
    const partyAccess = hasExplicitPartyAccessSelection(supplier)
      ? await resolvePartyBranchAccessForSave(_e, supplier, existingSupplier.branch_id || getDefaultMainBranchIdSync())
      : {
          accessScope: existingSupplier.access_scope,
          branchId: existingSupplier.branch_id,
          branchIds: existingSupplier.access_scope === 'all' ? [] : normalizeBranchIdList(existingSupplier.assigned_branch_ids),
        };
    const accountId = existingSupplier.account_id || await ensureLinkedPartyAccount('supplier', supplier.id, supplier.name, existingSupplier.created_at || getLocalDateTime(), { branchId: partyAccess.branchId });
    const info = await tursoSync.run(
      `UPDATE suppliers SET
        name = ?, tax_no = ?, phone = ?, region = ?, active = ?, debt_limit = ?, category = ?, email = ?,
        sale_ounce_add = ?, sale_ounce_add_enabled = ?, sale_ounce_sub = ?, sale_ounce_sub_enabled = ?,
        purchase_ounce_add = ?, purchase_ounce_add_enabled = ?, purchase_ounce_sub = ?, purchase_ounce_sub_enabled = ?,
        updated_at = ?, account_id = ?, access_scope = ?, branch_id = ?
      WHERE id = ?`,
      [
        supplier?.name,
        supplier?.tax_no || null,
        supplier?.phone || null,
        supplier?.region || null,
        supplier?.active ? 1 : 0,
        supplier?.debt_limit ?? 0,
        supplier?.category || null,
        supplier?.email || null,
        supplier?.sale_ounce_add ?? 0,
        supplier?.sale_ounce_add_enabled ? 1 : 0,
        supplier?.sale_ounce_sub ?? 0,
        supplier?.sale_ounce_sub_enabled ? 1 : 0,
        supplier?.purchase_ounce_add ?? 0,
        supplier?.purchase_ounce_add_enabled ? 1 : 0,
        supplier?.purchase_ounce_sub ?? 0,
        supplier?.purchase_ounce_sub_enabled ? 1 : 0,
        getLocalDateTime(),
        accountId,
        partyAccess.accessScope,
        partyAccess.branchId,
        supplier?.id
      ]
    );
    if (info.changes > 0) {
      await savePartyBranchAssignments('supplier', supplier.id, partyAccess.accessScope === 'all' ? [] : partyAccess.branchIds, existingSupplier.created_at || getLocalDateTime());
      await syncLinkedPartyAccountName(accountId, supplier?.name || '');
      await tursoSync.run(
        'UPDATE accounts SET branch_id = CASE WHEN branch_id IS NULL THEN NULL ELSE ? END WHERE id = ? AND COALESCE(is_system, 0) = 0',
        [partyAccess.branchId, accountId]
      );
      invalidatePartyCaches('supplier');
      invalidateAccountsCaches();
      broadcastCloudDataUpdated({
        source: 'local',
        action: 'update',
        tables: ['suppliers', 'supplier_branches', 'accounts'],
        entityType: 'suppliers',
        documentId: Number(supplier?.id) || 0,
        supplierId: Number(supplier?.id) || 0,
        branchId: getPartyBroadcastBranchId({ access_scope: partyAccess.accessScope, assigned_branch_ids: partyAccess.branchIds, branch_id: partyAccess.branchId }),
        actorUserId,
        actorName,
        changes: Number(info?.changes) || 0,
      });
      return { success: true };
    }
    return { success: false, error: 'لم يتم العثور على المورد' };
  } catch (error) {
    return { success: false, error: error.message };
  }
});

ipcMain.handle('delete-supplier', async (event, id) => {
  try {
    const { id: supplierId, payload: requestPayload } = parseDocumentRequestPayload(id);
    if (!supplierId) {
      return { success: false, error: 'رقم المورد غير صالح' };
    }
    const branchId = await resolveBranchIdForRequest(event, requestPayload, getDefaultMainBranchIdSync());
    const supplierAccess = await getPartyBranchAccessInfo('supplier', supplierId);
    if (!supplierAccess) {
      return { success: false, error: 'لم يتم العثور على المورد' };
    }
    if (!partyAccessAllowsBranch(supplierAccess, branchId)) {
      return { success: false, error: 'المورد لا يتبع الفرع الحالي' };
    }
    const { actorUserId, actorName } = await resolveBroadcastActor(event, requestPayload);
    const info = await tursoSync.run('DELETE FROM suppliers WHERE id = ?', [supplierId]);
    if (info.changes > 0) {
      try {
        await tursoSync.run('DELETE FROM supplier_branches WHERE supplier_id = ?', [supplierId]);
      } catch (_) {}
      if (supplierAccess && supplierAccess.account_id) {
        try {
          await tursoSync.run('DELETE FROM accounts WHERE id = ? AND is_system = 0', [supplierAccess.account_id]);
        } catch (_) {}
      }
      invalidatePartyCaches('supplier');
      invalidateAccountsCaches();
      broadcastCloudDataUpdated({
        source: 'local',
        action: 'delete',
        tables: ['suppliers', 'supplier_branches', 'accounts'],
        entityType: 'suppliers',
        documentId: Number(supplierId) || 0,
        supplierId: Number(supplierId) || 0,
        branchId: getPartyBroadcastBranchId(supplierAccess),
        actorUserId,
        actorName,
        changes: Number(info?.changes) || 0,
      });
      return { success: true };
    }
    return { success: false, error: 'لم يتم العثور على المورد' };
  } catch (error) {
    return handleForeignKeyError(error, 'مورد');
  }
});

ipcMain.handle('get-suppliers-stats', async (event, payload = {}) => {
  try {
    const mainBranchId = getDefaultMainBranchIdSync();
    const scopeInfo = await resolveBranchScopeForRequest(event, payload, mainBranchId);
    const branchIds = scopeInfo.isAllBranches ? scopeInfo.allowedBranchIds : [scopeInfo.branchId];
    const accessFilter = buildPartyBranchAccessWhereClause('supplier', 's', branchIds, mainBranchId);
    const useMainBranchCache = !scopeInfo.isAllBranches && scopeInfo.branchId === mainBranchId;
    const cached = useMainBranchCache ? tursoSync.getCache('suppliersStats') : null;
    if (cached) {
      return { success: true, ...cached };
    }
    const row = await tursoSync.queryOne(`
      SELECT
        COUNT(*) AS total,
        SUM(CASE WHEN date(substr(created_at, 1, 10)) >= date('now', 'localtime', 'start of month') THEN 1 ELSE 0 END) AS month,
        SUM(CASE WHEN date(substr(created_at, 1, 10)) >= date('now', 'localtime', '-6 days') THEN 1 ELSE 0 END) AS week
      FROM suppliers s
      WHERE ${accessFilter.sql}
    `, accessFilter.params);
    const stats = {
      total: Number(row?.total || 0),
      month: Number(row?.month || 0),
      week: Number(row?.week || 0),
    };
    if (useMainBranchCache) {
      tursoSync.setCache('suppliersStats', stats);
    }
    return { success: true, ...stats };
  } catch (error) {
    return { success: false, error: error.message };
  }
});

