async function resolveGoldItemPurity(section, defaultKarat, providedPurity) {
  const numericProvidedPurity = Number(providedPurity || 0);
  if (Number.isFinite(numericProvidedPurity) && numericProvidedPurity > 0) {
    return numericProvidedPurity;
  }

  try {
    const row = await tursoSync.queryOne(
      'SELECT purity FROM gold_karats WHERE karat = ? AND section = ? LIMIT 1',
      [Number(defaultKarat || 0) || 0, String(section || 'mashghulat')]
    );
    return Number(row?.purity || 0) || 0;
  } catch (_) {
    return 0;
  }
}

try { ipcMain.removeHandler('get-gold-items'); } catch (_) {}
ipcMain.handle('get-gold-items', async () => {
  try {
    const rows = await tursoSync.queryAll(`
      SELECT
        gi.id,
        gi.name,
        gi.name_en,
        gi.section,
        gi.default_karat,
        COALESCE(NULLIF(gi.purity, 0), gk.purity, 0) AS purity,
        gi.status,
        gi.description,
        gi.created_at,
        gi.updated_at
      FROM gold_items gi
      LEFT JOIN gold_karats gk ON gk.karat = gi.default_karat AND gk.section = gi.section
      ORDER BY
        CASE gi.section
          WHEN 'mashghulat' THEN 1
          WHEN 'kasr' THEN 2
          WHEN 'silver' THEN 3
          ELSE 4
        END,
        gi.default_karat DESC,
        gi.id DESC
    `);
    return { success: true, data: rows };
  } catch (error) {
    return { success: false, error: error.message };
  }
});

try { ipcMain.removeHandler('save-gold-item'); } catch (_) {}
ipcMain.handle('save-gold-item', async (_e, payload = {}) => {
  try {
    const id = Number(payload?.id || 0) || 0;
    const name = String(payload?.name || '').trim();
    const nameEn = String(payload?.nameEn || payload?.name_en || '').trim() || null;
    const section = String(payload?.section || 'mashghulat').trim() || 'mashghulat';
    const defaultKarat = Number(payload?.defaultKarat ?? payload?.default_karat ?? 0) || 0;
    const status = String(payload?.status || 'active').trim() || 'active';
    const description = String(payload?.description || '').trim() || null;

    if (!name) {
      return { success: false, error: 'اسم الصنف مطلوب' };
    }
    if (!defaultKarat) {
      return { success: false, error: 'العيار الافتراضي مطلوب' };
    }

    const purity = await resolveGoldItemPurity(section, defaultKarat, payload?.purity);
    const now = getLocalDateTime();

    let existing = null;
    if (id) {
      existing = await tursoSync.queryOne('SELECT id FROM gold_items WHERE id = ? LIMIT 1', [id]);
    }

    if (existing?.id) {
      const result = await tursoSync.run(
        `UPDATE gold_items
         SET name = ?, name_en = ?, section = ?, default_karat = ?, purity = ?, status = ?, description = ?, updated_at = ?
         WHERE id = ?`,
        [name, nameEn, section, defaultKarat, purity, status, description, now, id]
      );

      if (Number(result?.changes || 0) > 0) {
        broadcastCloudDataUpdated({
          source: 'local',
          action: 'update',
          tables: ['gold_items'],
          entityType: 'gold_items',
          documentId: id,
          changes: Number(result?.changes || 0),
        });
      }

      return { success: true, id };
    }

    const insertId = id || Number((await tursoSync.queryOne('SELECT COALESCE(MAX(id), 0) + 1 AS nextId FROM gold_items'))?.nextId || 1) || 1;

    const result = await tursoSync.run(
      `INSERT INTO gold_items (id, name, name_en, section, default_karat, purity, status, description, created_at, updated_at)
       VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
      [insertId, name, nameEn, section, defaultKarat, purity, status, description, now, now]
    );

    const insertedId = Number(insertId || result?.lastInsertRowid || 0) || null;
    broadcastCloudDataUpdated({
      source: 'local',
      action: 'insert',
      tables: ['gold_items'],
      entityType: 'gold_items',
      documentId: Number(insertedId) || 0,
      changes: 1,
    });

    return { success: true, id: insertedId };
  } catch (error) {
    return { success: false, error: error.message };
  }
});

