async function ensureDefaultBoxesTableReady() {
  await tursoSync.run(`
    CREATE TABLE IF NOT EXISTS default_boxes (
      branch_id INTEGER NOT NULL,
      box_type TEXT NOT NULL,
      account_id INTEGER,
      PRIMARY KEY (branch_id, box_type),
      FOREIGN KEY (branch_id) REFERENCES branches(id) ON DELETE CASCADE,
      FOREIGN KEY (account_id) REFERENCES accounts(id)
    )
  `);
}

async function ensureDefaultBoxesForBranch(branchId) {
  const normalizedBranchId = Number(branchId || 0) || getDefaultMainBranchIdSync();
  const fallbackCodes = {
    cash: '1111',
    gold: '11211',
    worked_gold: '11221',
    silver: '11231',
    diamond: '11241',
  };

  await ensureDefaultBoxesTableReady();
  const rows = await tursoSync.queryAll('SELECT box_type, account_id FROM default_boxes WHERE branch_id = ?', [normalizedBranchId]);
  const existingMap = new Map();
  rows.forEach((row) => {
    const boxType = String(row?.box_type || '').trim();
    if (boxType) {
      existingMap.set(boxType, Number(row?.account_id || 0) || null);
    }
  });

  let changed = false;
  for (const [boxType, fallbackCode] of Object.entries(fallbackCodes)) {
    const currentAccountId = existingMap.get(boxType);
    let isValid = false;

    if (currentAccountId) {
      const account = await tursoSync.queryOne(`
        SELECT id, code, is_parent, is_system, branch_id
        FROM accounts
        WHERE id = ?
        LIMIT 1
      `, [currentAccountId]);
      const accountBranchId = Number(account?.branch_id || 0) || null;
      const branchMismatch = accountBranchId && accountBranchId !== normalizedBranchId && Number(account?.is_system || 0) !== 1;
      isValid = Boolean(
        account
        && Number(account?.is_parent || 0) !== 1
        && !branchMismatch
        && doesAccountMatchDefaultBoxType(account?.code, boxType)
      );
    }

    if (isValid) {
      continue;
    }

    const fallbackAccount = await tursoSync.queryOne('SELECT id FROM accounts WHERE code = ? LIMIT 1', [fallbackCode]);
    const fallbackAccountId = Number(fallbackAccount?.id || 0) || null;
    if (!fallbackAccountId) {
      continue;
    }

    await tursoSync.run(
      'INSERT OR REPLACE INTO default_boxes (branch_id, box_type, account_id) VALUES (?, ?, ?)',
      [normalizedBranchId, boxType, fallbackAccountId]
    );
    changed = true;
  }

  if (changed && normalizedBranchId === getDefaultMainBranchIdSync()) {
    tursoSync.invalidateCache('defaultBoxes');
  }

  return changed;
}

