ipcMain.handle('get-default-boxes', async (event, payload = {}) => {
  try {
    const branchId = await resolveBranchIdForRequest(event, payload, getDefaultMainBranchIdSync());
    const forceFresh = Boolean(payload?.forceFresh);
    const useMainBranchCache = branchId === getDefaultMainBranchIdSync();
    if (!forceFresh && useMainBranchCache) {
      const cached = tursoSync.getCache('defaultBoxes');
      if (cached) {
        return { success: true, data: cached };
      }
    }
    await ensureDefaultBoxesForBranch(branchId);
    const rows = await tursoSync.queryAll(`
      SELECT db.branch_id, db.box_type, db.account_id, a.name, a.code
      FROM default_boxes db
      LEFT JOIN accounts a ON a.id = db.account_id
      WHERE db.branch_id = ?
    `, [branchId]);
    const data = {
      cash: null,
      gold: null,
      worked_gold: null,
      silver: null,
      diamond: null,
    };
    rows.forEach((row) => {
      if (row?.box_type && Object.prototype.hasOwnProperty.call(data, row.box_type)) {
        data[row.box_type] = {
          account_id: row.account_id ? Number(row.account_id) : null,
          name: row.name || null,
          code: row.code || null,
        };
      }
    });
    if (useMainBranchCache) {
      tursoSync.setCache('defaultBoxes', data);
    }
    return { success: true, data };
  } catch (error) {
    return { success: false, error: error.message };
  }
});

ipcMain.handle('set-default-box', async (event, payload = {}) => {
  try {
    const boxType = String(payload?.boxType || '').trim();
    const accountId = Number(payload?.accountId || 0) || 0;
    const branchId = await resolveBranchIdForRequest(event, payload, getDefaultMainBranchIdSync());
    const allowedBoxTypes = new Set(['cash', 'gold', 'worked_gold', 'silver', 'diamond']);

    if (!allowedBoxTypes.has(boxType)) {
      return { success: false, error: 'نوع الصندوق غير صالح' };
    }
    if (!accountId) {
      return { success: false, error: 'معرّف الحساب غير صالح' };
    }

    const account = await tursoSync.queryOne('SELECT id, branch_id, is_system FROM accounts WHERE id = ?', [accountId]);
    if (!account) {
      return { success: false, error: 'الحساب غير موجود' };
    }
    const accountBranchId = normalizePositiveId(account?.branch_id, null);
    if (accountBranchId && accountBranchId !== branchId && Number(account?.is_system || 0) !== 1) {
      return { success: false, error: 'الحساب المحدد لا يتبع الفرع الحالي' };
    }

    await ensureDefaultBoxesTableReady();
    await tursoSync.run(
      'INSERT OR REPLACE INTO default_boxes (branch_id, box_type, account_id) VALUES (?, ?, ?)',
      [branchId, boxType, accountId]
    );
    tursoSync.invalidateCache('defaultBoxes');

    broadcastCloudDataUpdated({
      source: 'local',
      action: 'update',
      tables: ['default_boxes'],
      entityType: 'default_boxes',
      documentId: Number(accountId) || 0,
      branchId,
      changes: 1,
    });

    return { success: true };
  } catch (error) {
    return { success: false, error: error.message };
  }
});

