ipcMain.handle('get-users', async (event, viewerUserId) => {
  try {
    await waitForCloudModeActivation();
    const authenticatedUser = getAuthenticatedUserFromEvent(event);
    const requestPayload = (viewerUserId && typeof viewerUserId === 'object') ? viewerUserId : { viewerUserId };
    const requestedViewerId = Number(requestPayload?.viewerUserId || requestPayload?.userId || viewerUserId);
    const requestedBranchId = normalizePositiveId(requestPayload?.branch_id ?? requestPayload?.branchId, null);
    const shouldScopeToViewer = Number.isFinite(requestedViewerId) && requestedViewerId > 0;
    const effectiveViewerId = Number(authenticatedUser?.id) || requestedViewerId;
    const effectiveViewerRole = String(authenticatedUser?.role || '').trim().toLowerCase();

    if (shouldScopeToViewer && Number.isFinite(effectiveViewerId) && effectiveViewerId > 0) {
      let viewerRole = effectiveViewerRole;
      if (!viewerRole) {
        const viewer = await tursoSync.queryOne('SELECT id, role FROM users WHERE id = ?', [effectiveViewerId]);
        viewerRole = String(viewer?.role || '').trim().toLowerCase();
      }

      if (viewerRole && viewerRole !== 'admin') {
        const viewerRow = await tursoSync.queryOne(`
          SELECT u.id, u.username, u.full_name, u.password_hint, u.role, u.active, u.created_at, u.last_login,
                 (SELECT branch_id FROM user_branches WHERE user_id = u.id AND COALESCE(is_default, 0) = 1 ORDER BY branch_id ASC LIMIT 1) AS default_branch_id,
                 (SELECT COUNT(*) FROM user_branches WHERE user_id = u.id AND COALESCE(can_login, 1) = 1) AS branch_count
          FROM users u
          WHERE u.id = ?
        `, [effectiveViewerId]);
        return { success: true, data: viewerRow ? [viewerRow] : [] };
      }
    }

    if (requestedBranchId) {
      const usersByBranch = await tursoSync.queryAll(`
        SELECT DISTINCT u.id, u.username, u.full_name, u.password_hint, u.role, u.active, u.created_at, u.last_login,
               COALESCE(ub.is_default, 0) AS is_default_for_branch,
               (SELECT branch_id FROM user_branches WHERE user_id = u.id AND COALESCE(is_default, 0) = 1 ORDER BY branch_id ASC LIMIT 1) AS default_branch_id,
               (SELECT COUNT(*) FROM user_branches WHERE user_id = u.id AND COALESCE(can_login, 1) = 1) AS branch_count
        FROM users u
        JOIN user_branches ub ON ub.user_id = u.id
        JOIN branches b ON b.id = ub.branch_id
        WHERE ub.branch_id = ?
          AND COALESCE(ub.can_login, 1) = 1
          AND COALESCE(b.active, 1) = 1
        ORDER BY u.id DESC
      `, [requestedBranchId]);
      return { success: true, data: usersByBranch };
    }

    const cached = tursoSync.getCache('users');
    if (cached) {
      return { success: true, data: cached };
    }
    const users = await tursoSync.queryAll(`
      SELECT u.id, u.username, u.full_name, u.password_hint, u.role, u.active, u.created_at, u.last_login,
             (SELECT branch_id FROM user_branches WHERE user_id = u.id AND COALESCE(is_default, 0) = 1 ORDER BY branch_id ASC LIMIT 1) AS default_branch_id,
             (SELECT COUNT(*) FROM user_branches WHERE user_id = u.id AND COALESCE(can_login, 1) = 1) AS branch_count
      FROM users u
      ORDER BY u.id DESC
    `);
    tursoSync.setCache('users', users);
    return { success: true, data: users };
  } catch (error) {
    return { success: false, error: error.message };
  }
});

// Add new user
ipcMain.handle('add-user', async (event, user) => {
  try {
    const crypto = require('crypto');
    const hashedPassword = crypto.createHash('sha256').update(user.password || 'password').digest('hex');
    
    // Find the smallest available ID (reuse deleted IDs)
    let nextId = 1;
    const existingIds = await tursoSync.queryAll('SELECT id FROM users ORDER BY id');
    const ids = existingIds.map(row => row.id);
    
    // Find first gap in sequence
    for (let i = 0; i < ids.length; i++) {
      if (ids[i] !== nextId) {
        break; // Found a gap, use this nextId
      }
      nextId++;
    }
    
    // Insert with specific ID
    const createdAt = new Date().toISOString();
    await tursoSync.run(`
      INSERT INTO users (id, username, password, password_hint, full_name, role, active, created_at)
      VALUES (?, ?, ?, ?, ?, ?, ?, ?)
    `, [
      nextId,
      user.username,
      hashedPassword,
      user.password_hint || null,
      user.full_name,
      user.role || 'user',
      user.active !== undefined ? user.active : 1,
      createdAt
    ]);
    await saveUserBranchAssignments(nextId, user || {});
    invalidateUsersCache();
    broadcastCloudDataUpdated({
      source: 'local',
      action: 'insert',
      tables: ['users', 'user_branches'],
      entityType: 'users',
      documentId: Number(nextId) || 0,
      actorUserId: Number(user?.created_by) || null,
      changes: 1,
    });
    
    return { success: true, id: nextId };
  } catch (error) {
    return { success: false, error: error.message };
  }
});

// Update user
ipcMain.handle('update-user', async (event, user) => {
  try {
    const existingUser = await tursoSync.queryOne('SELECT username, full_name, role, active FROM users WHERE id = ?', [user.id]);
    if (!existingUser) {
      return { success: false, error: 'المستخدم غير موجود' };
    }

    const authenticatedUser = getAuthenticatedUserFromEvent(event);
    const actorUserId = Number(authenticatedUser?.id) || Number(user?.updated_by || user?.created_by);
    let actorRole = String(authenticatedUser?.role || '').trim().toLowerCase();
    if (!actorRole && Number.isFinite(actorUserId) && actorUserId > 0) {
      const actorUser = await tursoSync.queryOne('SELECT role FROM users WHERE id = ?', [actorUserId]);
      actorRole = String(actorUser?.role || '').trim().toLowerCase();
    }

    if (actorRole && actorRole !== 'admin') {
      if (Number(user.id) !== actorUserId) {
        return { success: false, error: 'يمكنك تعديل حسابك فقط' };
      }
      user = {
        ...user,
        username: existingUser.username,
        full_name: existingUser.full_name,
        role: existingUser.role,
        active: existingUser.active,
      };
    }

    // Prevent deactivating or demoting default admin user
    if (existingUser.username === 'Smart Accountant') {
      if (user.active === 0) {
        return { success: false, error: 'لا يمكن تعطيل المستخدم الافتراضي (Smart Accountant)' };
      }
      if (user.role !== 'admin') {
        return { success: false, error: 'لا يمكن تغيير دور المستخدم الافتراضي (Smart Accountant) من مدير' };
      }
    }
    
    if (user.password && user.password.trim() !== '') {
      const crypto = require('crypto');
      const hashedPassword = crypto.createHash('sha256').update(user.password).digest('hex');
      await tursoSync.run(`
        UPDATE users
        SET username = ?, password = ?, password_hint = ?, full_name = ?, role = ?, active = ?
        WHERE id = ?
      `, [user.username, hashedPassword, user.password_hint || null, user.full_name, user.role, user.active, user.id]);
    } else {
      await tursoSync.run(`
        UPDATE users
        SET username = ?, password_hint = ?, full_name = ?, role = ?, active = ?
        WHERE id = ?
      `, [user.username, user.password_hint || null, user.full_name, user.role, user.active, user.id]);
    }
    if (
      Array.isArray(user?.branch_ids) ||
      Array.isArray(user?.branchIds) ||
      user?.default_branch_id !== undefined ||
      user?.defaultBranchId !== undefined ||
      user?.can_login_by_branch !== undefined ||
      user?.canLoginByBranch !== undefined ||
      user?.read_only_by_branch !== undefined ||
      user?.readOnlyByBranch !== undefined
    ) {
      await saveUserBranchAssignments(user.id, user);
    }
    invalidateUsersCache();
    broadcastCloudDataUpdated({
      source: 'local',
      action: 'update',
      tables: ['users', 'user_branches'],
      entityType: 'users',
      documentId: Number(user?.id) || 0,
      actorUserId: Number(user?.updated_by || user?.created_by) || null,
      changes: 1,
    });
    
    return { success: true };
  } catch (error) {
    return { success: false, error: error.message };
  }
});

ipcMain.handle('delete-user', async (event, id) => {
  try {
    // Prevent deleting default admin user
    const userCheck = await tursoSync.queryOne('SELECT username FROM users WHERE id = ?', [id]);
    if (!userCheck) {
      return { success: false, error: 'المستخدم غير موجود' };
    }
    
    if (userCheck.username === 'Smart Accountant') {
      return { success: false, error: 'لا يمكن حذف المستخدم الإداري الأساسي' };
    }
    
    await tursoSync.run('DELETE FROM users WHERE id = ?', [id]);
    invalidateUsersCache();
    broadcastCloudDataUpdated({
      source: 'local',
      action: 'delete',
      tables: ['users'],
      entityType: 'users',
      documentId: Number(id) || 0,
      changes: 1,
    });
    return { success: true };
  } catch (error) {
    return handleForeignKeyError(error, 'مستخدم');
  }
});

// Login handler
ipcMain.handle('authenticate-user', async (event, credentials) => {
  try {
    await waitForCloudModeActivation();
    const crypto = require('crypto');
    const hashedPassword = crypto.createHash('sha256').update(credentials.password || '').digest('hex');
    const user = await tursoSync.queryOne('SELECT id, username, full_name, role, active FROM users WHERE username = ? AND password = ?', [credentials.username, hashedPassword]);
    
    if (!user) {
      return { success: false, error: 'كلمة المرور غير صحيحة' };
    }
    
    if (user.active !== 1) {
      return { success: false, error: 'هذا الحساب غير مفعل' };
    }

    const allowedBranches = await listUserAccessibleBranches(user.id, { activeOnly: true, canLoginOnly: true });
    if (!allowedBranches.length) {
      return { success: false, error: 'هذا المستخدم غير مرتبط بأي فرع صالح للدخول' };
    }

    const requestedBranchId = normalizePositiveId(credentials?.branch_id || credentials?.branchId, null);
    const selectedBranch = requestedBranchId
      ? allowedBranches.find((branch) => Number(branch?.id || 0) === requestedBranchId)
      : (allowedBranches.find((branch) => Number(branch?.is_default || 0) === 1) || allowedBranches[0]);

    if (!selectedBranch) {
      return { success: false, error: 'هذا المستخدم غير مرتبط بالفرع المحدد' };
    }
    
    // Update last login
    await tursoSync.run('UPDATE users SET last_login = ? WHERE id = ?', [new Date().toISOString(), user.id]);
    invalidateUsersCache();
    const normalizedAllowedBranches = normalizeSessionBranchAssignments(allowedBranches);
    const enrichedUser = {
      ...user,
      branch_id: Number(selectedBranch?.id || 0) || null,
      login_branch_id: Number(selectedBranch?.id || 0) || null,
      default_branch_id: Number((allowedBranches.find((branch) => Number(branch?.is_default || 0) === 1) || selectedBranch)?.id || 0) || null,
      allowed_branch_ids: allowedBranches.map((branch) => Number(branch?.id || 0)).filter((value) => value > 0),
      allowed_branches: normalizedAllowedBranches,
      branch_read_only: Number(selectedBranch?.read_only || 0) === 1 ? 1 : 0,
      read_only_branch_ids: normalizedAllowedBranches.filter((branch) => Number(branch?.read_only || 0) === 1).map((branch) => Number(branch.id)),
    };
    setAuthenticatedUserForEvent(event, enrichedUser, {
      branch: selectedBranch,
      branchId: enrichedUser.branch_id,
      defaultBranchId: enrichedUser.default_branch_id,
      allowedBranchIds: enrichedUser.allowed_branch_ids,
      allowedBranches: normalizedAllowedBranches,
      branchReadOnly: enrichedUser.branch_read_only,
    });
    
    return { success: true, user: enrichedUser, branch: selectedBranch, branches: allowedBranches };
  } catch (error) {
    return { success: false, error: error.message };
  }
});

