ipcMain.handle('verify-smart-accountant-password', async (_event, { password } = {}) => {
  try {
    const crypto = require('crypto');
    const hashedPassword = crypto.createHash('sha256').update(password || '').digest('hex');
    const defaultAdmin = await tursoSync.queryOne(`
      SELECT id
      FROM users
      WHERE active = 1 AND (id = 1 OR username = ? OR full_name = ?)
      ORDER BY CASE
        WHEN id = 1 THEN 0
        WHEN username = ? THEN 1
        WHEN full_name = ? THEN 2
        ELSE 3
      END, id ASC
      LIMIT 1
    `, ['Smart Accountant', 'المحاسب الذكي', 'Smart Accountant', 'المحاسب الذكي']);

    if (!defaultAdmin?.id) {
      return { success: false, error: 'لم يتم العثور على مستخدم المحاسب الذكي' };
    }

    const user = await tursoSync.queryOne('SELECT id FROM users WHERE id = ? AND password = ?', [defaultAdmin.id, hashedPassword]);
    if (!user) {
      return { success: false, error: 'كلمة مرور المحاسب الذكي غير صحيحة' };
    }

    return { success: true, userId: Number(defaultAdmin.id) || 1 };
  } catch (error) {
    return { success: false, error: error.message };
  }
});

