function getEntityRowForChecks(tableName, id) {
  const numericId = Number(id || 0);
  if (!Number.isFinite(numericId) || numericId <= 0) return null;
  if (!['customers', 'suppliers', 'accounts'].includes(tableName)) return null;
  try {
    return db.prepare(`SELECT id, name, active, debt_limit, is_parent FROM ${tableName} WHERE id = ?`).get(numericId) || null;
  } catch (_) {
    return null;
  }
}

async function getEntityCashExposureForLimit(columnName, entityId, excludeJournalId = null, branchId = null) {
  const numericId = Number(entityId || 0);
  if (!Number.isFinite(numericId) || numericId <= 0) return 0;
  if (!['customer_id', 'supplier_id', 'account_id'].includes(columnName)) return 0;
  try {
    const normalizedBranchId = normalizePositiveId(branchId, null);
    let sql = `
      SELECT COALESCE(SUM(
        CASE
          WHEN jl.currency_type IS NULL OR jl.currency_type = '' OR jl.currency_type LIKE '%ريال%'
            THEN COALESCE(jl.debit, 0) - COALESCE(jl.credit, 0)
          ELSE 0
        END
      ), 0) AS balance
      FROM journal_lines jl
      LEFT JOIN journal_entries je ON je.id = jl.journal_id
      WHERE jl.${columnName} = ?
    `;
    const params = [numericId];
    if (normalizedBranchId) {
      sql += ' AND (je.id IS NULL OR COALESCE(je.branch_id, ?) = ?)';
      params.push(getDefaultMainBranchIdSync(), normalizedBranchId);
    }
    const excludedId = Number(excludeJournalId || 0);
    if (Number.isFinite(excludedId) && excludedId > 0) {
      sql += ' AND (jl.journal_id IS NULL OR jl.journal_id != ?)';
      params.push(excludedId);
    }
    const row = await tursoSync.queryOne(sql, params);
    return Number(row?.balance || 0) || 0;
  } catch (_) {
    return 0;
  }
}

function getInactiveEntityType(tableName) {
  const normalizedTableName = String(tableName || '').trim().toLowerCase();
  if (normalizedTableName === 'customers' || normalizedTableName === 'customer') return 'customer';
  if (normalizedTableName === 'suppliers' || normalizedTableName === 'supplier') return 'supplier';
  return 'account';
}

async function buildInactiveEntityDetails(tableName, row, fallbackId, options = {}) {
  const entityType = getInactiveEntityType(tableName);
  const entityName = row?.name || options?.entityName || null;
  return {
    entityType,
    id: Number(row?.id) || Number(fallbackId) || 0,
    entityName,
    name: entityName,
    label: options?.label || null,
  };
}

async function checkInactiveReferences(references = []) {
  const seen = new Set();

  for (const reference of Array.isArray(references) ? references : []) {
    const normalizedTable = String(reference?.table || '').trim().toLowerCase();
    const entityId = Number(reference?.id || 0);
    if (!Number.isFinite(entityId) || entityId <= 0) continue;

    let tableName = normalizedTable;
    if (tableName === 'customer') tableName = 'customers';
    else if (tableName === 'supplier') tableName = 'suppliers';
    else if (tableName === 'account') tableName = 'accounts';
    if (!['customers', 'suppliers', 'accounts'].includes(tableName)) continue;

    const referenceKey = `${tableName}:${entityId}`;
    if (seen.has(referenceKey)) continue;
    seen.add(referenceKey);

    const row = await tursoSync.queryOne(`SELECT id, name, active FROM ${tableName} WHERE id = ? LIMIT 1`, [entityId]);
    if (!row) continue;
    if (row.active !== null && row.active !== undefined && Number(row.active) === 0) {
      const entityType = getInactiveEntityType(tableName);
      const entityLabel = reference?.label
        || (entityType === 'customer' ? 'العميل' : entityType === 'supplier' ? 'المورد' : 'الحساب');
      return {
        allowed: false,
        error: `${entityLabel} غير نشط`,
        details: await buildInactiveEntityDetails(tableName, row, entityId, { label: entityLabel }),
      };
    }
  }

  return { allowed: true };
}

async function checkInactiveEntity(payload = {}) {
  return checkInactiveReferences([
    { id: payload?.customer_id, table: 'customers', label: 'العميل' },
    { id: payload?.supplier_id, table: 'suppliers', label: 'المورد' },
    { id: payload?.account_id, table: 'accounts', label: 'الحساب' },
  ]);
}

async function ensurePartyEntityBelongsToBranch(table, entityId, label, branchId) {
  const mainBranchId = getDefaultMainBranchIdSync();
  const partyScope = table === 'suppliers' ? 'supplier' : 'customer';
  const accessInfo = await getPartyBranchAccessInfo(partyScope, entityId);
  if (!accessInfo) {
    return {
      allowed: false,
      error: `${label} غير موجود`,
      details: {
        entityType: table,
        id: entityId,
        name: null,
      }
    };
  }

  if (partyAccessAllowsBranch(accessInfo, branchId)) {
    return { allowed: true };
  }

  return {
    allowed: false,
    error: `${label} لا يتبع الفرع الحالي`,
    details: {
      entityType: table,
      id: Number(accessInfo?.id) || entityId,
      name: accessInfo?.name || null,
      branchId: normalizePositiveId(accessInfo?.branch_id, mainBranchId) || mainBranchId,
      accessScope: normalizePartyAccessScope(accessInfo?.access_scope, 'single'),
      branchIds: normalizeBranchIdList(accessInfo?.assigned_branch_ids),
    }
  };
}

async function ensurePayloadEntitiesBelongToBranch(payload = {}, branchId) {
  const mainBranchId = getDefaultMainBranchIdSync();
  const normalizedBranchId = normalizePositiveId(branchId, mainBranchId) || mainBranchId;
  const checks = [
    { id: payload?.customer_id, table: 'customers', label: 'العميل' },
    { id: payload?.supplier_id, table: 'suppliers', label: 'المورد' },
  ];

  for (const item of checks) {
    const entityId = Number(item?.id || 0);
    if (!entityId) continue;

    const result = await ensurePartyEntityBelongsToBranch(item.table, entityId, item.label, normalizedBranchId);
    if (!result?.allowed) {
      return result;
    }
  }

  return { allowed: true };
}

async function ensureEntityReferencesBelongToBranch(references = [], branchId) {
  const mainBranchId = getDefaultMainBranchIdSync();
  const normalizedBranchId = normalizePositiveId(branchId, mainBranchId) || mainBranchId;
  const seen = new Set();

  for (const reference of Array.isArray(references) ? references : []) {
    const table = String(reference?.table || '').trim();
    const entityId = Number(reference?.id || 0);
    const label = reference?.label || 'السجل';
    if (!table || !entityId) continue;

    const referenceKey = `${table}:${entityId}`;
    if (seen.has(referenceKey)) continue;
    seen.add(referenceKey);

    if (table === 'accounts') {
      const row = await tursoSync.queryOne('SELECT id, name, branch_id, is_system, is_parent FROM accounts WHERE id = ? LIMIT 1', [entityId]);
      if (!row) {
        return {
          allowed: false,
          error: `${label} غير موجود`,
          details: {
            entityType: table,
            id: entityId,
            name: null,
          }
        };
      }
      const normalizedAccount = normalizeAccountRecord(row);
      if (Number(normalizedAccount?.is_shared_across_branches || 0) === 1) {
        continue;
      }
      const entityBranchId = normalizePositiveId(normalizedAccount?.branch_id, mainBranchId) || mainBranchId;
      if (entityBranchId !== normalizedBranchId) {
        return {
          allowed: false,
          error: `${label} لا يتبع الفرع الحالي`,
          details: {
            entityType: table,
            id: Number(normalizedAccount?.id) || entityId,
            name: normalizedAccount?.name || null,
            branchId: entityBranchId,
          }
        };
      }
      continue;
    }

    if (table !== 'customers' && table !== 'suppliers') {
      continue;
    }

    const result = await ensurePartyEntityBelongsToBranch(table, entityId, label, normalizedBranchId);
    if (!result?.allowed) {
      return result;
    }
  }

  return { allowed: true };
}

function collectTransactionBranchScopedReferences(payload = {}, lines = []) {
  const references = [
    { id: payload?.cash_account_id, table: 'accounts', label: 'حساب صندوق النقد' },
    { id: payload?.gold_account_id, table: 'accounts', label: 'حساب صندوق الذهب' },
    { id: payload?.silver_account_id, table: 'accounts', label: 'حساب صندوق الفضة' },
  ];

  for (const line of Array.isArray(lines) ? lines : []) {
    references.push(
      { id: line?.customer_id, table: 'customers', label: 'العميل' },
      { id: line?.supplier_id, table: 'suppliers', label: 'المورد' },
      { id: line?.account_id, table: 'accounts', label: 'الحساب' },
    );
  }

  return references;
}

async function checkNoParentAccounts(accountIds = []) {
  const ids = [...new Set((Array.isArray(accountIds) ? accountIds : [accountIds])
    .map((value) => Number(value || 0))
    .filter((value) => Number.isFinite(value) && value > 0))];

  for (const accountId of ids) {
    const account = await tursoSync.queryOne('SELECT id, name, is_parent FROM accounts WHERE id = ? LIMIT 1', [accountId]);
    if (!account) continue;
    if (Number(account.is_parent || 0) === 1) {
      return {
        allowed: false,
        error: 'لا يمكن التسجيل على حساب رئيسي',
        details: {
          accountId: Number(account.id) || accountId,
          name: account.name || null,
        }
      };
    }
  }

  return { allowed: true };
}

function normalizeDebtLimitAmount(value) {
  const numericValue = Number(value || 0);
  if (!Number.isFinite(numericValue)) return 0;
  const roundedValue = Math.round(numericValue * 100) / 100;
  return Math.abs(roundedValue) < 0.005 ? 0 : roundedValue;
}

async function checkDebtLimit(payload = {}) {
  const debitAmount = normalizeDebtLimitAmount(payload?.debit_amount || 0);
  const creditAmount = normalizeDebtLimitAmount(payload?.credit_amount || 0);
  const excludeJournalId = Number(payload?.exclude_journal_id || 0) || null;
  const branchId = normalizePositiveId(payload?.branch_id ?? payload?.branchId, null);
  const targets = [
    { id: payload?.customer_id, table: 'customers', column: 'customer_id', label: 'العميل' },
    { id: payload?.supplier_id, table: 'suppliers', column: 'supplier_id', label: 'المورد' },
    { id: payload?.account_id, table: 'accounts', column: 'account_id', label: 'الحساب' },
  ];

  for (const target of targets) {
    const numericId = Number(target.id || 0);
    if (!Number.isFinite(numericId) || numericId <= 0) continue;

    const row = await tursoSync.queryOne(`SELECT id, name, debt_limit FROM ${target.table} WHERE id = ? LIMIT 1`, [numericId]);
    if (!row) continue;
    const debtLimit = normalizeDebtLimitAmount(row.debt_limit || 0);
    if (!(debtLimit > 0)) continue;

    const currentBalance = normalizeDebtLimitAmount(await getEntityCashExposureForLimit(target.column, row.id, excludeJournalId, branchId));
    const projectedBalance = normalizeDebtLimitAmount(currentBalance + debitAmount - creditAmount);
    if (projectedBalance > debtLimit) {
      const entityName = row.name || null;
      const excess = normalizeDebtLimitAmount(projectedBalance - debtLimit);
      return {
        allowed: false,
        error: `تجاوز سقف المديونية ${target.label}`,
        details: {
          entityType: getInactiveEntityType(target.table),
          id: Number(row.id) || Number(target.id) || 0,
          entityName,
          name: entityName,
          currentBalance,
          projectedBalance,
          newBalance: projectedBalance,
          debtLimit,
          excess,
        }
      };
    }
  }

  return { allowed: true };
}

function getDebtLimitEntityKey(payload = {}) {
  return `c${payload?.customer_id || 0}_s${payload?.supplier_id || 0}_a${payload?.account_id || 0}`;
}

function addDebtLimitAmountEntry(amountsByEntity, payload = {}, debitAmount = 0, creditAmount = 0) {
  const debit = Number(debitAmount || 0) || 0;
  const credit = Number(creditAmount || 0) || 0;
  if (!(debit > 0 || credit > 0)) return;

  const key = getDebtLimitEntityKey(payload);
  if (!amountsByEntity.has(key)) {
    amountsByEntity.set(key, {
      customer_id: payload?.customer_id || null,
      supplier_id: payload?.supplier_id || null,
      account_id: payload?.account_id || null,
      totalDebit: 0,
      totalCredit: 0,
    });
  }

  const entity = amountsByEntity.get(key);
  entity.totalDebit += debit;
  entity.totalCredit += credit;
}

function collectDebtLimitAmountsFromOpeningLines(lines = []) {
  const amountsByEntity = new Map();

  for (const line of Array.isArray(lines) ? lines : []) {
    const amount = Number(line?.amount || 0) || 0;
    if (amount > 0) {
      addDebtLimitAmountEntry(amountsByEntity, line, amount, 0);
    } else if (amount < 0) {
      addDebtLimitAmountEntry(amountsByEntity, line, 0, Math.abs(amount));
    }
  }

  return amountsByEntity;
}

function summarizeInvoiceDebtLimitValues(details = []) {
  let totalValue = 0;
  let totalLaborValue = 0;
  let totalTax = 0;

  for (const detail of Array.isArray(details) ? details : []) {
    const weight = Number(detail?.weight) || 0;
    const labor = Number(detail?.labor) || 0;
    totalValue += Number(detail?.value) || 0;
    totalLaborValue += weight * labor;
    totalTax += Number(detail?.tax) || 0;
  }

  return {
    totalValue,
    laborPlusTax: totalLaborValue + totalTax,
  };
}

function collectDebtLimitAmountsFromInvoicePayload(payload = {}, direction = 'sales') {
  const amountsByEntity = new Map();
  const paymentType = String(payload?.payment_type || payload?.paymentType || 'cash').trim().toLowerCase();
  if (paymentType === 'cash') {
    return amountsByEntity;
  }

  const invoiceType = String(payload?.invoice_type || payload?.invoiceType || 'taskir').trim().toLowerCase();
  const { totalValue, laborPlusTax } = summarizeInvoiceDebtLimitValues(payload?.details);
  const cashAmount = invoiceType === 'taskir' ? totalValue : laborPlusTax;
  if (!(cashAmount > 0)) {
    return amountsByEntity;
  }

  if (String(direction || '').trim().toLowerCase() === 'purchase') {
    addDebtLimitAmountEntry(amountsByEntity, payload, 0, cashAmount);
  } else {
    addDebtLimitAmountEntry(amountsByEntity, payload, cashAmount, 0);
  }

  return amountsByEntity;
}

async function findDebtLimitFailureForAmounts(amountsByEntity = new Map(), options = {}) {
  for (const entity of amountsByEntity.values()) {
    const check = await checkDebtLimit({
      customer_id: entity?.customer_id,
      supplier_id: entity?.supplier_id,
      account_id: entity?.account_id,
      debit_amount: entity?.totalDebit,
      credit_amount: entity?.totalCredit,
      exclude_journal_id: options?.excludeJournalId,
      branch_id: options?.branchId,
    });

    if (!check.allowed) {
      return check;
    }
  }

  return { allowed: true };
}

async function findDebtLimitFailureForNetAmounts(oldAmountsByEntity = new Map(), newAmountsByEntity = new Map(), options = {}) {
  const keys = new Set([...oldAmountsByEntity.keys(), ...newAmountsByEntity.keys()]);

  for (const key of keys) {
    const oldEntity = oldAmountsByEntity.get(key) || { customer_id: null, supplier_id: null, account_id: null, totalDebit: 0, totalCredit: 0 };
    const newEntity = newAmountsByEntity.get(key) || { customer_id: null, supplier_id: null, account_id: null, totalDebit: 0, totalCredit: 0 };
    const entity = (newEntity?.customer_id || newEntity?.supplier_id || newEntity?.account_id) ? newEntity : oldEntity;
    const oldNet = (Number(oldEntity?.totalDebit || 0) || 0) - (Number(oldEntity?.totalCredit || 0) || 0);
    const newNet = (Number(newEntity?.totalDebit || 0) || 0) - (Number(newEntity?.totalCredit || 0) || 0);
    const netChange = newNet - oldNet;
    if (Math.abs(netChange) <= 0.0001) continue;

    const check = await checkDebtLimit({
      customer_id: entity?.customer_id,
      supplier_id: entity?.supplier_id,
      account_id: entity?.account_id,
      debit_amount: netChange > 0 ? netChange : 0,
      credit_amount: netChange < 0 ? Math.abs(netChange) : 0,
      branch_id: options?.branchId,
    });

    if (!check.allowed) {
      return check;
    }
  }

  return { allowed: true };
}

// Helper to get account ID by code
function getAccountIdByCode(code) {
  const value = String(code || '').trim();
  if (!value) return null;

  try {
    const cached = tursoSync.getCache('accounts');
    if (Array.isArray(cached) && cached.length) {
      const cachedMatch = cached.find((account) => String(account?.code || '').trim() === value);
      if (cachedMatch?.id) {
        return Number(cachedMatch.id) || null;
      }
    }
  } catch (_) {}

  try {
    const acc = db.prepare('SELECT id FROM accounts WHERE code = ?').get(value);
    return acc ? (Number(acc.id) || null) : null;
  } catch (_) {
    return null;
  }
}

async function getAccountIdByCodeAsync(code) {
  const value = String(code || '').trim();
  if (!value) return null;

  try {
    const cached = tursoSync.getCache('accounts');
    if (Array.isArray(cached) && cached.length) {
      const cachedMatch = cached.find((account) => String(account?.code || '').trim() === value);
      if (cachedMatch?.id) {
        return Number(cachedMatch.id) || null;
      }
    }
  } catch (_) {}

  try {
    const acc = await tursoSync.queryOne('SELECT id FROM accounts WHERE code = ? LIMIT 1', [value]);
    return acc ? (Number(acc.id) || null) : null;
  } catch (_) {
    return null;
  }
}

const DEFAULT_BOX_FALLBACK_CODES = {
  cash: '1111',
  gold: '11211',
  worked_gold: '11221',
  silver: '11231',
  diamond: '11241',
};

function doesAccountMatchDefaultBoxType(code, boxType) {
  const normalizedCode = String(code || '').trim();
  if (!normalizedCode) return false;
  if (boxType === 'cash') return normalizedCode.startsWith('111') && normalizedCode.length > 3;
  if (boxType === 'gold') return normalizedCode.startsWith('1121') && normalizedCode.length > 4;
  if (boxType === 'worked_gold') return normalizedCode.startsWith('1122') && normalizedCode.length > 4;
  if (boxType === 'silver') return normalizedCode.startsWith('1123') && normalizedCode.length > 4;
  if (boxType === 'diamond') return normalizedCode.startsWith('1124') && normalizedCode.length > 4;
  return false;
}

async function resolveDefaultBoxAccountId(branchId, boxType) {
  const normalizedBranchId = normalizePositiveId(branchId, getDefaultMainBranchIdSync()) || getDefaultMainBranchIdSync();
  const normalizedBoxType = String(boxType || '').trim().toLowerCase();
  const fallbackCode = DEFAULT_BOX_FALLBACK_CODES[normalizedBoxType] || null;

  try {
    await ensureDefaultBoxesTableReady();
    const row = await tursoSync.queryOne(`
      SELECT db.account_id, a.code, a.is_parent
      FROM default_boxes db
      LEFT JOIN accounts a ON a.id = db.account_id
      WHERE db.branch_id = ? AND db.box_type = ?
      LIMIT 1
    `, [normalizedBranchId, normalizedBoxType]);
    const accountId = Number(row?.account_id || 0) || null;
    if (accountId && Number(row?.is_parent || 0) !== 1 && doesAccountMatchDefaultBoxType(row?.code, normalizedBoxType)) {
      return accountId;
    }
  } catch (_) {}

  return fallbackCode ? await getAccountIdByCodeAsync(fallbackCode) : null;
}

// ===== Movement handlers =====

function normalizeMovementGoldBasis(payload = {}) {
  const value = Number(payload?.goldBasis || payload?.goldBaseKarat || 24);
  return Number.isFinite(value) && value > 0 ? value : 24;
}

function normalizeMovementSilverBasis(payload = {}) {
  const value = Number(payload?.silverBasis || payload?.silverBaseKarat || 999);
  return Number.isFinite(value) && value > 0 ? value : 999;
}

function buildMovementDateConditions(alias, payload = {}) {
  const conditions = [];
  const params = [];
  const scopeArg = arguments[2];
  const mainBranchId = normalizePositiveId(arguments[3], getDefaultMainBranchIdSync()) || getDefaultMainBranchIdSync();
  const scopeInfo = scopeArg && typeof scopeArg === 'object' && (scopeArg.branchId !== undefined || scopeArg.isAllBranches !== undefined)
    ? scopeArg
    : { branchId: normalizePositiveId(scopeArg, mainBranchId) || mainBranchId, allowedBranchIds: normalizeBranchIdList([scopeArg]), isAllBranches: false };
  const branchFilter = buildCoalescedBranchWhereClause(`${alias}.branch_id`, getEffectiveBranchIdsForScope(scopeInfo, mainBranchId), mainBranchId);
  conditions.push(branchFilter.sql);
  params.push(...branchFilter.params);
  const dateFrom = String(payload?.dateFrom || payload?.from || '').trim();
  const dateTo = String(payload?.dateTo || payload?.to || '').trim();

  if (dateFrom) {
    conditions.push(`${alias}.date >= ?`);
    params.push(dateFrom);
  }
  if (dateTo) {
    conditions.push(`${alias}.date <= ?`);
    params.push(dateTo);
  }

  return { conditions, params };
}

function buildMovementGoldWeightSum(alias, goldBasis) {
  return `COALESCE(SUM(CASE WHEN CAST(COALESCE(NULLIF(TRIM(${alias}.karat),''), '0') AS INTEGER) IN (999,925,900,800) THEN 0 ELSE COALESCE(${alias}.weight, 0) * (CAST(COALESCE(NULLIF(TRIM(${alias}.karat),''), '21') AS REAL) / ${goldBasis}) END), 0)`;
}

function buildMovementSilverWeightSum(alias, silverBasis) {
  return `COALESCE(SUM(CASE WHEN CAST(COALESCE(NULLIF(TRIM(${alias}.karat),''), '0') AS INTEGER) IN (999,925,900,800) THEN COALESCE(${alias}.weight, 0) * (CAST(COALESCE(NULLIF(TRIM(${alias}.karat),''), '999') AS REAL) / ${silverBasis}) ELSE 0 END), 0)`;
}

function buildMovementKaratDisplay(alias) {
  return `CASE
    WHEN COUNT(DISTINCT NULLIF(TRIM(${alias}.karat), '')) = 0 THEN ''
    WHEN COUNT(DISTINCT NULLIF(TRIM(${alias}.karat), '')) = 1 THEN MAX(NULLIF(TRIM(${alias}.karat), ''))
    ELSE REPLACE(GROUP_CONCAT(DISTINCT NULLIF(TRIM(${alias}.karat), '')), ',', ' / ')
  END`;
}

function buildMovementJournalGoldSum(alias, valueField, goldBasis) {
  return `COALESCE(SUM(CASE WHEN (COALESCE(${alias}.currency_type, '') LIKE '%ذهب%' OR COALESCE(${alias}.currency_type, '') LIKE '%gold%') AND CAST(COALESCE(NULLIF(TRIM(${alias}.karat),''), '0') AS INTEGER) NOT IN (999,925,900,800) THEN COALESCE(${alias}.${valueField}, 0) * (CAST(COALESCE(NULLIF(TRIM(${alias}.karat),''), '21') AS REAL) / ${goldBasis}) ELSE 0 END), 0)`;
}

function buildMovementJournalSilverSum(alias, valueField, silverBasis) {
  return `COALESCE(SUM(CASE WHEN ((COALESCE(${alias}.currency_type, '') LIKE '%فضة%' OR COALESCE(${alias}.currency_type, '') LIKE '%silver%') OR CAST(COALESCE(NULLIF(TRIM(${alias}.karat),''), '0') AS INTEGER) IN (999,925,900,800)) THEN COALESCE(${alias}.${valueField}, 0) * (CAST(COALESCE(NULLIF(TRIM(${alias}.karat),''), '999') AS REAL) / ${silverBasis}) ELSE 0 END), 0)`;
}

try { ipcMain.removeHandler('movement-get-entity-name'); } catch (_) {}
ipcMain.handle('movement-get-entity-name', async (event, payload = {}) => {
  try {
    const type = String(payload?.type || '').trim().toLowerCase();
    const id = Number(payload?.id || 0) || 0;
    const mainBranchId = getDefaultMainBranchIdSync();
    const branchId = await resolveBranchIdForRequest(event, payload, mainBranchId);
    if (!id) {
      return { success: true, name: null };
    }

    let tableName = null;
    if (type === 'customer') tableName = 'customers';
    else if (type === 'supplier') tableName = 'suppliers';
    else if (type === 'account') tableName = 'accounts';

    if (!tableName) {
      return { success: false, error: 'نوع غير مدعوم' };
    }

    const row = tableName === 'accounts'
      ? await tursoSync.queryOne('SELECT name FROM accounts WHERE id = ? AND (COALESCE(is_system, 0) = 1 OR branch_id IS NULL OR branch_id = ?) LIMIT 1', [id, branchId])
      : await tursoSync.queryOne(`SELECT name FROM ${tableName} WHERE id = ? AND COALESCE(branch_id, ?) = ? LIMIT 1`, [id, mainBranchId, branchId]);
    return { success: true, name: row?.name || null };
  } catch (error) {
    return { success: false, error: error.message };
  }
});

try { ipcMain.removeHandler('movement-sales-summary'); } catch (_) {}
ipcMain.handle('movement-sales-summary', async (event, payload = {}) => {
  try {
    const goldBasis = normalizeMovementGoldBasis(payload);
    const silverBasis = normalizeMovementSilverBasis(payload);
    const mainBranchId = getDefaultMainBranchIdSync();
    const scopeInfo = await resolveBranchScopeForRequest(event, payload, mainBranchId);
    const { conditions, params } = buildMovementDateConditions('si', payload, scopeInfo, mainBranchId);
    const whereClause = conditions.length ? `WHERE ${conditions.join(' AND ')}` : '';
    const goldTotalExpr = buildMovementGoldWeightSum('sid', goldBasis);
    const silverTotalExpr = buildMovementSilverWeightSum('sid', silverBasis);
    const karatDisplayExpr = buildMovementKaratDisplay('sid');

    const rows = await tursoSync.queryAll(`
      SELECT
        si.id,
        si.branch_local_number,
        si.date,
        COALESCE(si.branch_id, ${mainBranchId}) AS branch_id,
        COALESCE((SELECT name FROM branches branch_lookup WHERE branch_lookup.id = COALESCE(si.branch_id, ${mainBranchId}) LIMIT 1), '') AS branch_name,
        COALESCE((SELECT code FROM branches branch_lookup WHERE branch_lookup.id = COALESCE(si.branch_id, ${mainBranchId}) LIMIT 1), '') AS branch_code,
        si.customer_id,
        COALESCE(c.name, s.name, si.customer_name, '') AS customer_name,
        COALESCE(si.description, '') AS description,
        ${karatDisplayExpr} AS karat,
        COUNT(sid.id) AS line_count,
        ROUND(COALESCE(SUM(COALESCE(sid.value, 0)), 0), 2) AS cash_total,
        ROUND(${goldTotalExpr}, 3) AS gold_total,
        ROUND(${silverTotalExpr}, 3) AS silver_total
      FROM sales_invoices si
      LEFT JOIN sales_invoice_details sid ON sid.invoice_id = si.id
      LEFT JOIN customers c ON c.id = si.customer_id
      LEFT JOIN suppliers s ON s.id = si.supplier_id
      ${whereClause}
      GROUP BY si.id, si.branch_local_number, si.date, si.customer_id, COALESCE(c.name, s.name, si.customer_name, ''), si.description
      ORDER BY si.date DESC, COALESCE(si.branch_local_number, si.id) DESC, si.id DESC
    `, params);
    return { success: true, data: rows };
  } catch (error) {
    return { success: false, error: error.message };
  }
});

