    const whereClause = `WHERE ${( ['(je.is_auto = 0 OR je.is_auto IS NULL)', ...conditions] ).join(' AND ')}`;
    const goldDebitExpr = buildMovementJournalGoldSum('jl', 'debit', goldBasis);
    const goldCreditExpr = buildMovementJournalGoldSum('jl', 'credit', goldBasis);
    const silverDebitExpr = buildMovementJournalSilverSum('jl', 'debit', silverBasis);
