// Add order
ipcMain.handle('orders-add', async (event, payload) => {
  try {
    const {
      customer_id, supplier_id, customer_name, created_date,
      completion_date, operation_type, karat, weight, ounce,
      addition, dollar_price, price_per_gram, execution_date, 
      execution_time, execute_on_mt5, status, notes, created_by
    } = payload;
    
    if (!created_date || !operation_type) {
      return { success: false, error: 'بيانات غير صالحة: التاريخ ونوع العملية مطلوبان' };
    }
    const branchId = await resolveBranchIdForRequest(event, payload, getDefaultMainBranchIdSync());
    const branchWriteAccess = await ensureAuthenticatedUserCanMutateBranch(event, branchId);
    if (!branchWriteAccess.allowed) {
      return branchWriteAccess.response;
    }
    const branchEntityCheck = await ensurePayloadEntitiesBelongToBranch({ customer_id, supplier_id }, branchId);
    if (!branchEntityCheck.allowed) {
      return { success: false, error: branchEntityCheck.error, branchMismatch: true, details: branchEntityCheck.details };
    }
    
    const createdAt = getLocalDateTime();
    const requestedBranchLocalNumber = normalizePositiveId(
      payload?.branch_local_number ?? payload?.branchLocalNumber ?? payload?.id,
      null
    );
    const branchLocalNumber = await resolveBranchLocalNumberForInsert('orders', branchId, requestedBranchLocalNumber);
    let nextOrderId = 1;
    const existingOrderIds = await tursoSync.queryAll('SELECT id FROM orders ORDER BY id');
    for (const row of existingOrderIds) {
      const currentId = Number(row?.id || 0);
      if (currentId === nextOrderId) {
        nextOrderId++;
      } else if (currentId > nextOrderId) {
        break;
      }
    }
    
    // Reset auto-increment if table is empty before inserting (local mode only)
    if (!tursoSync.isCloudMode()) {
      const count = db.prepare('SELECT COUNT(*) as cnt FROM orders').get();
      if (count && count.cnt === 0) {
        try {
          db.prepare("DELETE FROM sqlite_sequence WHERE name = 'orders'").run();
        } catch (_) {}
      }
    }
    
    const result = await tursoSync.run(`
      INSERT INTO orders (
        id,
        customer_id, supplier_id, customer_name, created_date,
        completion_date, operation_type, karat, weight, ounce,
        addition, dollar_price, price_per_gram, execution_date, 
        execution_time, execute_on_mt5, status, notes, created_by, created_at, branch_id, branch_local_number
      ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
    `, [
      nextOrderId,
      customer_id || null,
      supplier_id || null,
      customer_name || null,
      created_date,
      completion_date || null,
      operation_type,
      karat || null,
      Number(weight) || 0,
      Number(ounce) || 0,
      Number(addition) || 0,
      Number(dollar_price) || 0,
      Number(price_per_gram) || 0,
      execution_date || null,
      execution_time || null,
      Number(execute_on_mt5) ? 1 : 0,
      status || 'pending',
      notes || null,
      created_by || null,
      createdAt,
      branchId,
      branchLocalNumber
    ]);

    const id = Number(nextOrderId || result.lastInsertRowid || 0);
    const wantsMt5 = Number(execute_on_mt5) ? 1 : 0;

    if (wantsMt5 && Number.isFinite(Number(id)) && Number(id) > 0) {
      try {
        if (!mt5Proc || !mt5Proc.stdin || !mt5Proc.stdin.writable) {
          const msg = 'MT5 bridge not running';
          await tursoSync.run('UPDATE orders SET status = ?, mt5_error = ? WHERE id = ? AND COALESCE(branch_id, ?) = ?', ['pending', msg, id, getDefaultMainBranchIdSync(), branchId]);
        } else {
          const op = String(operation_type || '').toUpperCase();
          const side = op === 'SELL' ? 'sell' : 'buy';

          const w = Number(weight);
          let lots = 0;
          if (Number.isFinite(w) && w > 0) {
            lots = (w / 31.1034768) / 100;
          }
          if (!Number.isFinite(lots) || lots <= 0) lots = 0.01;
          lots = Math.max(0.01, lots);
          lots = Math.round(lots / 0.01) * 0.01;

          const symbol = 'XAUUSDm';
          const deviation = 20;
          const comment = String(`order_${id}`);
          const price = Number(ounce) || 0;

          const res = await sendMt5BridgeCommand({
            cmd: 'trade',
            kind: 'limit',
            symbol,
            side,
            volume: lots,
            price,
            deviation,
            magic: 0,
            comment,
          }, 20000);

          const orderTicket = (res && res.order != null) ? String(res.order) : null;
          const dealTicket = (res && res.deal != null && Number(res.deal) > 0) ? String(res.deal) : null;

          await tursoSync.run(`UPDATE orders SET
            status = ?,
            mt5_order_ticket = ?,
            mt5_deal_ticket = ?,
            mt5_symbol = ?,
            mt5_volume = ?,
            mt5_price = ?,
            mt5_retcode = ?,
            mt5_error = NULL
            WHERE id = ?
          `, [
            'pending',
            orderTicket,
            dealTicket,
            res && res.symbol ? String(res.symbol) : String(symbol),
            Number(res && res.volume != null ? res.volume : lots) || lots,
            (res && res.price != null) ? Number(res.price) : price,
            res && res.retcode != null ? Number(res.retcode) : null,
            id
          ]);
        }
      } catch (error) {
        const msg = error?.message || String(error);
        const isTradeFail = error && Object.prototype.hasOwnProperty.call(error, 'data');
        const nextStatus = isTradeFail ? 'failed' : 'pending';
        try {
          await tursoSync.run('UPDATE orders SET status = ?, mt5_error = ? WHERE id = ? AND COALESCE(branch_id, ?) = ?', [nextStatus, msg, id, getDefaultMainBranchIdSync(), branchId]);
        } catch (_) {}
      }
    }

    return { success: true, id, branch_local_number: branchLocalNumber };
  } catch (error) {
    return { success: false, error: error.message };
  }
});

// Update order
ipcMain.handle('orders-update', async (event, payload) => {
  try {
    const {
      id, customer_id, supplier_id, customer_name, created_date,
      completion_date, operation_type, karat, weight, ounce,
      addition, dollar_price, price_per_gram, execution_date, 
      execution_time, execute_on_mt5, status, notes, modified_by
    } = payload;
    
    if (!id || !created_date || !operation_type) {
      return { success: false, error: 'بيانات غير صالحة' };
    }
    const branchId = await resolveBranchIdForRequest(event, payload, getDefaultMainBranchIdSync());
    const branchWriteAccess = await ensureAuthenticatedUserCanMutateBranch(event, branchId);
    if (!branchWriteAccess.allowed) {
      return branchWriteAccess.response;
    }
    const existingOrder = await tursoSync.queryOne('SELECT id, branch_id, branch_local_number FROM orders WHERE id = ?', [id]);
    if (!existingOrder) {
      return { success: false, error: 'الأوردر غير موجود' };
    }
    const existingBranchId = normalizePositiveId(existingOrder?.branch_id, getDefaultMainBranchIdSync()) || getDefaultMainBranchIdSync();
    if (existingBranchId !== branchId) {
      return { success: false, error: 'الأوردر لا يتبع الفرع الحالي' };
    }
    const orderDisplayNumber = normalizePositiveId(existingOrder?.branch_local_number, null)
      || normalizePositiveId(payload?.branch_local_number ?? payload?.branchLocalNumber, null)
      || id;
    const branchEntityCheck = await ensurePayloadEntitiesBelongToBranch({ customer_id, supplier_id }, branchId);
    if (!branchEntityCheck.allowed) {
      return { success: false, error: branchEntityCheck.error, branchMismatch: true, details: branchEntityCheck.details };
    }
    
    const modifiedAt = getLocalDateTime();
    
    await tursoSync.run(`
      UPDATE orders SET
        customer_id = ?, supplier_id = ?, customer_name = ?, created_date = ?,
        completion_date = ?, operation_type = ?, karat = ?, weight = ?, ounce = ?,
        addition = ?, dollar_price = ?, price_per_gram = ?, execution_date = ?, 
        execution_time = ?, execute_on_mt5 = ?, status = ?, notes = ?, modified_by = ?, modified_at = ?, branch_id = ?
      WHERE id = ?
    `, [
      customer_id || null,
      supplier_id || null,
      customer_name || null,
      created_date,
      completion_date || null,
      operation_type,
      karat || null,
      Number(weight) || 0,
      Number(ounce) || 0,
      Number(addition) || 0,
      Number(dollar_price) || 0,
      Number(price_per_gram) || 0,
      execution_date || null,
      execution_time || null,
      Number(execute_on_mt5) ? 1 : 0,
      status || 'pending',
      notes || null,
      modified_by || null,
      modifiedAt,
      branchId,
      id
    ]);

    const wantsMt5 = Number(execute_on_mt5) ? 1 : 0;
    if (wantsMt5) {
      try {
        const order = await tursoSync.queryOne('SELECT * FROM orders WHERE id = ? AND COALESCE(branch_id, ?) = ?', [id, getDefaultMainBranchIdSync(), branchId]);
        const isCompleted = order && String(order.status || '').toLowerCase() === 'completed';
        const hasTicket = order && (order.mt5_deal_ticket || order.mt5_order_ticket);

        if (order && !isCompleted && !hasTicket) {
          if (!mt5Proc || !mt5Proc.stdin || !mt5Proc.stdin.writable) {
            const msg = 'MT5 bridge not running';
            await tursoSync.run('UPDATE orders SET status = ?, mt5_error = ? WHERE id = ? AND COALESCE(branch_id, ?) = ?', ['pending', msg, id, getDefaultMainBranchIdSync(), branchId]);
          } else {
            const op = String(order.operation_type || '').toUpperCase();
            const side = op === 'SELL' ? 'sell' : 'buy';

            const w = Number(order.weight);
            let lots = 0;
            if (Number.isFinite(w) && w > 0) {
              lots = (w / 31.1034768) / 100;
            }
            if (!Number.isFinite(lots) || lots <= 0) lots = 0.01;
            lots = Math.max(0.01, lots);
            lots = Math.round(lots / 0.01) * 0.01;

            const symbol = (order.mt5_symbol || 'XAUUSDm');
            const deviation = 20;
            const comment = String(`order_${id}`);
            const price = Number(order.ounce) || 0;

            const res = await sendMt5BridgeCommand({
              cmd: 'trade',
              kind: 'limit',
              symbol,
              side,
              volume: lots,
              price,
              deviation,
              magic: 0,
              comment,
            }, 20000);

            const orderTicket = (res && res.order != null) ? String(res.order) : null;
            const dealTicket = (res && res.deal != null && Number(res.deal) > 0) ? String(res.deal) : null;

            await tursoSync.run(`UPDATE orders SET
              status = ?,
              mt5_order_ticket = ?,
              mt5_deal_ticket = ?,
              mt5_symbol = ?,
              mt5_volume = ?,
              mt5_price = ?,
              mt5_retcode = ?,
              mt5_error = NULL
              WHERE id = ? AND COALESCE(branch_id, ?) = ?
            `, [
              'pending',
              orderTicket,
              dealTicket,
              res && res.symbol ? String(res.symbol) : String(symbol),
              Number(res && res.volume != null ? res.volume : lots) || lots,
              (res && res.price != null) ? Number(res.price) : price,
              res && res.retcode != null ? Number(res.retcode) : null,
              id,
              getDefaultMainBranchIdSync(),
              branchId
            ]);
          }
        }
      } catch (error) {
        const msg = error?.message || String(error);
        const isTradeFail = error && Object.prototype.hasOwnProperty.call(error, 'data');
        const nextStatus = isTradeFail ? 'failed' : 'pending';
        try {
          await tursoSync.run('UPDATE orders SET status = ?, mt5_error = ? WHERE id = ? AND COALESCE(branch_id, ?) = ?', [nextStatus, msg, id, getDefaultMainBranchIdSync(), branchId]);
        } catch (_) {}
      }
    }

    return { success: true, id, branch_local_number: orderDisplayNumber };
  } catch (error) {
    return { success: false, error: error.message };
  }
});

// Delete order
ipcMain.handle('orders-delete', async (event, id) => {
  try {
    const { id: orderId, payload: requestPayload } = parseDocumentRequestPayload(id);
    const branchId = await resolveBranchIdForRequest(event, requestPayload, getDefaultMainBranchIdSync());
    const branchWriteAccess = await ensureAuthenticatedUserCanMutateBranch(event, branchId);
    if (!branchWriteAccess.allowed) {
      return branchWriteAccess.response;
    }
    // Get order first to check if it has MT5 ticket
    const order = await tursoSync.queryOne('SELECT * FROM orders WHERE id = ?', [orderId]);
    if (!order) {
      return { success: false, error: 'الأوردر غير موجود' };
    }
    const orderBranchId = normalizePositiveId(order?.branch_id, getDefaultMainBranchIdSync()) || getDefaultMainBranchIdSync();
    if (orderBranchId !== branchId) {
      return { success: false, error: 'الأوردر لا يتبع الفرع الحالي' };
    }
    
    if (order && order.mt5_order_ticket && order.status === 'pending') {
      // Try to cancel the MT5 order first
      if (mt5Proc && mt5Proc.stdin && mt5Proc.stdin.writable) {
        try {
          await sendMt5BridgeCommand({
            cmd: 'cancel_order',
            ticket: order.mt5_order_ticket
          }, 15000);
        } catch (cancelErr) {
          // Log but continue with deletion - order might already be executed
          console.log('[MT5] Cancel order warning:', cancelErr?.message || cancelErr);
        }
      }
    }
    
    await tursoSync.run('DELETE FROM orders WHERE id = ?', [orderId]);
    
    // Reset auto-increment if table is empty (local mode only)
    if (!tursoSync.isCloudMode()) {
      const count = db.prepare('SELECT COUNT(*) as cnt FROM orders').get();
      if (count && count.cnt === 0) {
        try {
          db.prepare("DELETE FROM sqlite_sequence WHERE name = 'orders'").run();
        } catch (_) {}
      }
    }
    
    return { success: true };
  } catch (error) {
    return { success: false, error: error.message };
  }
});

