// Handle opening invoice window
ipcMain.handle('open-invoice-window', async (event, data) => {
  try {
    const { invoiceId, type } = data;
    const branchId = normalizePositiveId(data?.branchId || data?.branch_id || data?.selectedBranchId, null);
    const displayInvoiceId = normalizePositiveId(data?.displayInvoiceId ?? data?.invoiceDisplayId ?? data?.branch_local_number ?? data?.branchLocalNumber, null);
    
    // Determine which screen to open based on type
    let screenPath;
    let windowTitle;
    
    if (type === 'SELL') {
      screenPath = path.join(__dirname, 'screens/sales-invoice/index.html');
      windowTitle = `فاتورة بيع - ${displayInvoiceId || invoiceId}`;
    } else if (type === 'BUY') {
      screenPath = path.join(__dirname, 'screens/purchase-invoice/index.html');
      windowTitle = `فاتورة شراء - ${displayInvoiceId || invoiceId}`;
    } else {
      throw new Error('Invalid invoice type');
    }
    
    // Create new window for the invoice
    const invoiceWindow = new BrowserWindow({
      width: 1200,
      height: 800,
      title: windowTitle,
      webPreferences: {
        nodeIntegration: false,
        contextIsolation: true,
        preload: path.join(__dirname, 'preload.js')
      },
      parent: win,
      modal: false
    });
    
    // Hide menu bar
    invoiceWindow.setMenuBarVisibility(false);
    
    // Load the invoice screen with invoice ID as URL parameter
    const query = { id: String(invoiceId) };
    if (branchId) query.branchId = String(branchId);
    await invoiceWindow.loadFile(screenPath, {
      query
    });
    
    return { success: true };
  } catch (error) {
    return { success: false, error: error.message };
  }
});

// Handle opening document window (voucher, receipt, journal, etc.)
ipcMain.handle('open-document-window', async (event, data) => {
  try {
    const { documentId, type, parentWindow } = data;
    const branchId = normalizePositiveId(data?.branchId || data?.branch_id || data?.selectedBranchId, null);
    
    // Determine which screen to open based on type
    let screenPath;
    let windowTitle;
    
    if (type === 'voucher') {
      screenPath = path.join(__dirname, 'screens/voucher/index.html');
      windowTitle = `سند قيد - ${documentId}`;
    } else if (type === 'receipt') {
      screenPath = path.join(__dirname, 'screens/receipt/index.html');
      windowTitle = `سند قبض - ${documentId}`;
    } else if (type === 'sales_invoice') {
      screenPath = path.join(__dirname, 'screens/sales-invoice/index.html');
      windowTitle = `فاتورة بيع - ${documentId}`;
    } else if (type === 'purchase_invoice') {
      screenPath = path.join(__dirname, 'screens/purchase-invoice/index.html');
      windowTitle = `فاتورة شراء - ${documentId}`;
    } else if (type === 'opening') {
      screenPath = path.join(__dirname, 'screens/opening/index.html');
      windowTitle = `رصيد افتتاحي - ${documentId}`;
    } else if (type === 'journal') {
      screenPath = path.join(__dirname, 'screens/journal/index.html');
      windowTitle = `قيد يومية - ${documentId}`;
    } else {
      throw new Error('Invalid document type');
    }
    
    // Get the parent window (the window that called this)
    const callerWindow = parentWindow ? BrowserWindow.fromWebContents(event.sender) : win;
    
    // Create new window for the document
    const documentWindow = new BrowserWindow({
      width: 1200,
      height: 800,
      title: windowTitle,
      webPreferences: {
        nodeIntegration: false,
        contextIsolation: true,
        preload: path.join(__dirname, 'preload.js')
      },
      parent: callerWindow, // Set as child of the calling window
      modal: false
    });
    
    // Hide menu bar
    documentWindow.setMenuBarVisibility(false);
    
    // Load the document screen with document ID as URL parameter
    const query = { id: String(documentId) };
    if (branchId) query.branchId = String(branchId);
    await documentWindow.loadFile(screenPath, {
      query
    });
    
    return { success: true };
  } catch (error) {
    return { success: false, error: error.message };
  }
});

