// ===== كشف حساب إجمالي - استعلام مباشر وسريع =====
ipcMain.handle('get-all-entity-balances', async (event, payload = {}) => {
  try {
    const { scope, from, to, goldBasis, silverBasis, includeOpening, accountType, category } = payload || {};
    const gBase = parseInt(goldBasis) || 24;
    const sBase = parseInt(silverBasis) || 999;
    const fromDate = from || null;
    const toDate = to || null;
    const includeOpen = includeOpening ? 1 : 0;
    const mainBranchId = getDefaultMainBranchIdSync();
    const scopeInfo = await resolveBranchScopeForRequest(event, payload, mainBranchId);
    const branchIds = getEffectiveBranchIdsForScope(scopeInfo, mainBranchId);
    const journalBranchFilter = buildCoalescedBranchWhereClause('je.branch_id', branchIds, mainBranchId);
    
    // تحديد الجدول والحقول حسب النطاق
    let entityTable, entityIdField, entityNameField;
    if (scope === 'customers') {
      entityTable = 'customers';
      entityIdField = 'customer_id';
      entityNameField = 'name';
    } else if (scope === 'suppliers') {
      entityTable = 'suppliers';
      entityIdField = 'supplier_id';
      entityNameField = 'name';
    } else {
      entityTable = 'accounts';
      entityIdField = 'account_id';
      entityNameField = 'name';
    }
    
    // ========== استعلام واحد مباشر من القيود اليومية فقط (بما فيها الافتتاحي عبر source_type='opening') ==========
    const isAccountsScope = (scope === 'accounts');
    const accountEntityWhere = buildSystemOrBranchWhereClause(entityTable, branchIds, mainBranchId);
    const partyEntityWhere = scope === 'customers'
      ? buildPartyBranchAccessWhereClause('customer', entityTable, branchIds, mainBranchId)
      : buildPartyBranchAccessWhereClause('supplier', entityTable, branchIds, mainBranchId);
    let entityWhere = isAccountsScope ? accountEntityWhere.sql : partyEntityWhere.sql;
    const entityParams = isAccountsScope ? [...accountEntityWhere.params] : [...partyEntityWhere.params];

    // فلتر التصنيف للعملاء/الموردين فقط
    if (!isAccountsScope && (scope === 'customers' || scope === 'suppliers') && category) {
      entityWhere += ' AND category = ?';
      entityParams.push(category);
    }

    // في حالة نطاق الحسابات مع اختيار حساب رئيسي، نستخدم CTE لاستخراج شجرة الحسابات تحت هذا الحساب
    let useAccountSubtree = false;
    let rootAccountId = null;
    if (isAccountsScope && accountType) {
      const parsedId = parseInt(accountType, 10);
      if (!isNaN(parsedId) && parsedId > 0) {
        rootAccountId = parsedId;
        useAccountSubtree = true;
      }
    }

    let totalsQuery;
    let totalsParams;
    const accountLeafCondition = isAccountsScope ? ' AND COALESCE(is_parent, 0) = 0' : '';

    if (isAccountsScope && useAccountSubtree) {
      // تجميع حسب كل حساب داخل الشجرة (الحساب الأب وجميع الفروع)
      totalsQuery = `
        WITH RECURSIVE account_tree AS (
          SELECT id, code, name, is_parent
          FROM accounts
          WHERE id = ?
            AND ${buildSystemOrBranchWhereClause('accounts', branchIds, mainBranchId).sql}
          UNION ALL
          SELECT a.id, a.code, a.name, a.is_parent
          FROM accounts a
          JOIN account_tree at ON a.parent_id = at.id
          WHERE ${buildSystemOrBranchWhereClause('a', branchIds, mainBranchId).sql}
        ),
        entities AS (
          SELECT id, code, name
          FROM account_tree
          WHERE COALESCE(is_parent, 0) = 0
        ),
        sums AS (
          SELECT
            jl.account_id as entity_id,
            SUM(CASE WHEN jl.currency_type = 'ريال' OR jl.currency_type = 'ريال سعودي' OR jl.currency_type IS NULL OR jl.currency_type = '' THEN jl.debit ELSE 0 END) as cash_debit,
            SUM(CASE WHEN jl.currency_type = 'ريال' OR jl.currency_type = 'ريال سعودي' OR jl.currency_type IS NULL OR jl.currency_type = '' THEN jl.credit ELSE 0 END) as cash_credit,
            SUM(CASE WHEN jl.currency_type LIKE '%ذهب%' THEN jl.debit * (CAST(COALESCE(NULLIF(jl.karat,''), '21') AS REAL) / ?) ELSE 0 END) as gold_debit,
            SUM(CASE WHEN jl.currency_type LIKE '%ذهب%' THEN jl.credit * (CAST(COALESCE(NULLIF(jl.karat,''), '21') AS REAL) / ?) ELSE 0 END) as gold_credit,
            SUM(CASE WHEN jl.currency_type LIKE '%فضة%' THEN jl.debit * (CAST(COALESCE(NULLIF(jl.karat,''), '999') AS REAL) / ?) ELSE 0 END) as silver_debit,
            SUM(CASE WHEN jl.currency_type LIKE '%فضة%' THEN jl.credit * (CAST(COALESCE(NULLIF(jl.karat,''), '999') AS REAL) / ?) ELSE 0 END) as silver_credit
          FROM journal_entries je
          JOIN journal_lines jl ON je.id = jl.journal_id
          JOIN account_tree at ON jl.account_id = at.id
          WHERE jl.account_id IS NOT NULL
            AND ${journalBranchFilter.sql}
            AND (
              (je.source_type != 'opening'
                AND (? IS NULL OR je.date >= ?)
                AND (? IS NULL OR je.date <= ?)
              )
              OR
              (? = 1 AND je.source_type = 'opening'
                AND (? IS NULL OR je.date <= ?)
              )
            )
          GROUP BY jl.account_id
        )
        SELECT
          e.id as id,
          e.code as code,
          e.name as name,
          ROUND(COALESCE(s.cash_debit, 0), 2) as cash_debit,
          ROUND(COALESCE(s.cash_credit, 0), 2) as cash_credit,
          ROUND(COALESCE(s.cash_debit, 0) - COALESCE(s.cash_credit, 0), 2) as cash_balance,
          ROUND(COALESCE(s.gold_debit, 0), 3) as gold_debit,
          ROUND(COALESCE(s.gold_credit, 0), 3) as gold_credit,
          ROUND(COALESCE(s.gold_debit, 0) - COALESCE(s.gold_credit, 0), 3) as gold_balance,
          ROUND(COALESCE(s.silver_debit, 0), 3) as silver_debit,
          ROUND(COALESCE(s.silver_credit, 0), 3) as silver_credit,
          ROUND(COALESCE(s.silver_debit, 0) - COALESCE(s.silver_credit, 0), 3) as silver_balance
        FROM entities e
        LEFT JOIN sums s ON s.entity_id = e.id
        ORDER BY e.id
      `;

      totalsParams = [
        rootAccountId,
        ...buildSystemOrBranchWhereClause('accounts', branchIds, mainBranchId).params,
        ...buildSystemOrBranchWhereClause('a', branchIds, mainBranchId).params,
        gBase, gBase,
        sBase, sBase,
        ...journalBranchFilter.params,
        fromDate, fromDate,
        toDate, toDate,
        includeOpen,
        fromDate, fromDate
      ];
    } else {
      // السلوك الافتراضي (كل الحسابات أو العملاء/الموردين مع فلتر التصنيف)
      // في حالة الحسابات: استثناء حسابات العملاء والموردين لأنها تظهر في أقسامها الخاصة
      const excludeCustomerSupplierAccounts = isAccountsScope ? `
        AND id NOT IN (
          WITH RECURSIVE excluded_tree AS (
            SELECT id FROM accounts WHERE code IN ('114', '211')
            UNION ALL
            SELECT a.id FROM accounts a JOIN excluded_tree et ON a.parent_id = et.id
          )
          SELECT id FROM excluded_tree
        )
      ` : '';
      
      totalsQuery = `
        WITH entities AS (
          SELECT id${isAccountsScope ? ', code' : ''}, ${entityNameField} as name
          FROM ${entityTable}
          WHERE ${entityWhere} ${excludeCustomerSupplierAccounts}${accountLeafCondition}
        ),
        sums AS (
          SELECT
            jl.${entityIdField} as entity_id,
            SUM(CASE WHEN jl.currency_type = 'ريال' OR jl.currency_type = 'ريال سعودي' OR jl.currency_type IS NULL OR jl.currency_type = '' THEN jl.debit ELSE 0 END) as cash_debit,
            SUM(CASE WHEN jl.currency_type = 'ريال' OR jl.currency_type = 'ريال سعودي' OR jl.currency_type IS NULL OR jl.currency_type = '' THEN jl.credit ELSE 0 END) as cash_credit,
            SUM(CASE WHEN jl.currency_type LIKE '%ذهب%' THEN jl.debit * (CAST(COALESCE(NULLIF(jl.karat,''), '21') AS REAL) / ?) ELSE 0 END) as gold_debit,
            SUM(CASE WHEN jl.currency_type LIKE '%ذهب%' THEN jl.credit * (CAST(COALESCE(NULLIF(jl.karat,''), '21') AS REAL) / ?) ELSE 0 END) as gold_credit,
            SUM(CASE WHEN jl.currency_type LIKE '%فضة%' THEN jl.debit * (CAST(COALESCE(NULLIF(jl.karat,''), '999') AS REAL) / ?) ELSE 0 END) as silver_debit,
            SUM(CASE WHEN jl.currency_type LIKE '%فضة%' THEN jl.credit * (CAST(COALESCE(NULLIF(jl.karat,''), '999') AS REAL) / ?) ELSE 0 END) as silver_credit
          FROM journal_entries je
          JOIN journal_lines jl ON je.id = jl.journal_id
          WHERE jl.${entityIdField} IS NOT NULL
            AND ${journalBranchFilter.sql}
            AND (
              (je.source_type != 'opening'
                AND (? IS NULL OR je.date >= ?)
                AND (? IS NULL OR je.date <= ?)
              )
              OR
              (? = 1 AND je.source_type = 'opening'
                AND (? IS NULL OR je.date <= ?)
              )
            )
          GROUP BY jl.${entityIdField}
        )
        SELECT
          e.id as id,
          ${isAccountsScope ? 'e.code as code,' : ''}
          e.name as name,
          ROUND(COALESCE(s.cash_debit, 0), 2) as cash_debit,
          ROUND(COALESCE(s.cash_credit, 0), 2) as cash_credit,
          ROUND(COALESCE(s.cash_debit, 0) - COALESCE(s.cash_credit, 0), 2) as cash_balance,
          ROUND(COALESCE(s.gold_debit, 0), 3) as gold_debit,
          ROUND(COALESCE(s.gold_credit, 0), 3) as gold_credit,
          ROUND(COALESCE(s.gold_debit, 0) - COALESCE(s.gold_credit, 0), 3) as gold_balance,
          ROUND(COALESCE(s.silver_debit, 0), 3) as silver_debit,
          ROUND(COALESCE(s.silver_credit, 0), 3) as silver_credit,
          ROUND(COALESCE(s.silver_debit, 0) - COALESCE(s.silver_credit, 0), 3) as silver_balance
        FROM entities e
        LEFT JOIN sums s ON s.entity_id = e.id
        ORDER BY e.id
      `;

      totalsParams = [
        ...entityParams,
        gBase, gBase,
        sBase, sBase,
        ...journalBranchFilter.params,
        fromDate, fromDate,
        toDate, toDate,
        includeOpen,
        fromDate, fromDate
      ];
    }

    console.log('[get-all-entity-balances] Executing query with', totalsParams.length, 'params');
    const results = await tursoSync.queryAll(totalsQuery, totalsParams);
    console.log('[get-all-entity-balances] Results:', results?.length || 0, 'records');
    const entityIds = normalizeBranchIdList((results || []).map((item) => item?.id || item?.entity_id));
    if (entityIds.length) {
      const placeholders = entityIds.map(() => '?').join(', ');
      let metadataRows = [];
      if (scope === 'accounts') {
        metadataRows = await tursoSync.queryAll(`
          SELECT id,
                 COALESCE(branch_id, ${mainBranchId}) AS branch_id,
                 COALESCE((SELECT name FROM branches branch_lookup WHERE branch_lookup.id = COALESCE(accounts.branch_id, ${mainBranchId}) LIMIT 1), '') AS branch_name,
                 COALESCE((SELECT code FROM branches branch_lookup WHERE branch_lookup.id = COALESCE(accounts.branch_id, ${mainBranchId}) LIMIT 1), '') AS branch_code,
                 '' AS access_scope,
                 '' AS branch_names,
                 '' AS branch_codes,
                 0 AS branch_count
          FROM accounts
          WHERE id IN (${placeholders})
        `, entityIds);
      } else {
        const tableName = scope === 'customers' ? 'customers' : 'suppliers';
        const assignmentsTable = scope === 'customers' ? 'customer_branches' : 'supplier_branches';
        const ownerField = scope === 'customers' ? 'customer_id' : 'supplier_id';
        metadataRows = await tursoSync.queryAll(`
          SELECT p.id,
                 COALESCE(p.branch_id, ${mainBranchId}) AS branch_id,
                 COALESCE((SELECT name FROM branches branch_lookup WHERE branch_lookup.id = COALESCE(p.branch_id, ${mainBranchId}) LIMIT 1), '') AS branch_name,
                 COALESCE((SELECT code FROM branches branch_lookup WHERE branch_lookup.id = COALESCE(p.branch_id, ${mainBranchId}) LIMIT 1), '') AS branch_code,
                 COALESCE(p.access_scope, 'single') AS access_scope,
                 COALESCE(assignments.branch_names, '') AS branch_names,
                 COALESCE(assignments.branch_codes, '') AS branch_codes,
                 COALESCE(assignments.branch_count, 0) AS branch_count
          FROM ${tableName} p
          LEFT JOIN (
            SELECT ab.${ownerField} AS party_id,
                   COUNT(*) AS branch_count,
                   group_concat(COALESCE(b2.name, ''), ', ') AS branch_names,
                   group_concat(COALESCE(b2.code, ''), ', ') AS branch_codes
            FROM ${assignmentsTable} ab
            LEFT JOIN branches b2 ON b2.id = ab.branch_id
            GROUP BY ab.${ownerField}
          ) assignments ON assignments.party_id = p.id
          WHERE p.id IN (${placeholders})
        `, entityIds);
      }
      const metadataMap = new Map(metadataRows.map((row) => [Number(row.id) || 0, row]));
      results.forEach((item) => {
        const metadata = metadataMap.get(Number(item?.id || item?.entity_id) || 0);
        if (metadata) {
          item.branch_id = metadata.branch_id;
          item.branch_name = metadata.branch_name || '';
          item.branch_code = metadata.branch_code || '';
          item.access_scope = metadata.access_scope || '';
          item.branch_names = metadata.branch_names || '';
          item.branch_codes = metadata.branch_codes || '';
          item.branch_count = Number(metadata.branch_count || 0);
        }
      });
    }
    return { success: true, data: results };
  } catch (err) {
    console.error('[get-all-entity-balances] Error:', err);
    return { success: false, error: err.message };
  }
});

