// التحقق من كلمة مرور المطور (آمن - في الـ backend)
ipcMain.handle('verify-dev-password', async (event, password) => {
  const crypto = require('crypto');
  const inputHash = crypto.createHash('md5').update(password + 'BenAjlan_Salt_2025').digest('hex').substring(0, 32);
  const correctHash = crypto.createHash('md5').update('Rr2712021@#*' + 'BenAjlan_Salt_2025').digest('hex').substring(0, 32);
  return { success: inputHash === correctHash };
});

