ipcMain.handle('test-cloud-db-connection', async (_e, params) => {
  try {
    const { url, token } = params || {};
    if (!url || !token) {
      return { success: false, error: 'URL and token are required' };
    }
    if (!url.startsWith('libsql://')) {
      return { success: false, error: 'Invalid URL format. Must start with libsql://' };
    }
    
    // Try to connect using @libsql/client if available
    try {
      const { createClient } = require('@libsql/client');
      const client = createClient({
        url: url,
        authToken: token
      });
      
      // Test connection with a simple query
      await client.execute('SELECT 1');
      
      return { success: true, message: 'Connection successful' };
    } catch (libsqlError) {
      // If @libsql/client is not installed, just validate the format
      if (libsqlError.code === 'MODULE_NOT_FOUND') {
        // Module not installed - validate format only
        return { success: true, message: 'Connection format valid (libsql client not installed)' };
      }
      return { success: false, error: libsqlError.message };
    }
  } catch (error) {
    return { success: false, error: error.message };
  }
});

const cloudDbConfigPath = path.join(dataDir, 'cloud-db-config.json');
const cloudDbTokenPath = path.join(dataDir, 'cloud-db-token.json');

function readCloudDbConfigFile() {
  const config = readJsonFileSafe(cloudDbConfigPath, {});
  return (config && typeof config === 'object' && !Array.isArray(config)) ? config : {};
}

function writeCloudDbConfigFile(config) {
  writeJsonFileSafe(cloudDbConfigPath, config || {});
}

function readCloudDbTokenFile() {
  const tokenData = readJsonFileSafe(cloudDbTokenPath, {});
  return (tokenData && typeof tokenData === 'object' && !Array.isArray(tokenData)) ? tokenData : {};
}

function writeCloudDbTokenFile(token) {
  writeJsonFileSafe(cloudDbTokenPath, { token, savedAt: new Date().toISOString() });
}

function getCloudDbSettingsWithToken() {
  const config = readCloudDbConfigFile();
  const tokenData = readCloudDbTokenFile();
  if (tokenData?.token) {
    return { ...config, token: tokenData.token };
  }
  return config;
}

function readAssistantProviderSettingsFile() {
  const raw = readJsonFileSafe(assistantProviderSettingsPath, {});
  return aiAgent.normalizeProviderSettings(raw || {});
}

function mergeAssistantProviderSettingsFile(payload) {
  const existing = readAssistantProviderSettingsFile();
  const incoming = (payload && typeof payload === 'object' && !Array.isArray(payload)) ? payload : {};
  const merged = {
    ...existing,
    ...incoming,
  };
  if (!Object.prototype.hasOwnProperty.call(incoming, 'apiKey') || String(incoming.apiKey || '').trim() === '') {
    merged.apiKey = existing.apiKey || '';
  }
  return aiAgent.normalizeProviderSettings(merged);
}

function writeAssistantProviderSettingsFile(payload) {
  const normalized = aiAgent.normalizeProviderSettings(payload || {});
  writeJsonFileSafe(assistantProviderSettingsPath, normalized);
  return normalized;
}

const AUTO_SYNC_UNITS = new Set(['seconds', 'minutes', 'hours']);

function convertAutoSyncValueToSeconds(value, unit) {
  const numericValue = Number(value || 0);
  if (!Number.isFinite(numericValue) || numericValue <= 0) {
    return 30;
  }
  if (unit === 'hours') {
    return numericValue * 3600;
  }
  if (unit === 'minutes') {
    return numericValue * 60;
  }
  return numericValue;
}

function normalizeAutoSyncSettings(settings) {
  const unit = AUTO_SYNC_UNITS.has(settings?.unit) ? settings.unit : 'seconds';
  const rawValue = Number(settings?.value);
  const rawIntervalSeconds = Number(settings?.intervalSeconds);
  let value = Number.isFinite(rawValue) && rawValue > 0 ? rawValue : null;
  let intervalSeconds = Number.isFinite(rawIntervalSeconds) && rawIntervalSeconds > 0 ? rawIntervalSeconds : null;

  if (value === null && intervalSeconds !== null) {
    if (unit === 'hours' && intervalSeconds % 3600 === 0) {
      value = intervalSeconds / 3600;
    } else if (unit === 'minutes' && intervalSeconds % 60 === 0) {
      value = intervalSeconds / 60;
    } else {
      value = intervalSeconds;
    }
  }

  if (value === null) {
    value = 30;
  }

  intervalSeconds = convertAutoSyncValueToSeconds(value, unit);

  return {
    enabled: settings?.enabled === true,
    value,
    unit,
    intervalSeconds,
  };
}

function loadAutoSyncSettingsFromConfig() {
  const config = readCloudDbConfigFile();
  return normalizeAutoSyncSettings(config.autoSync || {});
}

function saveAutoSyncSettingsToConfig(settings) {
  const config = readCloudDbConfigFile();
  config.autoSync = normalizeAutoSyncSettings(settings || {});
  writeCloudDbConfigFile(config);
  return config.autoSync;
}

function getFallbackAutoSyncIntervalSeconds(settings) {
  const intervalSeconds = Number(settings?.intervalSeconds || settings?.value || 0);
  return Number.isFinite(intervalSeconds) && intervalSeconds > 0 ? intervalSeconds : 30;
}

function resolveAutoSyncSettingsPayload(payload, fallbackSettings = {}) {
  if (payload && typeof payload === 'object' && !Array.isArray(payload)) {
    return normalizeAutoSyncSettings({
      enabled: payload.enabled ?? fallbackSettings.enabled,
      value: payload.value ?? fallbackSettings.value,
      unit: payload.unit ?? fallbackSettings.unit,
      intervalSeconds: payload.intervalSeconds ?? fallbackSettings.intervalSeconds,
    });
  }

  if (payload === undefined || payload === null) {
    return normalizeAutoSyncSettings(fallbackSettings);
  }

  return normalizeAutoSyncSettings({
    ...fallbackSettings,
    enabled: true,
    intervalSeconds: Number(payload),
  });
}

function startPeriodicSyncWithBroadcast(intervalSeconds = 30) {
  const effectiveIntervalSeconds = getFallbackAutoSyncIntervalSeconds({ intervalSeconds });
  return tursoSync.startPeriodicSync(db, effectiveIntervalSeconds, (result) => {
    broadcastPeriodicCloudSyncResult(result, 'cloud-periodic');
  });
}

function broadcastPeriodicCloudSyncResult(result, source = 'cloud-periodic') {
  if (!tursoSync.isCloudMode() || Number(result?.changes || 0) <= 0) {
    return;
  }
  broadcastCloudDataUpdated({
    source,
    action: 'sync',
    tables: Array.isArray(result?.changedTables) ? result.changedTables : [],
    changes: Number(result?.changes) || 0,
    latestRows: result?.latestRows || {},
  });
}

async function runImmediatePeriodicCloudSync(source = 'cloud-periodic') {
  const result = await tursoSync.pullFromCloud(db);
  broadcastPeriodicCloudSyncResult(result, source);
  return result;
}

ipcMain.handle('save-cloud-db-settings', async (_e, params) => {
  try {
    const { url, token } = params || {};
    
    // Save URL to config file - preserve existing cloudMode
    let existingConfig = readCloudDbConfigFile();
    const config = { ...existingConfig, url, savedAt: new Date().toISOString() };
    writeCloudDbConfigFile(config);
    
    // Save token to separate secure file
    if (typeof token === 'string' && token.trim()) {
      writeCloudDbTokenFile(token.trim());
    }
    
    // Reinitialize Turso sync with new settings
    try {
      await tursoSync.initTursoClient();
      if (tursoSync.isSyncEnabled()) {
        await ensureCloudSchemaMatchesLocal(CLOUD_SYNC_TABLES);
      }
    } catch (e) {
      console.log('[TursoSync] Reinit after save:', e.message);
    }
    
    return { success: true };
  } catch (error) {
    return { success: false, error: error.message };
  }
});

