ipcMain.handle('set-cloud-mode', async (_e, enabled) => {
  try {
    const wantsCloudMode = Boolean(enabled);
    const wasCloudActive = tursoSync.isCloudMode();
    const wasSyncEnabled = tursoSync.isSyncEnabled();
    const autoSyncSettings = loadAutoSyncSettingsFromConfig();
    let finalPullResult = null;
    let initialSyncResult = null;

    if (!wantsCloudMode && wasCloudActive && wasSyncEnabled) {
      await clearCurrentCloudPresence();
    }

    if (!wantsCloudMode && wasCloudActive && wasSyncEnabled && autoSyncSettings.enabled) {
      tursoSync.stopPeriodicSync();
      stopCloudRealtimeEventPolling();
      finalPullResult = await tursoSync.pullFromCloud(db);
    }

    tursoSync.setCloudMode(wantsCloudMode);
    const savedMode = tursoSync.getSavedCloudMode();
    const isActive = tursoSync.isCloudMode();

    if (wantsCloudMode && isActive && autoSyncSettings.enabled) {
      try {
        initialSyncResult = await runImmediatePeriodicCloudSync('cloud-periodic');
      } catch (syncError) {
        initialSyncResult = { success: false, error: syncError.message };
        console.error('[Main] Initial auto sync on cloud mode activation failed:', syncError.message);
      }
      startPeriodicSyncWithBroadcast(autoSyncSettings.intervalSeconds || 30);
      console.log('[Main] Started periodic sync - CLOUD mode activated');
    } else {
      tursoSync.stopPeriodicSync();
      console.log('[Main] Stopped periodic sync - LOCAL mode activated');
    }

    if (wantsCloudMode && isActive) {
      await startCloudRealtimeEventPolling({ resetCursor: true });
      console.log('[Main] Started cloud realtime event polling');
    } else {
      stopCloudRealtimeEventPolling();
      lastCloudRealtimeEventId = 0;
    }

    return {
      success: true,
      cloudMode: savedMode,
      activeMode: isActive,
      connected: tursoSync.isSyncEnabled(),
      finalPullResult,
      initialSyncResult,
    };
  } catch (error) {
    return { success: false, error: error.message };
  }
});

