ipcMain.handle('assistant-chat', async (event, payload) => {
  try {
    const request = (payload && typeof payload === 'object' && !Array.isArray(payload)) ? payload : { message: payload };
    const providerSettings = readAssistantProviderSettingsFile();
    const currentUser = getAuthenticatedUserFromEvent(event);
    const marketSnapshot = buildLiveMarketSnapshot();
    const requestedCurrentBranch = request?.currentBranch && typeof request.currentBranch === 'object' && !Array.isArray(request.currentBranch)
      ? request.currentBranch
      : null;
    const requestedBranchScope = request?.branchScope && typeof request.branchScope === 'object' && !Array.isArray(request.branchScope)
      ? request.branchScope
      : null;
    const assistantScopeInfo = await resolveBranchScopeForRequest(event, {
      branchScope: requestedBranchScope?.mode || requestedBranchScope?.scope || 'branch',
      branch_id: requestedBranchScope?.branchId || requestedBranchScope?.branch_id || requestedCurrentBranch?.id || null,
    }, getDefaultMainBranchIdSync());
    const assistantCurrentBranchId = normalizePositiveId(
      requestedCurrentBranch?.id || assistantScopeInfo?.branchId || currentUser?.branch_id || currentUser?.default_branch_id,
      getDefaultMainBranchIdSync()
    ) || getDefaultMainBranchIdSync();
    const assistantBranchScope = {
      mode: assistantScopeInfo?.isAllBranches ? 'all' : 'branch',
      branchId: assistantCurrentBranchId,
      allowedBranchIds: normalizeBranchIdList(assistantScopeInfo?.allowedBranchIds || currentUser?.allowed_branch_ids || [assistantCurrentBranchId]),
    };
    const assistantCurrentBranch = {
      id: assistantCurrentBranchId,
      code: String(requestedCurrentBranch?.code || '').trim(),
      name: String(requestedCurrentBranch?.name || '').trim(),
    };
    const result = await aiAgent.handleMessage(request.message || '', {
      db,
      tursoSync,
      projectRoot: __dirname,
      providerSettings,
      currentUser,
      currentBranch: assistantCurrentBranch,
      branchScope: assistantBranchScope,
      marketSnapshot,
      history: Array.isArray(request.history) ? request.history : [],
      conversationState: request.conversationState && typeof request.conversationState === 'object' ? request.conversationState : null,
      routeHint: request.routeHint || 'auto',
      activeTabId: request.activeTabId || null,
      activeTabLabel: request.activeTabLabel || null,
      exportStatement: exportAssistantStatement,
    });
    return {
      success: result?.success !== false,
      route: result?.route || 'knowledge',
      reply: result?.reply || 'لم أتمكن من توليد رد مناسب حالياً.',
      actions: Array.isArray(result?.actions) ? result.actions : [],
      attachments: Array.isArray(result?.attachments) ? result.attachments : [],
      contacts: Array.isArray(result?.contacts) ? result.contacts : [],
      meta: result?.meta || null,
      classification: result?.classification || null,
      conversationState: result?.conversationState || null,
    };
  } catch (error) {
    return {
      success: false,
      route: 'knowledge',
      reply: error.message || 'حدث خطأ غير متوقع أثناء معالجة طلب المساعد.',
      actions: [{ type: 'open_provider_settings', label: 'إعدادات الاتصال بالمزوّد' }],
    };
  }
});

