const notificationSettingsPath = path.join(dataDir, 'notification-settings.json');

function getDefaultNotificationSettings() {
  return {
    enabled: true,
    salesInvoice: true,
    purchaseInvoice: true,
    receipt: true,
    voucher: true,
    journal: true,
    customer: true,
    supplier: true,
    opening: true,
    accounts: true,
    goldItems: true,
    users: true,
    companySettings: true,
    taxDeclaration: true,
    ordersFromUsers: true,
    ordersCompleted: true
  };
}

function normalizeNotificationSettings(settings) {
  return {
    ...getDefaultNotificationSettings(),
    ...(settings && typeof settings === 'object' && !Array.isArray(settings) ? settings : {})
  };
}

function extractNotificationRequest(payload) {
  if (payload && typeof payload === 'object' && !Array.isArray(payload)) {
    return {
      userId: payload.userId ?? null,
      settings: payload.settings ?? null,
    };
  }
  return { userId: null, settings: payload ?? null };
}

function loadNotificationSettings(userId = null) {
  const raw = readJsonFileSafe(notificationSettingsPath, null);
  if (raw && typeof raw === 'object' && !Array.isArray(raw) && (raw.version === 2 || raw.users || raw.defaults)) {
    const defaults = normalizeNotificationSettings(raw.defaults || {});
    const key = userId != null ? String(userId) : null;
    if (key && raw.users && typeof raw.users === 'object' && raw.users[key]) {
      return normalizeNotificationSettings({ ...defaults, ...raw.users[key] });
    }
    return defaults;
  }
  return normalizeNotificationSettings(raw || {});
}

function saveNotificationSettings(settings, userId = null) {
  try {
    const normalized = normalizeNotificationSettings(settings);
    if (userId != null) {
      const existingRaw = readJsonFileSafe(notificationSettingsPath, null);
      const baseConfig = (existingRaw && typeof existingRaw === 'object' && !Array.isArray(existingRaw) && (existingRaw.version === 2 || existingRaw.users || existingRaw.defaults))
        ? {
            version: 2,
            defaults: normalizeNotificationSettings(existingRaw.defaults || {}),
            users: (existingRaw.users && typeof existingRaw.users === 'object' && !Array.isArray(existingRaw.users)) ? existingRaw.users : {}
          }
        : {
            version: 2,
            defaults: normalizeNotificationSettings(existingRaw || {}),
            users: {}
          };
      baseConfig.users[String(userId)] = normalized;
      writeJsonFileSafe(notificationSettingsPath, baseConfig);
      return true;
    }
    writeJsonFileSafe(notificationSettingsPath, normalized);
    return true;
  } catch (e) {
    console.error('Error saving notification settings:', e.message);
    return false;
  }
}

ipcMain.handle('get-notification-settings', async (_e, payload) => {
  try {
    const { userId } = extractNotificationRequest(payload);
    const settings = loadNotificationSettings(userId);
    return { success: true, settings };
  } catch (error) {
    return { success: false, error: error.message };
  }
});

ipcMain.handle('save-notification-settings', async (_e, payload) => {
  try {
    const { userId, settings } = extractNotificationRequest(payload);
    const saved = saveNotificationSettings(settings, userId);
    return { success: saved };
  } catch (error) {
    return { success: false, error: error.message };
  }
});

