// Start/Stop periodic sync
ipcMain.handle('start-periodic-sync', async (_e, payload) => {
  try {
    const currentSettings = loadAutoSyncSettingsFromConfig();
    const requestedSettings = resolveAutoSyncSettingsPayload(payload, currentSettings);
    const settings = saveAutoSyncSettingsToConfig({
      ...requestedSettings,
      enabled: true,
      intervalSeconds: getFallbackAutoSyncIntervalSeconds(requestedSettings),
    });

    // لا تبدأ المزامنة الدورية إذا كان الوضع محلي
    if (!tursoSync.isCloudMode()) {
      console.log('[Main] start-periodic-sync skipped - LOCAL mode');
      return { success: true, skipped: true, reason: 'local_mode', settings };
    }

    let initialSyncResult = null;
    try {
      initialSyncResult = await runImmediatePeriodicCloudSync('cloud-periodic');
    } catch (syncError) {
      initialSyncResult = { success: false, error: syncError.message };
      console.error('[Main] Initial periodic sync failed:', syncError.message);
    }

    startPeriodicSyncWithBroadcast(settings.intervalSeconds || 30);
    return { success: true, settings, initialSyncResult };
  } catch (error) {
    return { success: false, error: error.message };
  }
});

ipcMain.handle('stop-periodic-sync', async (_e, payload) => {
  try {
    const currentSettings = loadAutoSyncSettingsFromConfig();
    const requestedSettings = resolveAutoSyncSettingsPayload(payload, currentSettings);
    const settings = saveAutoSyncSettingsToConfig({
      ...requestedSettings,
      enabled: false,
      intervalSeconds: getFallbackAutoSyncIntervalSeconds(requestedSettings),
    });

    tursoSync.stopPeriodicSync();
    return { success: true, settings };
  } catch (error) {
    return { success: false, error: error.message };
  }
});

